export const COMPENDIUM_VERITE_FLEAUX_ARTICLES = [{"id":"lore-plagues-cultes-vaagor","dataset":"verite-fleaux-focus","category":"Vérité","sourceCategory":"Vérité","title":"Cultes de V’Aagor — Longinus, Œil Blanc, Fontaine, Faux et Gouffre","source":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx","status":"canon_enrichi","rebuildV2":true,"tags":["Vérité","Fléaux","Cultes","Focus Fléaux 2026-09"],"loreBook":{"focusBatch":"fleaux-focus-2026-09-v1","focusSource":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx"},"navigation":{"group":"Corruption & Fléaux","groupOrder":60,"subgroup":"Cultes des Fléaux","subgroupOrder":30,"pageOrder":10},"sections":[{"id":"cult-1-l'ordre-de-longinus-histoire","title":"L’ordre de Longinus — Histoire","level":2,"blocks":[{"type":"p","style":"lore","text":"L’ordre de Longinus était un ordre de chasseurs Chrétiens. Lors de la « réforme des chasseurs », fusionnant les innombrables ordres en trois plus structurés, l’ordre de Longinus se refusa de se soumettre à l’ordre d’Arianwen. Le maître de l’ordre, Vicente VALERIO, en 1235, déclara posséder la lance de Longines, et vint l’offrir au Pape, Grégoire IX, il fut assassiné en chemin, l’Eglise ne voulant pas accepter de cadeau d’un ordre renégat, mais la relique ne fut pas retrouvée. Le second de VALERIO, Ivan AGUINALDO, déclara que le Pape était un « démon » et l’ordre se terra. Depuis, l’ordre a sombré dans une paranoïa et une psychose profonde, se sentant menacé par l’Eglise, chaque maitre a commencé à avoir des « révélations », le « saint martyr VALERIO » aurait parlé à AGUINALDO, lui révélant où retrouver la relique. Aguinaldo à son tour, fut canonisé par l’Ordre et son successeur eut des révélations sur le « démon papal » et comment trouver « le véritable héritier de Jesus » le « Pape dissimulé » et détenteur de la relique, que l’ordre appela par la suite « L’ombre-Pape ». L’Ombre-Pape se révéla à l’ordre et s’instaura comme son meneur aux alentours de 1288. Son visage est méconnu et les membres de la secte ignorent s’il s’agit du même homme depuis, puisque c’est un grand tabou dans l’ordre. L’ombre-Pape annonça qu’à la toute fin des années 1980, naitrait le nouveau Messie, le second enfant de Dieu, celui venu pour le Jugement Dernier. Depuis, l’ordre se prépare."}]},{"id":"cult-2-l'ordre-de-longinus-fonctionnement","title":"L’ordre de Longinus — Fonctionnement","level":2,"blocks":[{"type":"p","style":"lore","text":"L’ordre se structure assez simplement, à sa tête, l’Ombre-Pape, qui est un fragment du Fléau, il est entouré des Cardinaux. L’ordre possède des ombre-prêtres qui prêchent pour el culte et des ombre-templiers, qui sont les chasseurs du culte. C’est une secte extrêmement secrète qui passent par d’anciens religieux Chrétiens et de sectes associées pour se dissimuler derrière. Par exemple, à la dissolution de l’ordre des Saintes Lagunes, énormément d’anciens chevaliers-chasseurs ont été récupérés. Tout moine, nonne ou prêtre de l’Eglise Chrétienne réformée qui semble pouvoir être récupéré le sera et certains membres de l’Eglise actuelle sont, à leur insu, orientés par le Culte sombre qui profite des plus bas échelons pour s’insinuer. L’ordre est essentiellement implanté en Asie néanmoins, sa plus grande communauté était en Corée après la guerre."}]},{"id":"cult-3-l'ordre-de-longinus-figures","title":"L’ordre de Longinus — Figures liées","level":2,"blocks":[{"type":"p","style":"lore","text":"Voir la fiche de L’ombre-Pape."},{"type":"p","style":"lore","text":"Voir la fiche de Stephania Volkov."}]},{"id":"cult-4-la-secte-de-l'-il-blanc-histoire","title":"La secte de l’œil blanc — Histoire","level":2,"blocks":[{"type":"p","style":"lore","text":"On ignore quand le premier effisme s’est écrasé sur Terre, mais tout semble indiquer plusieurs millénaires. Attirés par une étrange gravité fluctuante, ces créatures obscures s’installèrent pour fonder une communauté. Décédant à cause de la gravité trop faible de la Terre, devenant rapidement malades, ils ont commencé à se replier sur leur foi et ont attiré V’Aagor. Rnael’Gem naquit ainsi, un fragment de V’aagor à l’apparence des Effismes. Meneur religieux, il enfonça dans une profonde corruption tous les effismes locaux, arrachant de leur dimension les femelles pour permettre, via ses ténèbres malsaines, de se matérialiser dans la même dimension que les mâles. Le culte n’a jamais vraiment été menaçant, tant il compte peu de représentants, mais chacun est une abomination supérieure d’une rare puissance et dont le seul but est d’éventrer l’Ombre-Monde. Les effismes de cet ordre qui n’ont pas été jeté dans l’Ombre-Monde sont précisément les femelles, et toutes possèdent des yeux blancs ou gris comme un rappel à leur couleur d’origine, d’où le nom de la secte."}]},{"id":"cult-5-la-secte-de-l'-il-blanc-fonctionnement","title":"La secte de l’œil blanc — Fonctionnement","level":2,"blocks":[{"type":"p","style":"lore","text":"Rnael’gem est un maitre de l’ordre très peu présent. Il n’a pas parfaitement conscience de sa nature de fragment de V’Aagor, la majorité du temps, il dort dans son tombeau et c’est son corps qui sert ses cultistes pour doter les « messagers » de pouvoirs. Les membres de la secte ne cherchent pas à corrompre des mortels, on ne peut pas devenir un effisme même s’il est une abomination, ainsi les « Sœurs » de la secte, puisqu’elles sont toutes des femmes, sont visuellement des nonnes, aux yeux gris, aux tatouages très sombres sur les bras et les jambes, un symbole de trou noir doté de tentacules est sur leur dos. Leur unique but est de trouver des Mages ou des Voyageurs pour déchirer l’Ombre-Monde. Les membres de la secte sont des manipulatrices assez polyvalentes, elles cherchent des « messagers », des victimes qu’elles dotent de pouvoirs temporairement pour trouver des Mages véritables et les ramener. L’ordre possède seulement trois couvents dans le monde : un en Autriche, un autre en Afrique du Sud et une aux Etats-Unis, près de Salem. La secte recrute un très grand nombre de sorciers, les « messagers », ils pensent être de la secte et recevoir une récompense s’ils réussissent à sacrifier un Mage capable d’éventrer l’ombre-monde, mais ils ne sont que de faibles et misérables pions. Les Mages ne s’y trompent pas d’ailleurs ils exécutent sur le champ les sorciers de la secte dès qu’ils en croisent, car la présence de « messagers » étouffe énormément la magie des sorciers servant les Mages."}]},{"id":"cult-6-la-secte-de-l'-il-blanc-figures","title":"La secte de l’œil blanc — Figures liées","level":2,"blocks":[{"type":"p","style":"lore","text":"Voir la fiche de Azaliah Springer."},{"type":"p","style":"lore","text":"Voir la fiche de Noah Brenneman."}]},{"id":"cult-7-la-fontaine-de-tenebres-histoire","title":"La « fontaine de ténèbres » — Histoire","level":2,"blocks":[{"type":"p","style":"lore","text":"Quand naquit Neeba, un vampire de pure lignée, cela faisait bien longtemps que le culte de « d’Osh’bawa » était installé chez les vampires du centre de l’Afrique à une époque où les hommes étaient encore peu savants. « Osh’bawa » n’est pas un dieu de la nuit, c’est la Force des Ténèbres, un concept plus puissant qu’une incarnation, un concept sans volonté propre comme en aurait un dieu et à la fois omnipotent puisque toutes les volontés qui existent sont siennes. C’est une force de l’intangible, de ce qui ne peut pas être vu ni touché. « La fontaine des ténèbres » est sa création, elle offre la toute-puissance aux êtres tangibles et visibles aux êtres de la lumière, elle leur offre les ténèbres, aux faibles elle offre la force, aux stupides elle offre le savoir, aux mortels elle donne l’immortalité et aux êtres vivants elle offre l’existence transcendante. Cette tradition a été portée par les descendants de Khinae qui étaient corrompus, ceux qui sacrifiaient à la fontaine en recevaient les dos et le sang. Ironiquement, les vampires de l’ « Oru ayeraye » sont donc les plus proches de la vérité dans leur croyance quant à l’origine des vampires. En revanche, ironiquement leur refus catégorique de croire en Arawn, ou Caïn, un fondateur unique met de côté l’implication d’Awan (Gahanath), qui est pourtant une figure incontournable de leur création."}]},{"id":"cult-8-la-fontaine-de-tenebres-fonctionnement","title":"La « fontaine de ténèbres » — Fonctionnement","level":2,"blocks":[{"type":"p","style":"lore","text":"Le culte est entièrement lié à la faction vampirique de de l’ « Oru ayeraye », il s’inspire d’un chamanisme assez simple, certains vampires qui sentent « la fontaine », c’est-à-dire la source des ténèbres sont formés comme « prêtres de Osh’bawa », cependant, il ne s’agit pas d’une classe sacerdotale au sein des vampires, n’importe quel membre de l’Oru déclarant sentir l’appel des ténèbres peut recevoir la formation. Son sang devient alors non plus un sang vampirique mais un sang « Oshirique », simplement de la « sombre-vérité », le vampire perd ses dons spécifiques du sang mais gagne en compétence télékinétique et en physique. Il devient dépendant de la « fontaine des ténèbres » et ne put plus s’alimenter que de personne consommant de la « Sombre-vérité », sorciers ou autres cultistes de V’Aagor donc. S’il s’alimente d’autre sang, il souffre de la soif plus que les autres vampires, plus vite, en revanche, il peut corrompre ses victimes aisément pour en faire des cultistes le temps de s’en nourrir. Un vampire « Oshirique » ne peut pas consommer son propre sang ou celui d’un autre vampire Oshirique, pas sans devenir possiblement une strygoï noire, une des pires abominations pouvant naitre des vampires, ne créature de deux à quatre mètres dégoulinant de ténèbres qui aspire les fluides vitaux de tout ce qui bouge tant qu’il faut nuit, s’enterre le jour et recommence dès la nuit tombée."}]},{"id":"cult-9-la-fontaine-de-tenebres-figures","title":"La « fontaine de ténèbres » — Figures liées","level":2,"blocks":[{"type":"p","style":"lore","text":"Voir la fiche de Neeba Ngubenani."},{"type":"p","style":"lore","text":"Voir la fiche de Olayinka Najja."}]},{"id":"cult-10-la-confrerie-de-la-faux-histoire","title":"La confrérie de la faux — Histoire","level":2,"blocks":[{"type":"p","style":"lore","text":"Sur Aèr, les confréries d’assassins sont nombreuses, particulièrement chez les elfes noirs. Forcément, les expatriés de ce peuple ont importé leurs factions avec eux Une de ces confréries a perduré, bien qu’elle ait changé de nom de nombreuses fois, elle a surtout été liée à une faux comme symbole, à la Mort. Pendant très longtemps, elle est restée solide et influente, ne recrutant que des descendants d’elfes noirs ou sylvains. Malgré une efficacité qui n’était pas à prouver, le roi élu, Obéron, acta qu’il fallait en finir avec ces groupes trop attachés à une ethnie, il était temps que tous les elfes ne se rassemblent et ne s’unissent, de renoncer à leurs différences pour se préserver tous ensemble de renoncer à des querelles inutiles pour faciliter une entente indispensable. Nerediath LISINDRITH, maitre de la confrérie n’en fut absolument pas convaincu, arguant qu’il s’agissait d’une manœuvre politique pour simplement renforcer la position des élus, précisément aucunement des elfes noirs, il essaya de se soulever contre ce racisme à peine dissimulé. La tentative se solda par la levée de la Chasse Fantastique, menée par la reine Titania, qui massacra absolument chaque membre de la confrérie et chaque partisan, réduisant drastiquement le nombre de descendants elfes noirs en quelques heures. Si, pour les elfes, s’arrêta là la rébellion de Nerediath, pour lui, ce ne fut que le commencement. Sauvé par V’Aagor, qui le posséda, il en devint une incarnation et reconstitua sa confrérie, indépendamment des autres elfes. Il récupéra les parias, les semi-elfes ignorant tout de la Vérité, les opposants politique aux élus, mais aussi des azménoriens ou même des nains, tout expatrié pouvant servir la confrérie."}]},{"id":"cult-11-la-confrerie-de-la-faux-fonctionnement","title":"La confrérie de la faux — Fonctionnement","level":2,"blocks":[{"type":"p","style":"lore","text":"La confrérie de la faux est une société secrète de crawlers, des voidrunners essentiellement (assassins), elle fonctionne globalement comme la Blanchisserie en vérité, elle pourvoie des missions, des informations, elle ajoute de l’armement et des « dons » à l’offre de la Blanchisserie. Les dons s’obtiennent par une conversion au culte sombre. Ici, on vénère Alyera Scytheri, la première reine elfe noire sur Aèr. Elle n’est pas une déesse, et n’est qu’un nom pour désigner V’Aagor en vérité ou plutôt, on vénère R’Gahanath, aussi nommée Awan ou Aklima (parfois Arawn), laquelle ressemble assez à la reine elfique. En échange de trois actes de foi, la confrérie accepte les membres et corrompt leur corps et leur âme à tout jamais. Nerediath peut dès lors les posséder et les sauver en agissant à leur place par ses prodigieux réflexes et son expérience du combat aussi bien qu’il peut les tuer d’un claquement de doigt. Ce lien avec le maitre de la confrérie, le « Père », est la source d’une infinie loyauté au sein des assassins la composant."}]},{"id":"cult-12-la-confrerie-de-la-faux-figures","title":"La confrérie de la faux — Figures liées","level":2,"blocks":[{"type":"p","style":"lore","text":"Voir la fiche de Neals Corvo."},{"type":"p","style":"lore","text":"Voir la fiche de Mirrissi."}]},{"id":"cult-13-le-gouffre-infini-histoire","title":"Le Gouffre infini — Histoire","level":2,"blocks":[{"type":"p","style":"lore","text":"Les Whurtens se divisèrent avec les complexe oppositions entre factions fantastiques. D’une part, les humains rejetaient les autres peuples, se pendant désormais originaires de la Terre, ils purgeaient les peuples exilés, venus, comme eux, il y a longtemps. D’autre part, les elfes avaient commencé à prendre une telle importance chez les exilés que nombre de nains se refusaient à suivre les directives du conseil des Anciens. Motsognir était le plus véhément, il ne voyait pas l’intérêt de s’acharner à vivre à la surface si la magie n’était plus accessible et si les ressources élémentaires pour la technologie étaient prises par les humains, ne voyant pas une paix possible il s’enfonça dans les souterrains avec ses alliés. Cependant, nombre d’abominations anciennes, rejetées des dieux s’y trouvaient. Les nains de profondeurs, les « Duergars » réapprenant comme leurs ancêtres d’Aèr à affronter le pire dans les tunnels, et le pire l’était bien plus encore que des hordes de gobelins, kweets ou nagas. La princesse Fredegonda naquit faible, frêle, son père, Motsognir ne la considéra jamais vu les abominations à repousser, elle était si faible que même pratiquer la magie lui abimait l’âme. Délaissée, elle fit le choix de passer dans l’Ombre-monde pour se gorger de magie, mais ce fut une décision stupide, elle en revint avec l’âme s’émiettant et le corps encore plus faible et malade. Méprisée par les siens, la lourde décision de la jeter loin de la communauté pour qu’elle ne corrompe pas les siens fut ordonné par son père, elle fut jetée dans « le gouffre infini ». Ce qu’ignorait Motsognir c’était que ce « gouffre » était une partie de V’aagor lui-même dont Frenegonda devint un fragment quand elle acheva de recevoir les ténèbres s’y trouvant. Plus forte que jamais elle obtint plus de victoires que son père sur les « Deimons », puisqu’elle pouvait leurs commander et en créer. Les Duergars rejetèrent ces traitres, se divisant encore mais « le gouffre infini » avait pris racine comme culte et Frenegonda chercha à l’exporter à la surface."}]},{"id":"cult-14-le-gouffre-infini-fonctionnement","title":"Le Gouffre infini — Fonctionnement","level":2,"blocks":[{"type":"p","style":"lore","text":"Le culte est très restreint, Frenegonda le dirige avec ses dix grands Deimons, des Ombres à forme de whurtens qu’elle a façonnés pour ne pas se sentir seule, ne faisant confiance à personne. Ces Ombres-whurtennes commandent aux prêtres du cultes, lesquels n’ont absolument aucun accès à Frenegonda, leur mission est de servir V’Aagor et ses intérêts. Pour cela ils doivent recruter des nains de la surface et les ramener ou bien trouver d’autres cultes de V’Aagor et les aider. Une subtilité est que Frenegonda cherche aussi à aider Thul, qu’elle sert autant que V’Aagor, les deux lui parlant et la naine pensant servir le même Dieu, n’arrivant pas à les différencier bien que certains ordres aillent à l’encontre des suivants. Ainsi, certains prêtres sont plus proches des cultes de V’Aagor et d’autres de ceux de Thul."}]},{"id":"cult-15-le-gouffre-infini-figures","title":"Le Gouffre infini — Figures liées","level":2,"blocks":[{"type":"p","style":"lore","text":"Voir la fiche de Fredegonda."}]}]},{"id":"lore-plagues-cultes-uxsharith","dataset":"verite-fleaux-focus","category":"Vérité","sourceCategory":"Vérité","title":"Cultes d’Ux’Sharith — Saintes Lagunes, Bellatheis et Grand Savoir","source":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx","status":"canon_enrichi","rebuildV2":true,"tags":["Vérité","Fléaux","Cultes","Focus Fléaux 2026-09"],"loreBook":{"focusBatch":"fleaux-focus-2026-09-v1","focusSource":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx"},"navigation":{"group":"Corruption & Fléaux","groupOrder":60,"subgroup":"Cultes des Fléaux","subgroupOrder":30,"pageOrder":20},"sections":[{"id":"cult-1-l'ordre-des-saintes-lagunes-histoire","title":"L’ordre des Saintes Lagunes — Histoire","level":2,"blocks":[{"type":"p","style":"lore","text":"L’ordre des Saintes Lagunes a été fondé par Aldebert de Vandrick, il était un cousin d’Otton Ier, le premier empereur du saint empire romain germanique. Aldebert fit noyer des sorcières qui avaient tué de braves guerriers lors d’orgies païennes, il décida de fonder un ordre de chevaliers pour traquer ces créatures tentatrices si puissantes. L’ordre n’était donc absolument pas destiné à glorifier Ux’Sharith mais trucider des sorcières, peu importait lesquelles. C’est en chassant les communautés de sorcières psycolors que l’ordre commença à se spécialiser, chercher de vraies méthodes autres que la noyade, petit à petit, les maîtres de l’ordre comprirent que la lutte était vaine, les multitudes de cultes des sorcières étaient si nombreux et chacune si difficile à traquer et abattre s’il fallait s’en remettre seulement à la foi. Petit à petit, l’ordre captura et utilisa des sorcières pour se traquer entre elle. Comme les pouvoirs ne se manifestaient pas chez les hommes, les chevaliers se sentaient libre des pires actes avec les sorcières, restant « purs » même si physiquement, les descendants de sorcières étaient d’extraordinaires athlètes. Une forme d’eugénisme débuta et ce qui était un ordre destiné à les éliminé devint une sorte de vaste réseau d’asservissement visant bien moins à les anéantir qu’à simplement contrôler les sorcières psycolors. Le culte d’Ux’sharith commença à revenir, les sorcières païennes expliquaient leurs pouvoirs comme étant la manifestation de la « lumière de la vie » que la « déesse-mère » leur conférait, l’Ordre fit une composition en vénérant un saint Archange de lumière que Lucifer aurait brisé par jalousie en plusieurs couleurs maudites que l’ordre aurait à rassembler."}]},{"id":"cult-2-l'ordre-des-saintes-lagunes-fonctionnement","title":"L’ordre des Saintes Lagunes — Fonctionnement","level":2,"blocks":[{"type":"p","style":"lore","text":"L’ordre des saintes Lagunes était un ordre de religieux chasseurs, très spécialisés. Le grand maitre commandait à des sénéchaux qui commandaient à des capitaines eux-mêmes commandant aux chevaliers. Les chevaliers avaient un « troupeau » de sorcières dressées qui constituaient un réseau, elles payaient leur chevalier pour ne pas être dénoncée et dénoncer toute forme de trace d’une sorcière non référencée. L’ordre possédait des orphelinats et des couvents pour éduquer ces jeunes femmes dans la foi Chrétienne et les préparer à servir l’ordre. Le modèle perdura jusqu’en 2020 où dans sa plus malsaine version, l’ordre faisait d’énormes bénéfices telle une secte plaçant ses agents et pratiquant l’esclavage moderne et la prostitution, allant jusqu’à organiser des mariages pour posséder un réseau toujours plus efficace. L’éveil de Sharith a totalement brisé le fonctionnement de l’ordre, mais le réseau demeure."}]},{"id":"cult-3-l'ordre-des-saintes-lagunes-figures","title":"L’ordre des Saintes Lagunes — Figures liées","level":2,"blocks":[{"type":"p","style":"lore","text":"Voir la fiche de Baldwin de Vandrick."},{"type":"p","style":"lore","text":"Voir la fiche de Rolf de Vandrick."},{"type":"p","style":"lore","text":"Voir la fiche de Kennisha Arnold."},{"type":"p","style":"lore","text":"Voir la fiche de Lidira."}]},{"id":"cult-4-la-secte-de-bellatheis-histoire","title":"La secte de Bellatheis — Histoire","level":2,"blocks":[{"type":"p","style":"lore","text":"Ux’Sharith n’a pas engendré que des sorcières psyscolor. Absolument obsédée sexuelle elle s’accoupla avec absolument tout ce qu’elle pouvait dans une débauche orgiaque inimaginable entre créature, minéraux, animé, inanimé… Elle n’était pas nommée « reine des fléaux » parce qu’elle était la compagne de V’Aagor mais bien parce qu’elle était son égale. La secte de Bellatheis est une secte de sorcières très différente des psycolors. Elles glorifiaient le caractère fertile d’Ux’Sharith et sa liberté. Elles s’offrirent aux khinae et aux loup-garous, aux animaux, cherchant à recréer le miracle que leur « déesse » accomplissait à engendrer avec tout. Jugées comme obscène et décadentes, elles furent traquées à travers les âges, cependant, elles obtinrent quelques capacités propres, notamment, « la porte des secrets »."}]},{"id":"cult-5-la-secte-de-bellatheis-fonctionnement","title":"La secte de Bellatheis — Fonctionnement","level":2,"blocks":[{"type":"p","style":"lore","text":"Ces cultistes d’Ux’Sharith sont aussi des héritières du sang garou. « La porte des secrets » est une capacité extrêmement redoutée puisqu’elle consiste à s’emparer de n’importe quel pouvoir d’un individu qui a inséré une partie de son corps dans leur intimité. En somme c’est une façon de « diviser » les pouvoirs d’une proie qui se ferait avoir par le caractère séducteur de ces prêtresses utilisant leur ascendance khinae pour pouvoir imiter au besoin des attributs physiques, leurs pouvoirs de Sharith complétant le coté immatériel des pouvoirs copiés. La maitresse fondatrice n’avait pas de nom, c’était une énième engeance de Sharith, elle se fit appeler bien plus tard Raghnaid MACCALMAIN. L’ordre cherche essentiellement une ascendance liée à Sharith ou aux loups-garous, c’est une condition indispensable, la « grande Orbe » est un artefact que l’ordre utilise pour le détecter. Les sorcières du culte sont formées pour chercher des créatures ou des individus aux pouvoirs rares ou intéressants. Ce sont donc des chasseurs surnaturels bien que leurs méthodes pour dévorer les pouvoirs soient plus qu’atypiques."}]},{"id":"cult-6-la-secte-de-bellatheis-figures","title":"La secte de Bellatheis — Figures liées","level":2,"blocks":[{"type":"p","style":"lore","text":"Voir la fiche de Raghnaid Maccalmain.."},{"type":"p","style":"lore","text":"Voir la fiche de Nora Shakir."}]},{"id":"cult-7-le-culte-du-grand-savoir-histoire","title":"Le culte du Grand Savoir — Histoire","level":2,"blocks":[{"type":"p","style":"lore","text":"Ux’Sharith était un fléau dont les principaux pouvoirs étaient de diviser, décomposer, quand V’aaagor était un fléau caractérisé par sa capacité à s’infiltrer et se mêler à toute chose. Un des cultes de Sharith diffèrent profondément des autres, c’est celui du « Grand Savoir ». Le culte fut créé par une sorcière psycolor durant l’empire d’Akkad, Ashlultum, en grande partie à cause de sa rivalité avec Enheduana, la fille du roi Sargon d’Akkad. En plus d’être la haute prêtresse dz Sin (dieu de la lune), Enheduana est l’écrivaine la plus ancienne de l’Histoire et était une Mage de la loge d’Ur. Face à l’importance des Mages religieux, Ashlutum n’avait pas de pouvoirs, écrasés par la présence de la Loge, elle était aussi bien politiquement étranglée qu’elle ne l’était magiquement, elle s’est donc enfoncée dans la quête de savoirs et, Instruite par Anahita, une Mage sans loge, elle pensait acquérir assez de techniques pour faire face à un Mage, toute Sorcière qu’elle était. Il n’en fut rien, Enheduana l’humilia à chaque tentative. Anahita se lassa d’Ashlutum, qui ne semblait pas réellement chercher à s’améliorer mais à surpasser sa rivale, abandonnée, la sorcière enchaina des erreurs politiques, pour finir par être bannie. Avec ses filles, elle resta en ermite quelques années avant d’être approchée par un incarnat de V’Aagor, qu’elle tua dès qu’elle réalisa de quelle nature il était, c’est ainsi qu’elle eut l’Illumination de Sharith. Elle décomposa le corps mais ne parvint à rien avec l’essence maléfique qui demeura sur le sol. Elle ne la comprenait pas et réalisa ce jour-là que si l’’invulnérabilité venait du « Secret », la « Vérité » apportait la victoire sur tout. Elle revint à Ur, et se prosterna devant la Loge des Mages suppliant de servir sa rivale jusqu’à sa mort, ce qu’elle fit. Ce qu’ignoraient les Mages c’était que les filles d’Ashlutum continuèrent son œuvre, compilant des tonnes de savoirs magiques puis, plus tard, alchimiques, scientifiques dans leur corps, sur leur peau, dans leurs yeux, le culte de sharith devenant un culte du Savoir, les psycolors parvinrent à utiliser les pouvoirs de leur créatrice tels qu’ils étaient à l’origine, les usant pour décomposer les choses. Le culte resta assez localisé dans les régions sémitiques jusqu’à l’expansion de l’Islam et fut alors emporté jusqu’en l’actuelle Espagne mais aussi dans l’empire Mongol."}]},{"id":"cult-8-le-culte-du-grand-savoir-fonctionnement","title":"Le culte du Grand Savoir — Fonctionnement","level":2,"blocks":[{"type":"p","style":"lore","text":"Ces cultistes d’Ux’Sharith sont des scientifiques, on les surnomme « Archilogomanciens » car ils ont le pouvoir de voir les mécanismes, de décomposer le fonctionnement des choses. Ils peuvent voir un corps comme s’il était écorché, une machine comme si elle était démontée, un pouvoir comme s’il était au ralenti, en quelques fractions de secondes, ils ont la connaissance instinctive des mécanismes de toute chose, et n’ont qu’à trouver une solution par leurs savoirs. Bien qu’ils étaient exclusivement des femmes à l’origine, ces cultistes ne sont plus sexistes, peu importe le genre, les pouvoirs qu’ils ont se manifestent pareillement même si les femmes peuvent avoir des pouvoirs de « psycogrey ». La grande prêtresse est Ana Diana de la Caza et ses plus proches serviteurs les frères Karamov."}]},{"id":"cult-9-le-culte-du-grand-savoir-figures","title":"Le culte du Grand Savoir — Figures liées","level":2,"blocks":[{"type":"p","style":"lore","text":"Voir la fiche de Ana Diana De la Caza."},{"type":"p","style":"lore","text":"Voir la fiche de Yegor Karamovich."},{"type":"p","style":"lore","text":"Voir la fiche de Yegor Karamovich."}]}]},{"id":"lore-plagues-cultes-vhodhal","dataset":"verite-fleaux-focus","category":"Vérité","sourceCategory":"Vérité","title":"Cultes de Vhodhal — Loge d’Écume et Sang d’Ivoire","source":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx","status":"canon_enrichi","rebuildV2":true,"tags":["Vérité","Fléaux","Cultes","Focus Fléaux 2026-09"],"loreBook":{"focusBatch":"fleaux-focus-2026-09-v1","focusSource":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx"},"navigation":{"group":"Corruption & Fléaux","groupOrder":60,"subgroup":"Cultes des Fléaux","subgroupOrder":30,"pageOrder":30},"sections":[{"id":"cult-1-la-loge-d'ecume-histoire","title":"La Loge d’écume — Histoire","level":2,"blocks":[{"type":"p","style":"lore","text":"A la fin du XVIIIème siècle, la Russie colonisa l’Alaska, commença à s’installer, plusieurs familles de Mages de différentes loges venant s’exiler là pour se cacher. Une famille, les Voroshilov, découvrit néanmoins un nœud prodigieux de magie, l’ignorant, ils commencèrent à forer le tombeau de Vhodhal’nact. Les ouvriers devenaient fous et la mine ne fut jamais fonctionnelle, mais les mages accédèrent à une griffe du fléau titanesque. Ils comprirent pourquoi les Wendigos étaient si nombreux dans la région et pourquoi tant de créature mourraient spontanément au-dessus de la mine, leur vie se faisant dévorer à distance. Les mages de la loge locale décidèrent de sceller magiquement le tombeau et de renoncer à l’immense puissance possible. En 1907 néanmoins, les Voroshilov qui étaient resté malgré l’achat de l’Alaska par les Etats-Unis, purgèrent la loge, ils avaient passé un pacte avec une entité servant le Fléau, en échange des Mageius qu’ils dévoraient grâce à la famine blanche, ils recevaient des dons, comme des miettes des mageius sacrifiés. Miluska Voroshilov, l’année suivante, dévora entièrement sa famille pour obtenir encore plus de dons. « La loge d’écume » est un nom que donna la Loge d’Anchorage pour désigner les Voroshilov, mais on ignore si depuis, il y a vraiment plus d’un vrai Mage dedans. Miluska reste la grande « prêtresse de la famine » et la présidente de cette « Loge », dont on ne sait pas vraiment si elle existe encore."}]},{"id":"cult-2-la-loge-d'ecume-fonctionnement","title":"La Loge d’écume — Fonctionnement","level":2,"blocks":[{"type":"p","style":"lore","text":"Le culte a Miluska Voroshilov à sa tête. Elle est prêtresse et est la seule à entendre désormais l’entité qui négocie pour « le chien des fléaux », elle ignore qui le fait, certainement pas le Fléau qu’elle ne prie ni même Siadara, Miluska ne sait pas, mais la voix est intelligible, claire et logique, elle ne ment jamais, elle n’est jamais en colère. Pour les cultistes, cette voix n’existe pas, c’est la seule folie de Miluska qui est en cause. Les cultistes sont des « sorciers de la famine », ils n’ont aucun pouvoir de base, ils n’ont, aléatoirement que des pouvoirs de leurs victimes, des gens ou des créatures sacrifiés sur l’autel du culte dont l’assassin reçoit une fraction de don, parfois un membre de l’assemblée en reçoit aussi. Ils ne peuvent pas arracher de pouvoir en tuant ailleurs que sur l’autel, ils sont assez faibles de fait, en termes de pouvoirs purs, cependant, ils sont tous des porteurs sains de la « famine blanche », ce qui fait qu’ils peuvent contaminer ceux touchés. Les rares cultistes à avoir un Mageius sont les prêtres, ils peuvent voler les pouvoirs d’autres mages ainsi sacrifiés, à un bien plus grand niveau que les simples cultistes."}]},{"id":"cult-3-la-loge-d'ecume-figures","title":"La Loge d’écume — Figures liées","level":2,"blocks":[{"type":"p","style":"lore","text":"Voir la fiche de Miluska Voroshilov."},{"type":"p","style":"lore","text":"Voir la fiche de le roi du givre."}]},{"id":"cult-4-le-sang-d'ivoire-histoire","title":"Le sang d’ivoire — Histoire","level":2,"blocks":[{"type":"p","style":"lore","text":"Siadara a toujours été en rivalité avec R’Gahanath, l’une participa à la création des vampires, l’autre à celle des Wendigos, cependant, une des deux lança une espèce bien plus efficace que l’autre. Jalouse de l’intelligence d’Awan (Gahanath) Siadara décida de créer ses propres vampires, ses premières tentatives furent de corrompre les khinae mais il n’en existait plus vraiment, et les rares khinae immortels qu’elle arriva à maudire se trucidèrent rapidement. Elle préféra se rabattre sur les vampires, afin de ruiner le jouet de sa rivale. La « famine blanche » était parfaite, elle pouvait se nourrir de « la vérité noire » et transformer les vampires, ces khinaeiens élegants et subtiles en de grosses brutes sauvages et stupides, cependant, les vampires eux-mêmes jugulèrent à chaque fois les épidémies. Siadara réalisa que tant que les plus pures lignées étaient épargnées, elle n’avait aucune chance d’affecter les vampires, elle jeta donc son dévolu sur un jeune époux de la plus noble princesse de la krovni, la fille de Gahanath en personne. En le corrompant lui, elle espérait avoir Hécate mais elle échoua. Cependant, le duc vampirique n’accepta pas d’être purgé et chercha un moyen de survivre, de garder sa conscience, il y parvint, devenant un « sang d’ivoire », un vampire qui n’en était plus vraiment un et qui, pour survivre devait se nourrir d’autre vampires."}]},{"id":"cult-5-le-sang-d'ivoire-fonctionnement","title":"Le sang d’ivoire — Fonctionnement","level":2,"blocks":[{"type":"p","style":"lore","text":"Les « sangs d’ivoire » sont un type de sang vampirique corrompu par Vhodhal’nact. Il s’agit aussi d’une secte malsaine pouvant prendre dans n’importe quelle société vampirique, bien qu’initialement, elle soit issue de la krovni. « Elfenbeinblut » est donc une faction qui se structure à très petite échelle comme les autres factions vampiriques, elle possède un roi au-dessus de tout. « Elfenbeinblut » prend les vampires avec le titre qu’ils avaient dans leur faction initiale, ainsi, cette faction n’a pas de duc, elle n’a pas vraiment de barons même, elle n’a souvent, au mieux, que des chevaliers, très temporairement puisqu’on les élimine très vite, le plus souvent, la faction récupère ce qu’elle peut et a donc bien plus de Moroï que de vrais vampires. Elle a encore plus de strygoî néanmoins car certains vampires véritables en deviennent à cause de la « famine blanche », en régressant. Il existe une reine, mais elle est endormie, pour être plus précis, Xinya MING, la reine de la faction « Shì hun zhe », a décapité la reine et a gardé sa tête, «l’ Elfenbeinblut » conserve le corps inanimé en espérant un jour retrouver le crane pour la ramener à la vie. Bien qu’ils ne craignent pas les mêmes choses que les vrais vampires, les vampires « blafards » comme ils sont appelés péjorativement par les autres, sont un peu plus faibles, ils résistent mieux mais sont plus idiots, car ils ont du mal à se contenir, ils ont de bons pouvoirs, pouvant dissiper ceux des autres, mais ils souffrent à chaque utilisation, hésitant bien plus à le faire, enfin, ils sont très contagieux, avec toutes les espèces, cependant, ils détruisent souvent les corps pour éviter que leurs victimes ne se relèvent en Wendigo et ne les dévorent. De fait, seuls les vampires les plus expérimentés dans cette faction trouvent un vrai sens à en faire partie, les autres sont souvent des parias ayant eu le choix entre joindre et mourir."}]},{"id":"cult-6-le-sang-d'ivoire-figures","title":"Le sang d’ivoire — Figures liées","level":2,"blocks":[{"type":"p","style":"lore","text":"Voir la fiche de Maximilian Valentin Von Stroheim."},{"type":"p","style":"lore","text":"Voir la fiche de Ryong Myung-Sook."}]}]},{"id":"lore-plagues-eden-gris","dataset":"verite-fleaux-focus","category":"Vérité","sourceCategory":"Vérité","title":"Le culte de l’Éden Gris","source":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx","status":"canon_enrichi","rebuildV2":true,"tags":["Vérité","Fléaux","Cultes","Focus Fléaux 2026-09"],"loreBook":{"focusBatch":"fleaux-focus-2026-09-v1","focusSource":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx"},"navigation":{"group":"Corruption & Fléaux","groupOrder":60,"subgroup":"Cultes des Fléaux","subgroupOrder":30,"pageOrder":40},"sections":[{"id":"lore-plagues-eden-gris-histoire","title":"Histoire","level":2,"blocks":[{"type":"p","style":"lore","text":"Durant le IVème Siècle avant notre ère, les premiers alchimistes chinois découvrirent la « métastasismancie », une forme de magie alchimique, un art étrange qui ne fonctionnait qu’entre les mains de quelques rares élus détenant des billes de nacre noire d’une nature méconnue. Les Mages de la loge la plus proche commencèrent à s’inquiéter que des sorciers autodidactes ne maitrisent des arts si puissants et après une purge nécessaire ils s’emparèrent des billes de nacre noire avant de découvrir qu’il s’agissait d’yeux d’abominations. La loge entière disparut en étant détruite par Mleeac quand le Fléau réalisa que ses cultistes avaient été tués, il trouva d’autres alchimistes et les laissèrent entretenir leurs recherches sur l’immortalité. Certains émettent même que le culte de l’Eden gris, tel qu’il fut nommé plus tard, a les mêmes racines que le taoïsme qu’il engendra. Le culte de Vhadhi se répandit à travers les siècles, les millénaires, suivant les savoirs alchimiques, les alchimistes de toutes les époques étaient souvent considérés avec un œil juge pour leurs croyances car le culte exerçait une influence certaine. Hélas, le culte survivait peu avec la proximité de Mages ou d’institutions religieuses trop fortes, il déclina donc sans pour autant disparaitre. C’est durant le XXème siècle qu’il fit son second âge d’or, la Science remplaça l’Alchimie et les théories comme l’Evolution, la Génétique et d’autres disciplines donnèrent de la force aux croyances du culte. Le rejet des Religions classiques mena également à l’ouverture sur d’autres croyances, avec l’essor de l’occultisme en addition, cela donna un culte très solide."}]},{"id":"lore-plagues-eden-gris-fonctionnement","title":"Fonctionnement","level":2,"blocks":[{"type":"p","style":"lore","text":"Le culte de l’Eden gris fonctionne comme une secte « classique », elle a un grand maitre du culte, servit par trois Eveillés, des prêtresses, toujours des femmes, et chaque croyant doit accomplir sept actes de fois annuellement, pendant sept ans avant d’accéder au rang d’Initié, s’il manque à un seul acte de foi, le croyant recommence tout, ceux qui abandonnent sont exécutés, un acte de foi que doit accomplir un de leur proches amis parmi les croyants. Le culte est secret mais ne demande jamais d’argent, pour se financer, il créer des richesses, telles que des diamants, de l’or ou des terre rares que les pratiques alchimiques permettent de créer en combinaisons des pouvoirs des prêtresses. Le culte est excessivement porté sur l’avenir, l’évolution et l’espoir, il n’est pas un sombre culte où on récite des psaumes obscurs en robe noir en attendant de se tremper dans du sang, il est bien plus trompeur, il aide les gens paumés et leur promet un avenir radieux dans cette vie mais aussi l’après￾vie. Ce qui n’est jamais évoqué, c’est que l’Eden gris est l’enfer de Lucifer où se trouve Vhadhi elle￾même et que les âmes vont se tordre, s’altérer, se diviser et changer éternellement là-bas."}]},{"id":"lore-plagues-eden-gris-figures","title":"Figures liées","level":2,"blocks":[{"type":"p","style":"lore","text":"Voir la fiche de Aristaeus."},{"type":"p","style":"lore","text":"Voir la fiche de Margareta Diaconescu."}]}]},{"id":"lore-plagues-mere-primordiale","dataset":"verite-fleaux-focus","category":"Vérité","sourceCategory":"Vérité","title":"La Mère Primordiale","source":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx","status":"canon_enrichi","rebuildV2":true,"tags":["Vérité","Fléaux","Cultes","Focus Fléaux 2026-09"],"loreBook":{"focusBatch":"fleaux-focus-2026-09-v1","focusSource":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx"},"navigation":{"group":"Corruption & Fléaux","groupOrder":60,"subgroup":"Cultes des Fléaux","subgroupOrder":30,"pageOrder":50},"sections":[{"id":"lore-plagues-mere-primordiale-histoire","title":"Histoire","level":2,"blocks":[{"type":"p","style":"lore","text":"Avant de s’écraser sur Terre, Shaoggith écumait la galaxie. Enorme astéroïde aux millions de tentacules dotés de dents, elle était une titanesque forme de vie dont les écailles semaient la corruption. Sur un monde, elle a corrompu une espèce reptilienne et l’a fait constamment dégénérer. C’est cette espèce, stable à l’origine qui donna bien plus tard les Mo’sen, Chez’zons et Xe’wens à cause de la corruption, ces espèces pouvant encore dégénérer et se diviser en quelques siècles, de manière anarchique. Elle s’est finalement écrasée sur Terre et y demeura. Pendant des millions d’années, les créatures reptiliennes dans la galaxie la vénérèrent d’instinct, avant de trouver son tombeau, la Terre. c’est par sa seule présence que tant de Mo’sen se concentrent sur Terre et cherchent à changer le climat, poussés par le culte de la « mère primordiale » à leur insu. En effet, le culte est influant dans toute la galaxie mais sa force n’a pas d’égale sur Terre. Li’loth, la plus ancienne Mo’senne en vie en est la preuve, ayant subi plus de quatre « cycles » de mutation de Shaoggith, lui donnant son apparence si étrange."}]},{"id":"lore-plagues-mere-primordiale-fonctionnement","title":"Fonctionnement","level":2,"blocks":[{"type":"p","style":"lore","text":"Le culte est dirigé par la haute prêtresse, Li’Loth. Elle commande à neuf « maîtres des abominations » des prêtres qui ont la charge de cultiver les plus terrifiantes créatures engendrées par Shaoggith ou son influence, des monstres parfois titanesques tel que Krerath, la fille de Li’loth, qui aurait inspiré Godzilla. Si krerath n’est pas la seule créature imposante, elle reste la plus terrible de l’arsenal du culte après les armes technologiques. Le culte cherche ses partisans essentiellement dans les rangs extraterrestres. Toutefois, il est au courant de l’existence des dragons, même si les membres du culte doutent que des elfes et des nains existes, celle des dragons est une certitude, eux-aussi sont assez recherchés. Le culte connait également l’existence des autres cultes de Fléaux, un de ses objectif est de les anéantir, car pour le Culte, ils ne sont que des sectes malsaines alors que le culte est l’UNIQUE religion possible. Le culte recrute aussi parmi les humains, qui sont alors progressivement mutés."}]},{"id":"lore-plagues-mere-primordiale-figures","title":"Figures liées","level":2,"blocks":[{"type":"p","style":"lore","text":"Voir la fiche de Leona Elliott."},{"type":"p","style":"lore","text":"Voir la fiche de Shy Krerath."}]}]},{"id":"lore-plagues-sombre-culte","dataset":"verite-fleaux-focus","category":"Vérité","sourceCategory":"Vérité","title":"Le Sombre Culte","source":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx","status":"canon_enrichi","rebuildV2":true,"tags":["Vérité","Fléaux","Cultes","Focus Fléaux 2026-09"],"loreBook":{"focusBatch":"fleaux-focus-2026-09-v1","focusSource":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx"},"navigation":{"group":"Corruption & Fléaux","groupOrder":60,"subgroup":"Cultes des Fléaux","subgroupOrder":30,"pageOrder":60},"sections":[{"id":"lore-plagues-sombre-culte-histoire","title":"Histoire","level":2,"blocks":[{"type":"p","style":"lore","text":"Thul a écumé l’espace durant des millions d’années, expulsé après un combat face à d’autres Fléaux, Il était notamment l’ennemi de celle qui créa les ombres Wolféennes, ce Fléau a été divisé et donné naissance à V’Aagor qui fut envoyé à travers le Néant poursuivre Thul sur Terre. Thul s’est assez vite mis à faire émerger des « thuliens » des formes de vies similaires aux Mollusques, chaque graine semée sur les mondes visités en engendra afin de corrompre et anéantir l’Evolution, la Création. Thul n’est qu’un Fléau, il est intrinsèquement lié au Temps, il cherche à le figer, à anéantir ce qui change, ce qui bouge, c’est pourquoi les dons qu’il cède sont souvent l’immortalité ou l’infinie connaissance, comme pour figer ceux qui commettent l’erreur de s’en remettre à lui. Sur Terre, c’est son besoin d’instaurer des espèces incapables d’évoluer et toutes similaires qui poussèrent les dieux à le combattre. Toutefois, le « sombre culte » débuta assez tôt quand il dota d’intelligence ses créatures. Tout aurait pu s’achever, les créatures s’enfonçant dans les abysses mais les Azménoriens vinrent sur Terre, ils l’ignorèrent mais leurs vaisseaux emportèrent des mollusques microscopiques et c’est eux qui créèrent les ancêtres des rocréens ainsi et de nombreux peuples aliens. Thul se gorgea de la résonnance créée entre les « Thuliens » terrestres et ceux dans l’univers, n’ayant qu’à offrir du savoir à ses pions. Cependant, plus d’une fois ses cultes et ses empires furent anéantis. Sur Terre, Thul commença à se réveiller d’un long sommeil quand le continent de Mu se souleva des flots, appelant alors ses anciens serviteurs à venir le libérer."}]},{"id":"lore-plagues-sombre-culte-fonctionnement","title":"Fonctionnement","level":2,"blocks":[{"type":"p","style":"lore","text":"Le sombre culte a pour structure d’avoir une abomination majeure à sa tête, elle offre à un ou plusieurs grands cultistes des rites, des sacrifices et une mission. Les cultistes, presque toujours humains, sont progressivement métissés avec les peuples des abominations. Un des objectifs des « Thuliens » est d’obtenir le sang royal des Atlantes pour créer une forme d’Anté-Christ des Thuliens qui pourrait libérer leur « Divinité » de sa prison."}]},{"id":"lore-plagues-sombre-culte-figures","title":"Figures liées","level":2,"blocks":[{"type":"p","style":"lore","text":"Voir la fiche de « Dagon »."},{"type":"p","style":"lore","text":"Voir la fiche de Telipinu."},{"type":"p","style":"lore","text":"Voir la fiche de R’Sheraag."},{"type":"p","style":"lore","text":"Voir la fiche de Dsherra'neth."},{"type":"p","style":"lore","text":"Voir la fiche de Olla Berwick."},{"type":"p","style":"lore","text":"Voir la fiche de Peste des vases."},{"type":"p","style":"lore","text":"Voir la fiche de Grim."}]}]}] as Array<Record<string, any>>;
export const COMPENDIUM_VERITE_FLEAUX_ENRICHMENTS = [{"targetId":"verite-v7-six-fleaux-sources-rupture","section":{"id":"fleaux-focus-contexte","title":"Focus Fléaux — nature générale, hiérarchie et rapport au Néant","level":2,"blocks":[{"type":"p","style":"lore","text":"2035, Vos cauchemars vous obsèdent, la voix dans votre esprit est si forte que vous en oubliez des choses essentielles, vous commencez à oublier ce que vous faites, chaque jour, au travail, vous perdez de votre conscience, chaque nuit, vous commencez à vous retrouver dans d’étranges lieux… Ils vous appellent et vous n’y pouvez rien, ils sont si puissants et si influents que votre conscience s’effrite à la seule idée de les approcher, ils sont si attirants que votre esprit se déchire à la seule envie de les joindre… ils sont les Dieux des Abominations, ils sont les ennemis de tout, ils sont les déchets d’une guerre si ancienne qu’elle est même inconnue des dieux… ce sont les Fléaux."},{"type":"p","style":"lore","text":"Un Fléau Ancien est une entité dont on ne sait pas grand-chose, elles sont apparues pendant la guerre entre les Puissances Anciennes ou possiblement après, elles sont des agrégats plus ou moins incohérents et déséquilibrés de l’énergie, de la matière et des volontés laissées par les Puissances et leurs légions. Aucun Fléau Ancien ne peut se créer depuis ce temps, mais certains ne s’éveilleront que dans le futur, d’autres sont déjà éveillés et déjà détruits. Les véritables soucis sont les Fléaux qui demeurent. On ne peut pas résumer un Fléau Ancien à une nature, une forme et des pouvoirs, chacun est absolument différent et si ancien qu’il peut avoir changé de nature drastiquement depuis son éveil. Une constante avec eux est toutefois que les créatures mortelles sont incapables de les différencier des « Dieux » tant ils sont puissants et dotés de connaissances infinies, presque toujours, ils ont des cultes les vénérant. Sur Terra Umbra, les Fléaux ont été réveillé d’un long sommeil par les Dieux à l’insu de ces derniers, c’est pourquoi il y a eu des guerres meurtrières et une lutte acharnée pour détruire et sceller le plus d’entre eux. Outre les « Fléaux Anciens », il existe les « Fléaux supérieurs », qui sont des créations des premiers. On ne peut pas les considérer comme les « enfants » des Fléaux Anciens, car le mépris, l’indifférence et parfois même l’hostilité entre eux rend tout lien filial improbable, beaucoup de « Fléaux supérieurs » ont juste été créé par la causalité, parce qu’un « Fléau Ancien » était trop ou pas assez puissant, une nouvelle entité s’est formée, parce que deux « Fléaux Anciens » ont convergé, un « Fléau supérieur » est né et ainsi de suite. On peut ensuite désigner les « Fléaux inférieurs » ou « Abominations supérieures », qui sont les créations conscientes ou du moins utilisées par les « Fléaux anciens ». Il s’agit de créatures préexistantes ou entièrement conçues qui sont absolument pourries par l’essence des Fléaux et bien souvent les servent corps et âme par nature. Les « Fléaux » ne sont pas de véritables « Dieux », ils peuvent octroyer énormément plus de pouvoirs aux mortels, cependant, ce ne se fera jamais sans les altérer, au mieux, un mortel verra son esprit se tordre, se déchirer et n’être que des lambeaux de folie, au pire, c’est le corps qui se déforme et s’anime, seul, pendant que l’esprit, intact est conscient des atrocités commises avant de se tordre et se déchirer jusqu’à l’annihilation. Un point important sur la nature des Fléaux est qu’elle renvoie le plus souvent ses engeances au Néant, les Fléaux ne servent pas le Néant, pas consciemment, mais comme ils en sont issus en grande partie, tout ce qui les concerne, « eux-mêmes » aussi bien que leurs « abominations », fini presque toujours par l’annihilation totale. Ils en ont pleinement conscience et cherchent très souvent à s’en prémunir, cependant, les forces de la Création, précisément par cette nature néantiste, font tout pour ne jamais les accepter, ne voulant pas être corrompus par ce destin inéluctable."}]}},{"targetId":"regles-verite-v7-corruption-integrite-bascule","section":{"id":"fleaux-focus-corruption","title":"Focus Fléaux — corruption des mortels et annihilation","level":2,"blocks":[{"type":"p","style":"lore","text":"Un Fléau Ancien est une entité dont on ne sait pas grand-chose, elles sont apparues pendant la guerre entre les Puissances Anciennes ou possiblement après, elles sont des agrégats plus ou moins incohérents et déséquilibrés de l’énergie, de la matière et des volontés laissées par les Puissances et leurs légions. Aucun Fléau Ancien ne peut se créer depuis ce temps, mais certains ne s’éveilleront que dans le futur, d’autres sont déjà éveillés et déjà détruits. Les véritables soucis sont les Fléaux qui demeurent. On ne peut pas résumer un Fléau Ancien à une nature, une forme et des pouvoirs, chacun est absolument différent et si ancien qu’il peut avoir changé de nature drastiquement depuis son éveil. Une constante avec eux est toutefois que les créatures mortelles sont incapables de les différencier des « Dieux » tant ils sont puissants et dotés de connaissances infinies, presque toujours, ils ont des cultes les vénérant. Sur Terra Umbra, les Fléaux ont été réveillé d’un long sommeil par les Dieux à l’insu de ces derniers, c’est pourquoi il y a eu des guerres meurtrières et une lutte acharnée pour détruire et sceller le plus d’entre eux. Outre les « Fléaux Anciens », il existe les « Fléaux supérieurs », qui sont des créations des premiers. On ne peut pas les considérer comme les « enfants » des Fléaux Anciens, car le mépris, l’indifférence et parfois même l’hostilité entre eux rend tout lien filial improbable, beaucoup de « Fléaux supérieurs » ont juste été créé par la causalité, parce qu’un « Fléau Ancien » était trop ou pas assez puissant, une nouvelle entité s’est formée, parce que deux « Fléaux Anciens » ont convergé, un « Fléau supérieur » est né et ainsi de suite. On peut ensuite désigner les « Fléaux inférieurs » ou « Abominations supérieures », qui sont les créations conscientes ou du moins utilisées par les « Fléaux anciens ». Il s’agit de créatures préexistantes ou entièrement conçues qui sont absolument pourries par l’essence des Fléaux et bien souvent les servent corps et âme par nature. Les « Fléaux » ne sont pas de véritables « Dieux », ils peuvent octroyer énormément plus de pouvoirs aux mortels, cependant, ce ne se fera jamais sans les altérer, au mieux, un mortel verra son esprit se tordre, se déchirer et n’être que des lambeaux de folie, au pire, c’est le corps qui se déforme et s’anime, seul, pendant que l’esprit, intact est conscient des atrocités commises avant de se tordre et se déchirer jusqu’à l’annihilation. Un point important sur la nature des Fléaux est qu’elle renvoie le plus souvent ses engeances au Néant, les Fléaux ne servent pas le Néant, pas consciemment, mais comme ils en sont issus en grande partie, tout ce qui les concerne, « eux-mêmes » aussi bien que leurs « abominations », fini presque toujours par l’annihilation totale. Ils en ont pleinement conscience et cherchent très souvent à s’en prémunir, cependant, les forces de la Création, précisément par cette nature néantiste, font tout pour ne jamais les accepter, ne voulant pas être corrompus par ce destin inéluctable."}]}},{"targetId":"verite-v7-six-fleaux-sources-rupture","section":{"id":"fleaux-focus-mloxol-v'aagor","title":"Dossier détaillé — Mloxol V’Aagor","level":2,"blocks":[{"type":"p","style":"lore","text":"Roi des fléaux"},{"type":"p","style":"lore","text":"Nom de la Réalité : ??? Nom de la Vérité : Mloxol V’Aagor Age : « ??? ans » - ???? ans Affiliations : « Créatures » Nationalité d’origine : ??? Ethnie réelle : Fléaux Personnages liés :"},{"type":"p","style":"lore","text":"Mloxol est le « roi des fléaux », un titre qui n’a aucun sens, en vérité, puisque sur les 7 fléaux majeurs, il n’a jamais commandé qu’à trois autres dont Ux’Sharith, « la reine des fléaux », qu’il soumettait de force sans jamais avoir un ascendant véritable sur son esprit. Ce surnom lui était essentiellement donné par les Dieux, car il était l’un des trois fléaux les plus puissants et le plus avide de pouvoir. C’était un être extrêmement ambitieux et dangereux, son apparence d’origine était une masse informe similaire à du pétrole bouillonnant, pouvant devenir liquide aussi bien que dur comme du diamant, sans yeux ni bouche, son corps serpentait le long des parois, recouvrant et assimilant tout de son corps, toute ombre créé par l’exposition de son corps à une lumière était son corps, pouvant donc se démultiplier à l’infini mais finissant toujours par fusionner. N’ayant ni organe ni réelle consistance s’il le désirait, il n’était qu’un amas de matière noire soumis à une volonté malsaine. Quand Lilith fit découvrir les plaisirs charnels à Ux-Sharith, il en devint un grand amateur lui aussi et insémina sa « reine », hélas, il ne perdait pas de pouvoir contrairement à elle. Il entreprit de corrompre tous les êtres vivants, certains lui attribuent les « deimons », ces ombres-vivantes qui ne seraient que des fragments de sa tentative de règne, certains pensent qu’il est le premier fléau à avoir corrompu les Khinaes qui donnèrent les vampires, sa nature obscure pouvant être l’origine de leur caractère ténébreux, on pense aussi que sa nature liée à la matière noire le relie aux effismes terriens. Belial et Lucifer furent les seuls capables de l’enfermer dans une prison de feu et de lumière où son existence-même ne pouvait exister, telle la théorie du chat de Schrodinger, il n’est donc ni mort ni vivant ou plus précisément, tant que sa prison demeure, il n’existe plus mais, en même temps, il existe forcément si sa prison demeure pour le contenir. Des fragments du Fléau demeurent partout dans le monde, mais sans sa volonté, ces fragments sont à la fois son essence et à la fois d’autres entités, par exemple, il y a l’Ombre-Pape qui agit pour le ramener sans pour autant être lui. L’archange Gabrielle a déjà essayé de l’utiliser, mais fit corrompre un ange par l’essence du Fléau, ne se risquant pas à l’être elle-même. Mloxol peut toutefois parler à ses cultistes, il aurait annoncé son retour prochain, grâce à Ux’Sharith, mais rien ne semble indiquer qu’elle n’ait la même volonté, bien au contraire, toutefois, il n’a jamais précisé si c’était de gré ou de force…"}]}},{"targetId":"verite-v7-six-fleaux-sources-rupture","section":{"id":"fleaux-focus-ux'sharith-bellatheis","title":"Dossier détaillé — Ux’Sharith Bellatheis","level":2,"blocks":[{"type":"p","style":"lore","text":"Reine des fléaux"},{"type":"p","style":"lore","text":"Nom de la Réalité : Alisa SVALISDOTTIR Nom de la Vérité : Ux'sharith Bellatheis Age : « ??? ans » - ???? ans Affiliations : « Créatures » - « Chasseurs » Nationalité d’origine : Islandaise Ethnie réelle : Fléaux Personnages liés :"},{"type":"p","style":"lore","text":"Ux’Sharith était un fléau s’étant écrasé sur Terre après la guerre entre les légions, résidu de leur puissance, elle détruisait la lumière aussi bien que la magie en les décomposant. Créature de destruction, elle commandait à Vhodhal’nact'ruet C'thath vhadhi, deux fléaux d’une puissance similaire et était soumise\" « au roi des fléaux » : Mloxol v'aagor. Invulnérable, aucun dieu ne parvenait à la vaincre, Lucifer ou même Belial, elle brisait leurs pouvoirs, véritable complément de V’Aagor, elle ne se divisait pas, elle divisait ce qui l’entourait comme un prisme décomposant la lumière. C’est Lilith qui se chargea d’elle. Lilith n’usa d’aucun pouvoir, elle vint juste à elle pour la servir, humblement, lui façonner un corps plus humain, touchée, Sharith tomba amoureuse de lilith et usa de plus en plus du corps offert, découvrant la luxure, forçant lilith à faire des corps pour ses deux congénères. Au gré des orgies de Fléaux, elle engendra des myriades de créatures, renforçant les troupes des Fléaux, mais lilith avait gagné, chaque engeance de Sharith emportait de sa puissance avec elle, la créature immonde était si fertile qu’elle s’épuisa sans s’en rendre compte, s’emprisonnant dans le corps conçu pour la retenir. Lilith la tua et chercha à emporter son esprit dans son enfer, mais horrifiée par la trahison, Sharith brisa son esprit pour se réfugier en chaque descendante, explosant son âme, puis chaque descendante se cacha alors et engendra elle-même des myriades de descendantes, dissimulant ainsi l’esprit du fléau. En 2020, un grand tournoi au sein de l’Académie visait à établir le niveau des étudiantes psycolors, Allisa SVALISDOTTIR, se révéla posséder l’esprit de Sharith et dévora les pouvoirs de toutes les étudiantes présentes, avant d’anéantir l’ordre des Saintes Lagunes et traquer les sorcières psycolors à travers le monde, n’en gardant qu’une poignée singulière. Profondément marquée par la trahison de son premier amour,elle ne se sentit pas de se venger ni reprendre sa vie de fléau, se voyant comme une déesse, l’égale d’Elynea ou Belial, elle vise à purger le monde de sa propre espèce, les Fléau, pour racheter son passé, plus particulièrement, exterminer V’Aagor, son ancien maitre et plus terrible Fléau sur Terre bien que « l ’immondice Abyssale » K'thuhuth'lul l’ait possiblement surpassé. A gré des chasses, elle assimile néanmoins la souffrance de son ancien compagnon, mais elle n’est pas dupe, tôt ou tard, quelque chose finira par arriver, il souffre mais pas sans avoir un plan."}]}},{"targetId":"verite-v7-six-fleaux-sources-rupture","section":{"id":"fleaux-focus-vhodhal'nact'ru","title":"Dossier détaillé — Vhodhal’nact’ru","level":2,"blocks":[{"type":"p","style":"lore","text":"La famine véritable"},{"type":"p","style":"lore","text":"Nom de la Réalité : ??? Nom de la Vérité : Vhodhal’nact'ru Age : « ??? ans » - ???? ans Affiliations : « Créatures » Nationalité d’origine : ??? Ethnie réelle : Fléaux Personnages liés :"},{"type":"p","style":"lore","text":"Vhodhal est un fléau essentiellement issu du chaos et du néant. Il dévore absolument tout ce qui l’entoure, l’animé, l’inanimé, le matériel et même l’immatériel, c’est un véritable dévoreur acharné de tout ce qu’il perçoit. Les quatre yeux de Vhodhal voient quelque chose de différent chacun, l’un voit « les formes », l’autre voit « le temps », un troisième voit « l’énergie » et le dernier voit « la volonté » de ce qui l’entoure, il ne peut néanmoins se concentrer que sur un seul œil à la fois, les autres n’étant que secondaires jusqu’à ce qu’il ait dévoré ce qu’il a perçu comme son repas. Perpétuellement affamé, malgré une intelligence monumentale c’était le plus bestial de tous les fléaux majeurs, seule Ux’sharith parvenait à le faire cesser ses chasses, elle en était la seule maitresse. « Chien de la reine », c’est ce que signifie Vhodhal’nact dans la langue spécifique des fléaux terrestres, en effet, bien que sa puissance pût effrayer plus encore les dieux anciens que celle d’ux￾Sharith, il lui était entièrement obéissant, le nourrissant de son énergie écrasante, elle l’avait dressé. Sa famine était contagieuse, surnommée « famine liquide » ceux qui sont contaminés salivent un mucus blanchâtre et collant qui peut dissoudre pierre ou acier une fois que l’eau de cette salive est évaporée. Peu de cultes secrets l’honorent, mais il s’est fait glorifier néanmoins au plus fort du règne d’ux-sharith, comme un sous-culte à cette dernière. Il était la poubelle des fléaux, celui qu’on nourrissait par les ennemis sans valeur. Sa nature même était la destruction, son odeur était celle d’ozone et de souffre, une puanteur faisant tousser des kilomètres avant qu’il n’arrive. Il a de très nombreuses engeances ressemblant à des limaces dont la tête possède deux tentacules pour ramener à leur bec tranchant leurs proies, elles sécrètent le mucus blanc de la famine liquide par tout leur corps. Il fut tué par Mammon, non sans mal puisqu’il dévorait sa propre mort puis la trame temporelle où il le tuait, le dieu ancien le tuant en boucle jusqu’à ce qu’il ne soit aidé par Rae’kath, la Vala’eraï, pourtant soumise à V’Aagor, la créature élémentaire préférant préserver la stabilité terrestre en détruisant un être capable de dévorer le temps. Il n’est pas parfaitement mort, son corps immense demeure au nord de l’Alaska, d’où seraient apparu les premiers Wendigos, ces revenants affamés."}]}},{"targetId":"verite-v7-six-fleaux-sources-rupture","section":{"id":"fleaux-focus-c'thath-vhadhi","title":"Dossier détaillé — C’Thath Vhadhi","level":2,"blocks":[{"type":"p","style":"lore","text":"Le nœud de la causalité"},{"type":"p","style":"lore","text":"Nom de la Réalité : ??? Nom de la Vérité : C’Thath Vhadhi Age : « ??? ans » - ???? ans Affiliations : « Créatures » Nationalité d’origine : ??? Ethnie réelle : Fléaux Personnages liés :"},{"type":"p","style":"lore","text":"C’Thath Vhadhi était la quatrième des fléaux alliés, soumise à Mloxol V’Aagor elle était la plus discrète de ces quatre Fléaux majeurs. Vahdhi était un Fléau issu des entrelacs de causalité, ce sont les dieux qui la réveillèrent, en structurant leurs forces et leur organisation, elle éventra la croute terrestre pour sortir, tellement énorme qu’elle déversa des tonnes de lave qu’elle avait sur elle. Tout ce qu’elle regarde change intrinsèquement de fonction, elle donne un but, une raison d’exister à toute chose, mais ce n’est pas une véritable déesse du destin, c’est un entrelacs de causalités, cela signifie qu’elle mêle les destins et les fonctions, mais de manière anarchique, sans grand dessein divin derrière, c’est une essence chaotique absolue et glaciale. Son propre corps n’est qu’un tas de nœuds de fibres plus ou moins géantes, telle une grappe de racines plus longues qu’une montagne au sommet de laquelle un minuscule buste humanoïde toise le monde d’un visage bleuté sans émotion. Elle n’a jamais véritablement été vaincue, les dieux se sont rendus compte une fois les autres fléaux enfermés ou tués qu’elle était tourte aussi dangereuse pour eux. Elle n’est ni destructrice ni invasive, alors pour les espèces vivantes, elle était la moins menaçante, en revanche, face à un dieu, un être particulièrement forgé par l’énergie, cherchant à s’attacher à un « Attribut », elle est d’une redoutable dangerosité puisqu’elle peut donner un attribut de son choix au dieu l’affrontant, elle est capable de créer ces « attributs flottants » et de les greffer, mais aucun dieu n’a envie de devenir le dieu « de la faiblesse et de la coprophagie » ou bien « le dieu lécheur de poussière » et c’est un moindre mal car elle peut aussi bien les changer d’une nature divine à une nature de Fléau. C’est Elynea qui s’occupa de l’enfermer, après la guerre contre les enfers, du moins après avoir réussi installer le Paradis, elle a attaqué les cultes qui restaient, et le culte de Vhadi était l’un des plus puissants puisque le Fléau accordait une nouvelle vie à ceux sacrifiant quelque chose de suffisant, le Fléau changeant la personnalité et les dons de ceux qui la vénèrent. Elynea l’enferma après un combat monumental dans les souterrains, la divine créature lumineuse fut maintes fois réduite à des statuts immondes et méprisables, mais elle se refusa de fuir, affrontant le Fléau, même déesse de la vase, mortelle et malade, car elle réalisa rapidement que Vhadhi ne savait simplement pas se défendre autrement et n’avait jamais eu besoin de tuer. Elle l’emprisonna dans l’enfer de Lucifer, afin d’accentuer l’humiliation pour l’ancien dieu de la lumière désormais déchu."}]}},{"targetId":"verite-v7-six-fleaux-sources-rupture","section":{"id":"fleaux-focus-gajh'-shaoggith","title":"Dossier détaillé — Gajh’Shaoggith","level":2,"blocks":[{"type":"p","style":"lore","text":"La mère des Fléaux"},{"type":"p","style":"lore","text":"Nom de la Réalité : Tia Maria VERA Nom de la Vérité : Gajh’Shaoggith Age : « ??? ans » - ???? ans Affiliations : « Créatures » - Nationalité d’origine : Mexicaine Ethnie réelle : Fléaux Personnages liés : Tiamandra VECELLIO"},{"type":"p","style":"lore","text":"Gajh’Shaoggith est le troisième des grands Fléaux Anciens. Elle ne servait ni la reine ni le roi des dieux, à l’instant du titanesque Fléau des profondeurs, elle était indépendante. Dans sa forme la plus usuelle c’est une forme d’hydre dont on ne peut différencier les têtes et les queues, une immense titanesque sphère de tentacules se finissant par ders têtes reptiliennes bardées de dents. Elle adorait les crevasses et les canyons et chaque écaille, dent, chaque bout de peau qu’elle y laissait commençait à s’animer, elle devint le premier fléau que les dieux cherchèrent à véritablement anéantir, les hordes de créatures la suivant ravageant tout pour la nourrir. Sa première défaite ne fut pas simple, Belial, Abigor et Alabor s’alliant toutes les trois pour la noyer, l’ensevelir et faire fondre la pierre sur elle. Hélas, le Fléau Gajh’ shaoggith se réveilla en Mésopotamie bien longtemps après. Sa première action fut de se faire fertilisée par un dragon ancien nommé Shorolth, le dupant en prenant la forme d’une dragonne. Elle accoucha d’atrocités reptiliennes et inspira le mythe de Tiamat dont elle apprécie le nom. Le dieu Baal et l’archange Michael rivalisèrent en essayant de réitérer l’exploit des trois grandes déesses d’antan, mais ils échouèrent lamentablement, Caïn s’en mêla lui aussi, mais là encore, cela ne fut pas suffisant. Une fois le prince dévoré, le dieu et l’archange s’allièrent. Le fils de Michael, un nephilim fut créé pour surveiller la dépouille de la créature, ses descendants donnèrent la lignée de George de Lydda, un clan de chasseurs spécifiquement dédiés à la traque des « enfants de Tiamat » Cependant, Shaoggith ne fut que démembrée, elle ne fut pas tuée. Son esprit s’est façonné un corps humain depuis. Elle a pour but de fusionner avec Tiamandra VECELLIO, l’actuelle porteuse de son « corps », l’armure occulte « Nahfr», car elle semble incapable de toucher son propre corps depuis."}]}},{"targetId":"verite-v7-six-fleaux-sources-rupture","section":{"id":"fleaux-focus-k'thuhuth'lul","title":"Dossier détaillé — K’thuhuth’lul / Thul","level":2,"blocks":[{"type":"p","style":"lore","text":"Le Fléau de Lovecraft"},{"type":"p","style":"lore","text":"Nom de la Réalité : Cthulhu Nom de la Vérité : K'thuhuth'lul Age : « ??? ans » - ???? ans Affiliations : « Créatures » Nationalité d’origine : ??? Ethnie réelle : Fléaux Personnages liés : ? ?"},{"type":"p","style":"lore","text":"Voire le mythe de Cthulhu. Informations Vérité : K'thuhuth'lul est un fléau qui se forma à l’extérieur de la Terre, il fut arraché à sa dimension par des rocréens primitifs sur leur planète, il y a plusieurs centaines de millions d’années Sa présence extrêmement mutagène quand elle ne tue pas est si effrayante qu’il rend fou à distance, sans même qu’on ne le voit ni ne sache qu’il est présent. Extrêmement radioactif, il est à l’origine d’énormément de nouvelles formes de vies dans les profondeurs, hélas, souvent difformes. Il était le pire ennemi de V’Aagor, c’est un de leur affrontements qui poussa les dieux véritablement débuter la guerre contre les Fléaux. Chez les dieux, il était l’ennemi d’Alabor, sa présence n’étant pas que mutagène, il altérait jusqu’aux éléments, jusqu’aux atomes, changeant l’eau et sa composition, ainsi, il y a 380 à 360 millions d’années, la grande extinction du Dévonien est clairement du fait d’Alabor pour tenter d’anéantir Thul et ses innombrables créations que sa seule présence engendrait. Les scientifiques même en 2035 ont énormément de preuve que le niveau de la mer changeait énormément à cette période, ignorant qu’il s’agissait d’assèchement et d’inondations pour purger la Terre. Cette guerre entre Alabor et Thul mena à ce que les « fées », les esprits de la Terre, ne se divisent, certaines se ralliant à la déesse, comme le cas d’Amphitrite, d’autres s’y opposèrent et finirent corrompus et altérés, souvent dévorés par l’impitoyable titan vert. Les cultes de Thul ont continué même en 2035, même s’il a fini par être enfermés dans l’immense cité, non pas de R’Lyeh, mais la capitale de Mu que fondèrent les créatures le servant il y a des millions d’années. Les Atlantes dérobèrent ce continent immergé hélas et les grandes cités sous-marines du Pacifique, ils réalisèrent leur erreur trop tard, sous le grand palais du roi Kyriak, la tombe de Thul est désormais à l’air libre bien qu’il y sommeille encore. Dans son sommeil, Thul souffla souvent des images et des récits, mais aucun humain ne fut plus réceptif que H.P. Lovecraft."}]}},{"targetId":"verite-v7-delanial-pere-ombre","section":{"id":"fleaux-focus-delanial","title":"Dossier détaillé — Delanial","level":2,"blocks":[{"type":"p","style":"lore","text":"Le dieu de l’Ombre-Monde"},{"type":"p","style":"lore","text":"Nom de la Réalité : Bob SMITH Nom de la Vérité : Delanial Age : « ??? ans » - ???? ans Affiliations : « Créatures » Nationalité d’origine : ??? Ethnie réelle : ??? Personnages liés : ? ?"}]}},{"targetId":"verite-v7-delanial-pere-ombre","section":{"id":"fleaux-focus-pere-ombre","title":"Le Père de l’Ombre — histoire et fonctionnement","level":2,"blocks":[{"type":"p","style":"lore","text":"Delanial essaya d’instruire les Voyageurs afin qu’ils ne soutiennent les dieux. Les savoirs qu’il enseigna furent utilisés bien plus tard pour les combattre. Les Dives créèrent un culte au « Démiurge Obscur », le « Père de l’Ombre » et nombreux furent les autres ombres tels que les Deimons à l’adopter, refusant de vénérer les Dieux Anciens. Plus Delanial éliminait des Ombres le vénérant pur juguler le culte, plus leur colère contre les dieux s’intensifia face à cette purge honteuse et plus le culte se renforça."},{"type":"p","style":"lore","text":"Il n’y a pas de vrai fonctionnement, chaque Ombre gère ses croyances dans « le Père des Ombres » comme elle l’entend. On sait aussi que certains Vampires passant dans l’Ombre-Monde ont vu Delanial et le considère comme Arawn, le père des Vampires. Certains Vala’erai ou Atlantes pensent que le « vieux solitaire » est le Créateur en personne, le Démiurge de leurs croyances."}]}},{"targetId":"lore-hunters-confreries","section":{"id":"fleaux-focus-ordres-chasse","title":"Ordres de Chasse passés sous influence des Fléaux","level":2,"blocks":[{"type":"p","style":"lore","text":"L’Ordre de Longinus, ancien ordre de Chasseurs chrétiens, a refusé la réforme qui devait l’absorber dans l’ordre d’Arianwen avant de devenir le masque d’une influence de V’Aagor."},{"type":"p","style":"lore","text":"L’Ordre des Saintes Lagunes constitue un autre héritage de Chasse devenu inséparable de l’histoire d’Ux’Sharith et des Psycolors. Les dossiers complets sont conservés dans Corruption & Fléaux."}]}},{"targetId":"verite-v7-vampires-civilisation-cours-sangs","section":{"id":"fleaux-focus-fontaine-tenebres","title":"La Fontaine des Ténèbres et l’héritage oshirique","level":2,"blocks":[{"type":"p","style":"lore","text":"Le dossier Fléaux rattache la Fontaine des Ténèbres à l’histoire de Neeba Ngubenani et des Oru Ayeraye. Le culte complet est détaillé dans les Cultes de V’Aagor."}]}},{"targetId":"verite-v7-vampires-civilisation-cours-sangs","section":{"id":"fleaux-focus-sang-ivoire","title":"Le Sang d’Ivoire","level":2,"blocks":[{"type":"p","style":"lore","text":"Le Sang d’Ivoire apparaît dans le dossier de Vhodhal comme une tradition vampirique touchée par la Famine Blanche. Son histoire complète reste regroupée dans les Cultes de Vhodhal."}]}},{"targetId":"verite-extrals-mosens-detail","section":{"id":"fleaux-focus-mere-primordiale-reptile","title":"Mère Primordiale et Shaoggith","level":2,"blocks":[{"type":"p","style":"lore","text":"Le dossier Fléaux relie une partie du réseau à la Mère Primordiale et à Gajh’Shaoggith ; ces éléments relèvent de la Vérité et sont détaillés dans la page dédiée au culte."}]}}] as Array<Record<string, any>>;
export const COMPENDIUM_VERITE_FLEAUX_EXISTING_PNJ_SOURCES = [{"id":"pnj-fleaux-focus-anastasia-vargas-awan-aklima-anastasia-vargas","dataset":"verite-fleaux-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Anastasia VARGAS / Awan / Aklima","source":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Fléaux","Focus Fléaux 2026-09","Fléau supérieur","« Créatures »"],"pnj":{"completeness":"detailed","real_name":"Anastasia VARGAS / Awan / Aklima","nom_verite":"R’Gahanath","race":"Fléau supérieur","age":"« 30 ans » - ???? ans","origine":"Bulgare","statut":"« Créatures »","affiliations":"« Créatures »","relations":["Caïn","Rae’kath","Hécate SKOTIA"],"identity_keys":["Anastasia VARGAS / Awan / Aklima","Anastasia Vargas","R’Gahanath"]},"loreBook":{"focusBatch":"fleaux-focus-2026-09-v1","focusSource":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx"},"sections":[{"id":"fleaux-focus-dossier","title":"Dossier — Focus Fléaux","level":2,"blocks":[{"type":"p","style":"Normal","text":"Fille de V’Aagor"},{"type":"p","style":"Normal","text":"Nom de la Réalité : Anastasia VARGAS Awan Aklima Nom de la Vérité : R’Gahanath Age : « 30 ans » - ???? ans Affiliations : « Créatures » Nationalité d’origine : Bulgare Ethnie réelle : Fléau supérieur"}]},{"id":"fleaux-focus-verite","title":"Informations Vérité — Focus Fléaux","level":2,"audience":"mj","blocks":[{"type":"p","style":"Normal","text":"Mloxol v'aagor profita de la prétention de Rae’Kath une Vala’Erai de la mort et du temps, mais aussi de l’amitié profonde qu’elle avait pour lui pour assimiler la nature de la créature élémentaire. Immunisé à ses pouvoirs malgré l’immense maitrise qu’elle en avait, elle ne put l’empêcher d’agir à sa guise et se fit même contraindre à l’obéissance. De leur union naquit « R’Gahanath » « L’ombre du Temps » en langue des Fléaux. Une créature aussi malfaisante que son géniteur, dont elle est à la fois une création et à la fois une fraction. C’est elle qui s’occupa de corrompre les Khinae, les attirant, les séduisant et créant progressivement les ancêtres des vampires à l’insu des dieux, dissimulée entre es époques, préservant les Khinae de la mort en les enfermant dans l’ombre, ses deux natures : ombre et éternité. Des millénaires plus tard, elle fut la seule femme qui parvint à séduire Caïn, sous le nom d’Awan, elle l’utilisa, lui, le fils de Belial, la reine des dieux, pour façonner une marque s’inscrivant si profondément dans l’âme qu’elle conférait sa nature à n’importe quel corps. Appelée « marque de Caïn », elle devint une arme pour créer des vampires même à partir d’un sang très dilué de Khinae. Quand Caïn s’en rendit compte, il était bien trop tard, il avait créé quelque chose d’encore pire et se jura de la tuer s’il la retrouvait. Fuyant à sa mère et son premier amant, Gahanath n’a jamais cessé d’œuvrer pour son père, d’autant plus quand elle réalisa qu’il ne se libérerait jamais, devenant une simple source d’invulnérabilité pour elle, car tant qu’il serait emprisonné, elle pourrait puiser en lui pour exister quoi qu’il lui arrive, elle le réalisa en étant envoyée au Néant par Delanial, l’Archimaitre de l’ombre-Monde, réapparaissant spontanément par la Causalité, V’Aagor existant encore, elle existait et existerait aussi jusqu’à sa libération.. Elle est la créatrice de Dragoy SKOTIALOV, le roi de la Krovni et la mère d’Hécate SKOTIA, la probable future reine si son père était tué. Elle est extrêmement sûre d’elle et se sait surpuissante, elle affiche un éternel amusement face aux gens, qu’elle ne méprise pas mais ne peut pas vraiment respecter tant ils sont éphémères."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}],"legacyTargetId":"pnj-083-anastasia-vargas","navigation":{"group":"Corruption & menaces","groupOrder":80,"subgroup":"Fléaux & figures de Rupture","subgroupOrder":10,"pageOrder":500}},{"id":"pnj-fleaux-focus-ombre-pape-valentino-sombra-valentino-sombra","dataset":"verite-fleaux-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Ombre-Pape -Valentino SOMBRA","source":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Fléaux","Focus Fléaux 2026-09","Abomination","« Créatures »"],"pnj":{"completeness":"detailed","real_name":"Ombre-Pape -Valentino SOMBRA","nom_verite":"Absariath’V’Aagor","race":"Abomination","age":"« ??? ans » - ???? ans","origine":"???","statut":"« Créatures »","affiliations":"« Créatures »","relations":[],"identity_keys":["Ombre-Pape -Valentino SOMBRA","L’ombre-Pape","Absariath’V’Aagor"]},"loreBook":{"focusBatch":"fleaux-focus-2026-09-v1","focusSource":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx"},"sections":[{"id":"fleaux-focus-dossier","title":"Dossier — Focus Fléaux","level":2,"blocks":[{"type":"p","style":"Normal","text":"Maître des Abominations"},{"type":"p","style":"Normal","text":"Nom de la Réalité : Ombre-Pape -Valentino SOMBRA Nom de la Vérité : Absariath’V’Aagor Age : « ??? ans » - ???? ans Affiliations : « Créatures » Nationalité d’origine : ??? Ethnie réelle : Abomination"}]},{"id":"fleaux-focus-verite","title":"Informations Vérité — Focus Fléaux","level":2,"audience":"mj","blocks":[{"type":"p","style":"Normal","text":"« Valentino » n’est clairement pas un humain, c’est même une entité qu’on ne peut définir absolument comme étant un « être vivant », il s’agit plutôt d’une « essence de causalité », un reflet de la volonté de Mloxol V’Aagor, et pourtant il ne s’agit pas non plus de son maitre, simplement de l’émanation de sa volonté à revenir à la vie. Il possède seulement une forme humaine pour ce qu’il montre, ses pouvoirs sont équivalents à ceux d’un Mage très anciens et ses compétences physiques sont similaires à ceux d’un roi vampire, c’est une « Ombre », un « deimon » créé par le Fléau, même si sa naissance est causale et non volontaire, V’Aagor ignore qui est Absariath, il ne le considère pas comme existant, pourtant Absariath sait tout de son « maitre », son « père », qui n’est que le « Tout » dont il est issu, une « simple » écharde de volonté qui a été perdue. S’il est si puissant, c’est parce qu’Absariath puise dans tous les pouvoirs existants pour se façonner, il consume également les « Autres », les autres émanations de V’Aagor, qui, comme Absariath, naissent spontanément. Dans sa quête de pouvoir, Absariath tenta de s’emparer des dons d’Ux’Sharith, il est le père véritable de Catalina de la CAZA notamment, s’étant adonné à la reproduction, poussé par un instinct inédit. Il règne sur l’Eglise Secrète, et complote avec le dieu ancien Diablo et l’archange majeure Zophielle pour transformer Innocentia en déesse, pour cela, il façonne sa prophétesse, Stephania VOLKOV afin de forcer la Papesse à éveiller son âme, Stephania n’étant qu’un sacrifice pour créer une nouvelle divinité que L’ombre-pape réserve comme femelle à son maitre afin de créer une nouvelle ère des abominations. Absariath a toutefois quelques moments d’humanité, comme si, à force d’exister, il devenait un être vivant véritablement et éprouvait l’envie de le rester, impliquant de ne pas réveiller son « Père ». En vivant à Los Angeles, Absariath aspire de plus en plus à s’instaurer comme un « Dieu » plus qu’un serviteur de fléau, une fois V’Aagor ravivé, il ne sait pas encore comment survivre, c’est pourquoi il cherche à percer l’Ombre-Monde pour dévorer assez de Magie afin de parfaitement se détacher de son « Maitre »."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}],"legacyTargetId":"pnj-100-ombre-pape-valentino-sombra","navigation":{"group":"Corruption & menaces","groupOrder":80,"subgroup":"Abominations","subgroupOrder":20,"pageOrder":500}},{"id":"pnj-fleaux-focus-stephania-volkov-stephania-volkov","dataset":"verite-fleaux-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Stephania VOLKOV,","source":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Fléaux","Focus Fléaux 2026-09","humaine","chasseurs des confrérie"],"pnj":{"completeness":"detailed","real_name":"Stephania VOLKOV,","nom_verite":"","race":"humaine","age":"«41 ans » - 47 ans","origine":"russe","statut":"chasseurs des confrérie","affiliations":"chasseurs des confrérie","relations":["Levanah URIEL","Catalina de la CAZA"],"identity_keys":["Stephania VOLKOV,","Stephania Volkov"]},"loreBook":{"focusBatch":"fleaux-focus-2026-09-v1","focusSource":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx"},"sections":[{"id":"fleaux-focus-dossier","title":"Dossier — Focus Fléaux","level":2,"blocks":[{"type":"p","style":"Normal","text":"L’ordre de longinus"},{"type":"p","style":"Normal","text":"Nom de la Réalité : Stephania VOLKOV, Nom de la Vérité : _ Age : «41 ans » - 47 ans Affiliations : chasseurs des confrérie Nationalité d’origine : russe Ethnie réelle : humaine"}]},{"id":"fleaux-focus-realite","title":"Informations Réalité — Focus Fléaux","level":2,"blocks":[{"type":"p","style":"Normal","text":"« L’ombre-Pape » a désigné le nouveau Messie en la personne d’une ancienne sorcière des saintes lagunes, Stephania VOLKOV, que l’ordre sauva d’une mort certaine quand Alisa ( Ux’Sharith ) Fléau incarné, retira son essence de son corps. Bien que Stephania ne sache pas en quoi ni pourquoi, elle fut placée à la tête de l’ordre et reçu la lance de Longines comme présent afin qu’elle ne tue la « Papesse des enfers », Innocentia. Poussée par ses bienfaiteurs, Stephania ne peut reculer et a accepté de puiser dans leurs pouvoirs dont elle sent une étrange similarité avec ceux des sorcières qu’elle chassait et qu’elle était autrefois. Pratiquement ressuscitée pour devenir la meneuse de cet ordre, Stephania est incroyablement plus puissante qu’autrefois et, forcément, chasse uniquement les chasseurs Monothéïstes. Elle était absolument divisée dès qu’elle a été sauvée, elle savait d’instinct que l’Ombre-Pape était malfaisant mais sa survie en dépendait. Elle a donc manifestement aidé à répartir la « Sombre￾vérité », à travers les religieux et les chasseurs afin de se faire bien voir, elle a tué de nombreux chasseurs religieux également pour prouver sa force ainsi que de très nombreux daemons et angelus, bien qu’elle n’en comprît pas forcément la nature. A côté, elle a néanmoins tout fait pour limiter l’influence du culte, semer des traces et chercher de l’aide depuis 2020, hélas, les principaux membres de l’ordre des Saintes Lagunes n’ont jamais cherché à l’aider et Stephania a perdu progressivement espoir. Si elle a toujours cherché à préserver les enfants de l’influence du culte, elle a de nombreux meurtres et complots à son actif, elle détourne pour elle-même et pour l’ordre de très grosses sommes de la Liao-Bank où elle est vice-présidente en outre. Elle devait achever son éveil à V’Aagor pour devenir un sacrifice à Innocentia selon les plans d’Absariath, mais elle est devenue elle-même un fragment de V’Aagor, au même titre que l’Ombre￾Pape, si elle a été récemment purgée de V’Aagor, lors d’une entrevue avec des Divinités, par miracle, Stephania reste une créature n’ayant plus grand-chose d’humain. Ni Fléau supérieur ni humaine, elle est un réceptacle de pouvoirs et de dons sans vraie nature identifiable qui peut se briser à tout instant faute d’essence propre."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}],"legacyTargetId":"pnj-101-stephania-volkov","navigation":{"group":"Chasseurs","groupOrder":60,"subgroup":"Chasseurs & réseaux de Chasse","subgroupOrder":10,"pageOrder":500}},{"id":"pnj-fleaux-focus-azaliah-springer-azaliah-springer","dataset":"verite-fleaux-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Azaliah SPRINGER","source":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Fléaux","Focus Fléaux 2026-09","Abomination - extraterrestres (effismes)","« Créatures »"],"pnj":{"completeness":"detailed","real_name":"Azaliah SPRINGER","nom_verite":"Zaalia’Gaer","race":"Abomination - extraterrestres (effismes)","age":"« 38 ans » - ???? ans","origine":"???","statut":"« Créatures »","affiliations":"« Créatures »","relations":[],"identity_keys":["Azaliah SPRINGER","Azaliah Springer","Zaalia’Gaer"]},"loreBook":{"focusBatch":"fleaux-focus-2026-09-v1","focusSource":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx"},"sections":[{"id":"fleaux-focus-dossier","title":"Dossier — Focus Fléaux","level":2,"blocks":[{"type":"p","style":"Normal","text":"Secte de l’œil blanc"},{"type":"p","style":"Normal","text":"Nom de la Réalité : Azaliah SPRINGER Nom de la Vérité : Zaalia’Gaer Age : « 38 ans » - ???? ans Affiliations : « Créatures » Nationalité d’origine : ??? Ethnie réelle : Abomination - extraterrestres (effismes)"}]},{"id":"fleaux-focus-verite","title":"Informations Vérité — Focus Fléaux","level":2,"audience":"mj","blocks":[{"type":"p","style":"Normal","text":"Zaalia a été arrachée de la dimension des effismes par Rnael’gem, cette femelle était si heureuse d’agir dans la dimension des mâles qu’elle est rapidement tombée dans un fanatisme rare. Malgré les soucis de santé énormes que la gravité Terrestre posait, elle n’en démordait pas quant au caractère miraculeux de la matérialisation quand elle s’opposa farouchement à la grande prêtresse du culte du Photonaire qu’elle assassina de sang-froid. Plus tard, elle retourna les pouvoirs de Rnael’gem contre lui, en effet, c’est parce que les femelles effismes sont uniquement composée de matière noire qu’elles ne semblent pas visibles dans la dimension, elles pèsent, de fait, incroyablement plus lourd et manipulent la gravité comme personne, même s’il était le fragment d’un fléau, il s’endormit, écrasé par la puissance de la fanatique le maintenant en sommeil pour diriger, seule. Azaliah est une Chanoinesse impitoyable, ses nonnes recrutent essentiellement de jeunes hommes et femmes assez séduisants qu’elle dote des ténèbres de V’Aagor, ténèbres qui capturent la matière noire et permettent d’influer sur l’environnement, de pousser les choses en expulsant de cette matière invisible ou d’attirer en augmentant la quantité de matière. Elle est absolument fanatique du roi des Fléaux, hélas, enfermé avant qu’elle ne sorte de sa dimension, elle n’a jamais pu communiquer avec lui qu’en rêve, mais il l’ensemença malgré tout ainsi. Elle a une dizaine de filles, mi-fléau mi effismes, des abominations comme elle qu’elle retient de force dans son couvent près de Salem. Sa secte utilise le caractère religieux et humanitaire pour corrompre, tout comme l’ordre de Longinus, elle utilise la « sombre-vérité » pour insinuer V’Aagor dans les « messagers ». Malgré un comportement glacial et hautain, effrayant même, c’est une créature avide de sexualité, elle cherche plus particulièrement les autres fragments de son maitre pour les posséder comme amants. Elle a plusieurs millénaires, quand elle est en colère, elle peut créer de profondes dolines, elle a rasé ainsi le village de Dixenford en 1875, laissant un vaste cratère de 210 mètres de profondeur sur 25 km de diamètre bien qu’il soit rebouché depuis."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}],"legacyTargetId":"pnj-086-azaliah-springer","navigation":{"group":"Corruption & menaces","groupOrder":80,"subgroup":"Abominations","subgroupOrder":20,"pageOrder":500}},{"id":"pnj-fleaux-focus-noah-brenneman-6-noah-brenneman","dataset":"verite-fleaux-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Noah BRENNEMAN","source":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Fléaux","Focus Fléaux 2026-09","Abomination - extraterrestres (effismes)","« Créatures »"],"pnj":{"completeness":"detailed","real_name":"Noah BRENNEMAN","nom_verite":"Rnael’gem","race":"Abomination - extraterrestres (effismes)","age":"«49 ans » / -","origine":"russe","statut":"« Créatures »","affiliations":"« Créatures »","relations":[],"identity_keys":["Noah BRENNEMAN","Noah Brenneman","Rnael’gem"]},"loreBook":{"focusBatch":"fleaux-focus-2026-09-v1","focusSource":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx"},"sections":[{"id":"fleaux-focus-dossier","title":"Dossier — Focus Fléaux","level":2,"blocks":[{"type":"p","style":"Normal","text":"Secte de l’œil blanc"},{"type":"p","style":"Normal","text":"Nom de la Réalité : Noah BRENNEMAN Nom de la Vérité : Rnael’gem Age : «49 ans » - Affiliations : « Créatures » Nationalité d’origine : russe Ethnie réelle : Abomination - extraterrestres (effismes)"}]},{"id":"fleaux-focus-realite","title":"Informations Réalité — Focus Fléaux","level":2,"blocks":[{"type":"p","style":"Normal","text":"Rnael’gem a été créé par la causalité, comme presque tous les fragments de V’Aagor, peu après l’arrivée des premier effismes sur Terre. Il n’a jamais eu une véritable conscience de ce qu’il était, il a servi son créateur d’instinct sans aucun doute ni aucune forme d’hésitation. Pour s’imposer dans la communauté, il a déchiré le tissu dimensionnel, et arraché des femelles Effismes, en effet, chez cette espèce, les mâles ont un temps de développement dans la dimension où la matière baryonique se manifeste, une forme de longue adolescence allant de quelques décennies à quelques siècles afin d’acquérir une certaine maturité gravitationnelle, leur permettant de basculer dans la « dimension » de la matière noire, invisible où les femelles naissent et s’épanouissent nativement. C’est donc un non-sens de chercher à s’épanouir dans la dimension « normale » pour un effisme mais c’est aussi une source de grande frustration pour beaucoup, ramener des femelles a donc été à la fois la preuve de sa toute-puissance mais aussi un acte hérétique aussi infâme qu’inédit. La communauté s’est déchirée entre les fanatiques des anciennes croyances, voyant le caractère malsain de ces pouvoirs et les neo fanatiques, le considérant tel le prophète d’une nouvelle ère pour les effismes. Pendant longtemps, il a enchainé les « miracles » tout en s’assurant de cacher les siens, il a de plus en plus arraché des femelles pour posséder des appuis forts, en effet, plus puissantes et plus matures, plus sages, les femelles effismes ont un statut très supérieur dans les cultures de cette espèce, plus il en ramena et plus il s’imposa. Cependant, il commit l’erreur d’extraire une grande prêtresse qui rata de le tuer si une jeune fanatique n’était pas intervenue. Blessé, il décida d’entrer en stase, ignorant que celle l’ayant sauvé s’assura dès lors que plus jamais il ne s’éveillerait durablement, ne le réveillant à sa guise que lorsqu’elle a le besoin. Bien qu’il ne soit qu’un outil désormais, il reste un fléau supérieur d’une rare dangerosité."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}],"legacyTargetId":"pnj-096-noah-brenneman","navigation":{"group":"Corruption & menaces","groupOrder":80,"subgroup":"Abominations","subgroupOrder":20,"pageOrder":500}},{"id":"pnj-fleaux-focus-olayinka-najja-8-olayinka-najja","dataset":"verite-fleaux-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Olayinka NAJJA","source":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Fléaux","Focus Fléaux 2026-09","vampires","« Créatures »"],"pnj":{"completeness":"detailed","real_name":"Olayinka NAJJA","nom_verite":"Olayinka","race":"vampires","age":"«29 ans » / -","origine":"nigériane","statut":"« Créatures »","affiliations":"« Créatures »","relations":[],"identity_keys":["Olayinka NAJJA","Olayinka Najja","Olayinka"]},"loreBook":{"focusBatch":"fleaux-focus-2026-09-v1","focusSource":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx"},"sections":[{"id":"fleaux-focus-dossier","title":"Dossier — Focus Fléaux","level":2,"blocks":[{"type":"p","style":"Normal","text":"Confrérie de la faux"},{"type":"p","style":"Normal","text":"Nom de la Réalité : Olayinka NAJJA Nom de la Vérité : Olayinka Age : «29 ans » - Affiliations : « Créatures » Nationalité d’origine : nigériane Ethnie réelle : vampires"}]},{"id":"fleaux-focus-realite","title":"Informations Réalité — Focus Fléaux","level":2,"blocks":[{"type":"p","style":"Normal","text":"Olayinka était une ancienne chamane quand le roi Neeba est né. Elle avait annoncé à son père, le précédent roi, que son fils serait le plus prodigieux des chasseurs et qu’il l’emporterait sur tous ses ennemis se trouvant « entre les deux océans », effectivement, Neeba purga l’Afrique des homme￾hyènes, repoussa les hommes-lions et les loups-garous des pelages d’ébène, il purgea aussi toutes les factions vampiriques de l’Oru qui ne croyaient pas dans le culte de la « Fontaine des ténèbres », y compris son propre père qui oublia le temps d’une défaite mortelle la prophétie qui avait été faite. Olayinka est une femme totalement indépendante, elle est si ancienne que son sang est le plus noir de tous les vampires Oshiriques mais aussi le plus épais : une seule goutte de son sang peu transformer en abomination n’importe quel humain, en strygoï noire plus précisément. Si jamais un vampire venait à en boire, nul ne sait ce que cela engendrerait. Elle est si ancienne qu’absolument aucun vampire de l’Oru ne refuse ses avances quand elle en fait, et même en 2015, elle était encore capable de procréer. Avec un enfant tous les siècles, sa fertilité impressionne d’autant plus que le roi semble stérile, ce qu’elle moque ouvertement. Elle traque les fragments de V’Aagor car bien qu’elle serve à son insu ce Fléau, elle considère ces maitres des autres cultes comme des proies à sacrifier à son « Dieu ». C’est une femme fatale, dans tous les sens possibles du terme, en 2035, elle a déjà couché avec le président des Etats-Unis à peine quelques jours après être débarquée sur le territoire. Ses amants, qu’importe leur genre, se doivent d’être excellents, sinon elle les torture et s’en sert d’esclaves sans volonté. Elle a une relation complexe avec Neeba, le roi de l’Oru, elle est une sorte d’ex-femme, de mère, de mentor mais aussi de rivale, étant le vampire le plus influent après lui. Elle pose d’énormes soucis à la Chasseuse Lisbeth, elle hypnotise énormément d’humains et en transforme en moroï l’équivalent. Elle méprise Dragoy SKOTIA, mais respecte énormément Megda AYSHIN, son amie, la reine des vampires de l’Alghul."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}],"legacyTargetId":"pnj-098-olayinka-najja","navigation":{"group":"Figures de Vérité","groupOrder":70,"subgroup":"Vampires","subgroupOrder":10,"pageOrder":500}},{"id":"pnj-fleaux-focus-neals-corvo-ruth-neals-corvo","dataset":"verite-fleaux-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Neals CORVO","source":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Fléaux","Focus Fléaux 2026-09","Elfes","Crawlers"],"pnj":{"completeness":"detailed","real_name":"Neals CORVO","nom_verite":"Nerediath LISINDRITH « Painscar »","race":"Elfes","age":"«41 ans » - ???? ans","origine":"Canadienne","statut":"Crawlers","affiliations":"Crawlers","relations":[],"identity_keys":["Neals CORVO","Neals Corvo","Nerediath LISINDRITH « Painscar »"]},"loreBook":{"focusBatch":"fleaux-focus-2026-09-v1","focusSource":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx"},"sections":[{"id":"fleaux-focus-dossier","title":"Dossier — Focus Fléaux","level":2,"blocks":[{"type":"p","style":"Normal","text":"la confrérie de la faux"},{"type":"p","style":"Normal","text":"Nom de la Réalité : Neals CORVO Nom de la Vérité : Nerediath LISINDRITH « Painscar » Age : «41 ans » - ???? ans Affiliations : Crawlers Nationalité d’origine : Canadienne Ethnie réelle : Elfes"}]},{"id":"fleaux-focus-realite","title":"Informations Réalité — Focus Fléaux","level":2,"blocks":[{"type":"p","style":"Normal","text":"Neals Corvo est surnommé « Painscar » ou « Redscar » en raison de sa balafre rougeâtre sur son visage. C’est un assassin, un « Voidrunner », il est l’archétype du solitaire, il refuse d’avoir la moindre aide, le moindre soutien, une fois payé, on ne le revoit pas avant qu’il ne vienne pour la seconde de sa récompense, une fois la cible achevée."}]},{"id":"fleaux-focus-verite","title":"Informations Vérité — Focus Fléaux","level":2,"audience":"mj","blocks":[{"type":"p","style":"Normal","text":"Nerediath est un descendant d’elfes noirs d’Aèr. Il appartient à une confrérie d’assassins qui cultivent des arts ancestraux. La confrérie est peu aimée des autres elfes alors elle a souvent été démantelée puis refondée aussitôt. Nerediath était le maitre de cette confrérie quand en 1482, le roi Obéron décida de définitivement renoncer à cette faction dans les rangs des elfes, ce fut une simple et discrète purge, les quelques dizaines de membres la composant ne furent pas de grandes proies pour les quelques guerriers de la Chasse fantastique que dirigeait Titania contre la confrérie. Titania trancha le tiers gauche du crane de Nerediath et repartit en laissant les corps bruler. Dans sa rage et sa haine infinie, alors qu’il était à l’agonie, Nerediath en appela à V’Aagor, le Fléau, lui laissant son corps pour ses sombres projets tant qu’il pouvait se venger. Bien entendu le Fléau ne s’incarna pas dans l’elfe, ce ne fut qu’un fragment qui s’éveilla et fusionna avec Nerediath, assez pour recoller son corps découpé et le laisser pleinement recouvrir ses forces. La confrérie fut encore une fois relancée, mais désormais, elle était aussi une secte pour glorifier le « sang des ténèbres », le corps de V’Aagor, Nerediath transformant les elfes le suivant en abominations comme lui à la fois des elfes, à la fois des créatures asservies par le Fléau, pouvant à tout instant se déformer, gonfler et se déchirer sur un sursaut de sa conscience. Seule sa cicatrice rouge semble être une source de douleur pour lui, seule la reine Titania l’effraie vraiment."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}],"legacyTargetId":"pnj-truth-neals-corvo","navigation":{"group":"Corruption & menaces","groupOrder":80,"subgroup":"Abominations","subgroupOrder":20,"pageOrder":500}},{"id":"pnj-fleaux-focus-mira-stephens-5-mir-a-stephens","dataset":"verite-fleaux-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Mira STEPHENS","source":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Fléaux","Focus Fléaux 2026-09","elfes","« Créatures »"],"pnj":{"completeness":"detailed","real_name":"Mira STEPHENS","nom_verite":"Mirrissi","race":"elfes","age":"«49 ans » / -","origine":"américaine","statut":"« Créatures »","affiliations":"« Créatures »","relations":[],"identity_keys":["Mira STEPHENS","Mirrissi"]},"loreBook":{"focusBatch":"fleaux-focus-2026-09-v1","focusSource":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx"},"sections":[{"id":"fleaux-focus-dossier","title":"Dossier — Focus Fléaux","level":2,"blocks":[{"type":"p","style":"Normal","text":"Confrérie de la faux"},{"type":"p","style":"Normal","text":"Nom de la Réalité : Mira STEPHENS Nom de la Vérité : Mirrissi Age : «49 ans » - Affiliations : « Créatures » Nationalité d’origine : américaine Ethnie réelle : elfes"}]},{"id":"fleaux-focus-realite","title":"Informations Réalité — Focus Fléaux","level":2,"blocks":[{"type":"p","style":"Normal","text":"Mirissi était le mentor de Titania, elle lui a pratiquement tout enseigné, l’art du combat, de la magie, les philosophies elfiques, les arts elfiques, la sexualité, absolument tout ce que la reine élue Titania a su maitriser, Mirrissi le maitrisait et lui a enseigné. C’est pourquoi elle fut la première maitresse de la chasse Fantastique avant sa disciple et première reine élue de tous les elfes de la Terre. Glaciale et intraitable, elle était bien trop attachée à Aèr et aux anciennes coutumes, elle a progressivement perdu le jeu de la politique et s’est vue affublée d’un comparse en la personne d’Obéron puis, elle a aussi perdu la Chasse fantastique et progressivement a été mise à l’écart. « L’ancêtre » était son surnom, moquée, l’une des plus anciennes des elfes sur Terre a senti sa vie passer du plus haut sommet à celui de maria avec l’essor de sa disciple et de son époux. Mirrissi a toujours scrupuleusement caché son nom de famille, mais il ne faut pas douter qu’elle était issue d’une grande noblesse vu sa finesse et sa perfection dans tout ce qu’elle entreprend. C’est précisément son perfectionnisme et sa grande discrétion qui lui coutèrent le plus, les elfes de la Terre s’humanisant, devenant moins rigides, moins « beaux », mais plus adaptables, l’échec est la pire des laideurs, de perfection, l’objectif premier des elfes devint la réussite, le crédo de Titania, une vision qui mena Mirrissi à tenter de la renverser dans un coup d’Etat, ne pouvant pas tolérer la décadence que cette philosophie implique. Mirrissi fut seule, son coup d’Etat n’échoua pas simplement, il se retourna complétement contre elle et elle fut bannie à jamais, ses yeux furent crevés et on scella sa capacité à utiliser la magie. Elle fut toutefois sauvée par Nerediath et sa confrérie, en échange de sa conversion, elle retrouva la vue. Elle devint importante dans la confrérie et si jamais elle ne put utiliser elle-même de magie, elle tortura et dressa un Mage, Valagon BULGAKOV de la Loge de Moscou, l’esclave devenant son vecteur de magie et lui permit de capturer une autre Mage, Gudrun THUESEN, de la loge de Copenhague, dont elle tissa le Mageius à celui de Valagon puis à son corps grâce aux pouvoirs de V’Aagor. Elle a totalement conscience de servir un faux-dieux, et ne le fait que par pure envie de vengeance. Elle méprise totalement Nerediath, le maitre de la confrérie, un misérable moins que rien sans aucune forme d’honneur mais qu’elle utilise pour un jour, possiblement, redevenir reine."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}],"legacyTargetId":"pnj-095-mir-a-stephens","navigation":{"group":"Corruption & menaces","groupOrder":80,"subgroup":"Abominations","subgroupOrder":20,"pageOrder":500}},{"id":"pnj-fleaux-focus-tellia-fedirivna-skrypnyk-dirivna-skrypnyk","dataset":"verite-fleaux-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Tellia Fedirivna SKRYPNYK","source":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Fléaux","Focus Fléaux 2026-09","Fléau supérieur","« Créatures »"],"pnj":{"completeness":"detailed","real_name":"Tellia Fedirivna SKRYPNYK","nom_verite":"Tel’Shaerith","race":"Fléau supérieur","age":"« 40 ans » - ???? ans","origine":"Ukrainienne","statut":"« Créatures »","affiliations":"« Créatures »","relations":["R’Gahanath","Lilith"],"identity_keys":["Tellia Fedirivna SKRYPNYK","Tellia Fedirivna Skrypnyk","Tel’Shaerith"]},"loreBook":{"focusBatch":"fleaux-focus-2026-09-v1","focusSource":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx"},"sections":[{"id":"fleaux-focus-dossier","title":"Dossier — Focus Fléaux","level":2,"blocks":[{"type":"p","style":"Normal","text":"Fille de Sharith"},{"type":"p","style":"Normal","text":"Nom de la Réalité : Tellia Fedirivna SKRYPNYK Nom de la Vérité : Tel’Shaerith Age : « 40 ans » - ???? ans Affiliations : « Créatures » Nationalité d’origine : Ukrainienne Ethnie réelle : Fléau supérieur"}]},{"id":"fleaux-focus-verite","title":"Informations Vérité — Focus Fléaux","level":2,"audience":"mj","blocks":[{"type":"p","style":"Normal","text":"Tellia SHANE est une chasseuse ukrainienne, elle se cache à Tchernobyl et ses alentours. C’est une engeance de Sharith et V’Aagor, c’est possiblement le fléau supérieur le plus redouté par les Dieux, à tort quand on connait sa sœur, R’Gahanath. Tellia n’a pas hérité du caractère insidieux et malfaisant de son père, elle a été très tôt enfermée et protégée par la déesse Lilith, se refusant laisser le fléau grandir sous l’influence de ces parents immondes. Lilith lui façonna un corps, elle l’éduqua, quand Sharrith fut détruite, peu avant V’Aagor, elle dissimula l’engeance, ainsi, Tel’sha est plus proche d’être une démone de Lilith qu’un fléau. Néanmoins, elle déformait et altérait l’enfer de Lilith, elle fut relâchée sur Terre pour sauver la bulle dimensionnelle de l’influence passive qu’elle avait sur elle. Tel’sha était avide de connaissance, hélas pour elle, sa nature même changeait les humains en abomination, en effet, Sharith est excessivement radioactive, à l’instar de sa mère qui divise les pouvoirs, l’essence de Tellia est de diviser la matière, elle est une forme de réacteur nucléaire d’une rare capacité. Très tôt, sa présence a donc posé un problème, elle avait beau changer de corps, en parasitant ceux des descendantes de sa mère, elle finissait par les détruire par les effets de la radioactivité. Faute de solution, la Loge celtique finit par la sceller durant le début du moyen-âge. Elle a été libérée en 2020, quand sa mère, Ux’Sharith, se réveilla et dévora les milliers de pouvoirs revenant à elle. Tel’Sha fut aussi libérer de son pouvoir, non pas qu’elle en fut privée, mais son aptitude à la fission cessa d’être passif. Elle traque essentiellement les abominations créées par sa présence autrefois ainsi que celles créées par radioactivité, Tchernobyl et Fukushima sont ses principaux lieux de chasse en plus d’îles en Polynésie française. Elle considère Lilith comme sa mère et se prépare un jour à devoir affronter sa génitrice."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}],"legacyTargetId":"pnj-103-tellia-fedirivna-skrypnyk","navigation":{"group":"Corruption & menaces","groupOrder":80,"subgroup":"Fléaux & figures de Rupture","subgroupOrder":10,"pageOrder":500}},{"id":"pnj-fleaux-focus-kennisha-arnold--kennisha-arnold","dataset":"verite-fleaux-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Kennisha Arnold","source":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Fléaux","Focus Fléaux 2026-09","Abomination","chasseurs fantastique"],"pnj":{"completeness":"detailed","real_name":"Kennisha Arnold","nom_verite":"Karr’Shahan V’Rothl","race":"Abomination","age":"« 42 ans » - ??? ans","origine":"américaine","statut":"chasseurs fantastique","affiliations":"chasseurs fantastique","relations":[],"identity_keys":["Kennisha Arnold","Karr’Shahan V’Rothl"]},"loreBook":{"focusBatch":"fleaux-focus-2026-09-v1","focusSource":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx"},"sections":[{"id":"fleaux-focus-dossier","title":"Dossier — Focus Fléaux","level":2,"blocks":[{"type":"p","style":"Normal","text":"L’ombre à l’affût"},{"type":"p","style":"Normal","text":"Nom de la Réalité : Kennisha Arnold Nom de la Vérité : Karr’Shahan V’Rothl Age : « 42 ans » - ??? ans Affiliations : chasseurs fantastique Nationalité d’origine : américaine Ethnie réelle : Abomination"}]},{"id":"fleaux-focus-verite","title":"Informations Vérité — Focus Fléaux","level":2,"audience":"mj","blocks":[{"type":"p","style":"Normal","text":"Kennisha est la gérante d’un Dinner dans un quartier abandonné, le « Gore’Tex ‘s Dinner » (GTD). Serveuse, gérante et cuisinière le jour, elle gère une équipe de quatre serveuses malgré les gangs et les mafieux qui cherchent à la racketter souvent étant donné ses énormes dettes. La nuit, elle laisse le Dinner à une amie, et elle se révèle être la « karr ‘Shahan », une créature unique et malfaisante. Autrefois, elle était une forme de Deimon, une ombre vivante, mais elle fut corrompue par le fléau Ux’Sharith, loyale servante, elle n’aurait pas pu survivre sans sa maitresse quand elle fut privée de cette dernière. Traquée par les cieux comme les enfers, elle se réfugia parmi les humains, faible et seule. Elle se rapprocha des descendantes de sa maitresse mais l’ordre des saintes lagunes commença à les asservir quand elles approchèrent d’une première résurrection de leur Créatrice. Shahan lutta contre l’ordre des Saintes lagunes, en vain, échouant trois fois de suite à faire revenir le Fléau majeur. Emprisonnée, elle ne fut libérée qu’en 1990, durant la guerre du Golfe, vendue comme guerrière exceptionnelle, elle se fit passer pour morte dès son premier combat, sans rien accomplir, les chevaliers des Saintes lagunes et la troupe mercenaires qu’ils composaient ignorant ses véritables pouvoirs, se faisant avoir aisément. Rapatriée aux Etats-Unis, elle reprit sa méthode pour survivre : chercher des mâles descendants d’Ux’Sharith, leur dévorer leur essence puis s’accoupler avec, avant de partir traquer des créatures d’ombre, comme elle en était une autrefois, pour se repaitre de leur nature et ainsi osciller entre fléau mineur et Ombre. Elle a notamment été Keandra Leeson, mariée Brock, l’épouse de Melvin Brock, qu’elle rendit plus violent, mais qu’elle quitta quand ce dernier eu des démêlés avec la justice après avoir abusé d’une jeune orpheline qu’ils avaient chez eux. Cette abomination est considérée comme une cannibale car elle dévore aussi bien les ombres que les autres serviteurs des fléaux, du moins de ceux ne servant pas sa maitresse, elle cherche à tuer l’ancien maitre de l’ordre des Saintes lagunes."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}],"legacyTargetId":"pnj-089-kennisha-arnold","navigation":{"group":"Corruption & menaces","groupOrder":80,"subgroup":"Abominations","subgroupOrder":20,"pageOrder":500}},{"id":"pnj-fleaux-focus-lidira-pnj-091-lidira","dataset":"verite-fleaux-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Lidira","source":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Fléaux","Focus Fléaux 2026-09","Gobelins","Abominations (gobelins)"],"pnj":{"completeness":"detailed","real_name":"Lidira","nom_verite":"Lidira","race":"Gobelins","age":"« ?? »","origine":"-","statut":"Abominations (gobelins)","affiliations":"Abominations (gobelins)","relations":[],"identity_keys":["Lidira"]},"loreBook":{"focusBatch":"fleaux-focus-2026-09-v1","focusSource":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx"},"sections":[{"id":"fleaux-focus-dossier","title":"Dossier — Focus Fléaux","level":2,"blocks":[{"type":"p","style":"Normal","text":"La servante d’ux’Sharith"},{"type":"p","style":"Normal","text":"Nom de la Réalité :Lidira Nom de la Vérité : Lidira Age : « ?? » Affiliations : Abominations (gobelins) Nationalité d’origine : - Ethnie réelle : Gobelins"}]},{"id":"fleaux-focus-verite","title":"Informations Vérité — Focus Fléaux","level":2,"audience":"mj","blocks":[{"type":"p","style":"Normal","text":"Lidira est une abomination issue du peuple des Ashylls (gobelins) Malgré son apparence relativement séduisante de jeune gobeline radieuse et séductrice, c’est une servante d’Ux’Sharith. Elle n’a jamais connu le Fléau de son vivant, mais les sorcières psycolors ont longtemps entretenu un culte en son honneur, un culte féminin voire féministe qui traversa les âges. Un culte de l’esthétisme, de la couleur, de la polyvalence et la diversité. Bien qu’elle n’en descendît pas, lidira, face aux purges contre son peuple, se voua corps et âme à ce culte où la différence était une vertu. Elle reçut des pouvoirs de « psycolor » qu’on nommait à l’époque « pouvoirs du Prisme » Elle obtint la couleur du vert sans trop de surprise et devint capable de créer des « gobelins » à partir de toute matière, terre, bois, cadavres, des serviteurs similaires à des ashylls mais purement animés par les pouvoirs du Fléau, dépossédé de toute forme de libre-arbitre. Ses hordes de gobelins difformes et doté d’une intelligence limitée devinrent des armées qui défendirent les empires gobelins jusqu’à ce que les Duergars ne chassent définitivement les gobelins des sous-sols, à l’exception de Lidira et de ses créatures. Abandonnée par les siens parce qu’elle était hérétique, bien qu’elle défendît son peuple, elle devint folle, sadique et lunatique, elle commença à torturer ses propres créations et s’amuser à enfermer toute forme de créature dans ces corps grotesques pour leur donner des personnalités. Elle créa ainsi les « Greenblins » des formes d’abominations difformes allant de la taille d’une main à celle d’un petit immeuble, gonflés de sa magie maléfique qu’elle créait à partir de rien si ce n’est de prisonniers humains ou autre. Elle répugne désormais à créer ses jouets sans qu’ils n’aient de personnalité et cultive l’art de choisir des gens parmi les citoyens, artisans, vedettes ou loosers, elle pioche dans la société ses « acteurs » allant devenir des marionnettes vivantes, certains bénéficiant de l’immortalité par ses pouvoirs, d’autres mourant en quelques heures en l’ennuyant ou parfois parce qu’elle l’avait juste décidé sadiquement."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}],"legacyTargetId":"pnj-091-lidira","navigation":{"group":"Corruption & menaces","groupOrder":80,"subgroup":"Abominations","subgroupOrder":20,"pageOrder":500}},{"id":"pnj-fleaux-focus-nora-shakir--097-nora-shakir","dataset":"verite-fleaux-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Nora SHAKIR","source":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Fléaux","Focus Fléaux 2026-09","Abomination","« Créatures »"],"pnj":{"completeness":"detailed","real_name":"Nora SHAKIR","nom_verite":"« furoncle purulent »","race":"Abomination","age":"«29 ans » / -","origine":"Tunisienne","statut":"« Créatures »","affiliations":"« Créatures »","relations":[],"identity_keys":["Nora SHAKIR","Nora Shakir","« furoncle purulent »"]},"loreBook":{"focusBatch":"fleaux-focus-2026-09-v1","focusSource":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx"},"sections":[{"id":"fleaux-focus-dossier","title":"Dossier — Focus Fléaux","level":2,"blocks":[{"type":"p","style":"Normal","text":"Secte de Bellatheis"},{"type":"p","style":"Normal","text":"Nom de la Réalité : Nora SHAKIR Nom de la Vérité : « furoncle purulent » Age : «29 ans » - Affiliations : « Créatures » Nationalité d’origine : Tunisienne Ethnie réelle : Abomination"}]},{"id":"fleaux-focus-realite","title":"Informations Réalité — Focus Fléaux","level":2,"blocks":[{"type":"p","style":"Normal","text":"Elle n’avait absolument pas de corps humain ni de nom à l’origine, elle ne sait pas vraiment de quoi elle est née ni même si elle est une engeance directe ou indirecte de Sharith, dans tous les cas, elle en est forcément une création. Surnommée « furoncle », elle était, tout comme « pustule », une créature créée par Sharith, mais involontairement dont elle se débarrassa pour devenir plus belle, plus « divine ». Comme « Pustule », le principal talent de « Furoncle » est de se greffer aux créatures et de fusionner parfaitement avec le temps qu’elle désire. Contrairement à son homologue, elle a énormément voyagé et a toujours chassé les démons de Lilith, se greffant à eux et dévorant leur corps pour devenir une créature polymorphe. Elle n’a que récemment cherché à rejoindre l’ordre de Bellatheis, après des millénaires à n’œuvrer que pour elle-même. Contrairement à « Pustule », elle ne voue aucunement une admiration sans faille pour Sharith, elle vénère Lilith comme l’absolue maitresse ayant anéanti leur créatrice et cherche à nuire à ses daemons pour prouver en quelque sorte qu’elle est meilleure qu’eux. Ce qui l’a motivé à devenir prêtresse du culte est une raison très égoïste, elle était jalouse de « Pustule ». Les pouvoirs de « Furoncle » sont similaires à ceux de « Pustule », cependant, elle se greffe de façon moins compacte et plus visqueuse, plus « purulente », ses ennemis préférés sont ceux qui possèdent des organes spéciaux tels que des glandes à venin ou autre, qu’elle peut remplir de liquide nauséabond. Elle provoque aisément des maladies respiratoires de plus et des infections. C’est elle qui a créé la « porte des vérités » comme technique du culte."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}],"legacyTargetId":"pnj-097-nora-shakir","navigation":{"group":"Corruption & menaces","groupOrder":80,"subgroup":"Abominations","subgroupOrder":20,"pageOrder":500}},{"id":"pnj-fleaux-focus-ana-diana-de-la-caza-diana-de-la-caza","dataset":"verite-fleaux-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Ana Diana de la CAZA","source":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Fléaux","Focus Fléaux 2026-09","Abomination -","« Créatures »"],"pnj":{"completeness":"detailed","real_name":"Ana Diana de la CAZA","nom_verite":"Anadia","race":"Abomination -","age":"« 79 ans » - 279 ans","origine":"espagnole","statut":"« Créatures »","affiliations":"« Créatures »","relations":["Catalina de la CAZA","Valentino SOMBRA"],"identity_keys":["Ana Diana de la CAZA","Ana Diana De la Caza","Anadia"]},"loreBook":{"focusBatch":"fleaux-focus-2026-09-v1","focusSource":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx"},"sections":[{"id":"fleaux-focus-dossier","title":"Dossier — Focus Fléaux","level":2,"blocks":[{"type":"p","style":"Normal","text":"Matriarche du Grand Savoir"},{"type":"p","style":"Normal","text":"Nom de la Réalité : Ana Diana de la CAZA Nom de la Vérité : Anadia Age : « 79 ans » - 279 ans Affiliations : « Créatures » Nationalité d’origine : espagnole Ethnie réelle : Abomination -"}]},{"id":"fleaux-focus-verite","title":"Informations Vérité — Focus Fléaux","level":2,"audience":"mj","blocks":[{"type":"p","style":"Normal","text":"Héritière de la longue lignée d’Ashlutum, elle est une psywitch « black gold », une anomalie aisément expliquée par sa vraie nature d’abomination. En effet, Ana Diana n’est plus humaine depuis longtemps, étant donné qu’elle est la maitresse du culte du « Grand Savoir », elle a restructuré son propre corps pour devenir immortelle et approcher le fonctionnement d’un Mageius. Quand elle rencontrant Absariath, sous les traits de Valentino SOMBRA, elle savait qui était le fragment de V’Aagor et l’ensorcela pour le lier à sa lignée, elle est la véritable mère de Catalina de la Caza, Christina était une sœur ainée née 20 ans plus tôt à qui fut confier Catalina, Carlotta et Carmina en revanche étaient bien les filles de Christina. Ana Diana était convaincue que sa fille était une possible incarnation d’ux-Sharith et que les mauvais traitements de l’ordre des Saintes Lagunes l’éveilleraient, c’est pourquoi elle n’a jamais cherché à la rencontrer ni l’aider. Anadia mène son culte d’une main de fer, au point qu’il est possiblement le seul culte de Fléau qu’aucun dieu ni même les autres fléaux ne connaissent. Il est simplement si hermétique qu’il n’a pas admis de membre depuis des décennies. Même les enfants des membres ne sont généralement pas initiés s’ils n’ont pas le profil ou les dons nécessaires. Les Yeux d’Anadia sont capables de voir le fonctionnement des choses, elle sait estimer les points faibles, la santé, les défauts de conceptions ou de fabrication, la durée de vie mais aussi différentes caractéristiques de pouvoirs, tel que la densité magique, la vitesse des sorts ou bien encore leurs effets. Autant dire que les « yeux d’or » du culte du « Grand Savoir » sont plus efficaces encore que les yeux angéliques ou démoniaques pour percer l’Hologramme, pouvant même provoquer des bugs résiduels concernant ceux ainsi regardés. Elle vénère Sharith en tant que destructrice du Mensonge, le « Mensonge » étant l’obscurantisme et par extension l’obscurité, V’Aagor en personne l’incarnant, elle est donc redoutablement ennemie des cultes Aagoriens tout en les manipulant à sa guise, le plan de V’aagor quant à faire d’Innocentia une divinité étant d’elle."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}],"legacyTargetId":"pnj-082-ana-diana-de-la-caza","navigation":{"group":"Corruption & menaces","groupOrder":80,"subgroup":"Abominations","subgroupOrder":20,"pageOrder":500}},{"id":"pnj-fleaux-focus-yegor-karamov-05-yegor-karamov","dataset":"verite-fleaux-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Yegor KARAMOV","source":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Fléaux","Focus Fléaux 2026-09","Abomination","« Créatures »"],"pnj":{"completeness":"detailed","real_name":"Yegor KARAMOV","nom_verite":"Yegor KARAMOV","race":"Abomination","age":"«59 ans » / -","origine":"Russe","statut":"« Créatures »","affiliations":"« Créatures »","relations":[],"identity_keys":["Yegor KARAMOV","Yegor Karamovich"]},"loreBook":{"focusBatch":"fleaux-focus-2026-09-v1","focusSource":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx"},"sections":[{"id":"fleaux-focus-dossier","title":"Dossier — Focus Fléaux","level":2,"blocks":[{"type":"p","style":"Normal","text":"Apôtre du grand Savoir"},{"type":"p","style":"Normal","text":"Nom de la Réalité : Yegor KARAMOV Nom de la Vérité :Yegor KARAMOV Age : «59 ans » - Affiliations : « Créatures » Nationalité d’origine : Russe Ethnie réelle : Abomination"}]},{"id":"fleaux-focus-realite","title":"Informations Réalité — Focus Fléaux","level":2,"blocks":[{"type":"p","style":"Normal","text":"Yegor et Arkady KARAMOVICH sont nés en Russie. Leur père se nommait Sergey, c’était un prêtre du culte du « Grand Savoir » qui eut des soucis avec la justice de l’URSS et se retrouva protégé par la Vladivostokskaia, la mafia locale en nouant de forts liens avec. Forcément, Yegor et Arkady grandirent avec la dette de leur père et nouèrent des amitiés profondes avec les mafieux, Arkady finissant par devenir un des plus loyaux hommes de main de Kireyev Semyon VALENTINOVICH, Yegor, de son coté, s’éloigna de la mafia pour se passionner par les sciences. Il quitta Vladivostok pour étudier en Europe, où en Angleterre, il obtint deux doctorats, un physique appliqué et un en sciences neuronales, deux domaines très éloignés, preuve d’un génie rare. Pour fêter l’obtention de ses doctorats, en 2004, à 28 ans, il voyagea en Espagne avec sa petite amie, Lydia ANDREEVNA. Mais durant le voyage, une brune mystérieuse tua Lydia sous les yeux de Yegor, lui ordonnant de la sauver. Yegor ne comprit rien, bien qu’il eût vaguement connaissance des croyances de son père, cela faisait longtemps qu’il avait délaissé le folklore pour n’être qu’un scientifique, Ana Diana tua quarante deux fois Lydia sous les yeux de yegor, la ressuscitant à chaque fois pour pousser le cultiste à éveiller ses « yeux d’or ». Sans grand suspens, Yegor ne parvint pas à sauver sa petite amie mais dans son profond désespoir et sa colère alors qu’il pleurait la jeune femme, il essaya d’exploser le crane de la prêtresse par pure rage instinctive, ce qui marqua son entrée dans le culte, bien qu’il ne provoquât qu’une migraine à l’abomination. Yegor fut formé, en 2008, Ana Diana le renvoya à sa vie de scientifique avec pour ordre de ramener son frère ici avant cela. Yegor reprit sa vie de scientifique avec l’envie d’assassiner Ana Diana un jour, pratiquant sans cesse ses pouvoirs, pendant la guerre il suivit le PCRC et aida au projet Phoenix, grâce à ses yeux d’or, il était l’un des seuls scientifiques à ressusciter les soldats quasiment morts, voyant ce qui clochait et réparant les corps mécaniquement. Il se prit de passion pour une jeune femme nommée Hailey POWELL, la considérant à lui puisque l’ayant sauvé d’une mort certaine, la trafiquant physiquement, l’améliorant, essayant d’en faire une arme plus performante et sa poupée sexuelle à la fois. Néanmoins, Levanah et Leslie réalisèrent que les données de Hailey différaient trop des autres sujets, et attrapèrent Yegor à la baiser, le virant du projet et reprenant ses notes de zéro pour s’assurer qu’il n'avait pas tout fausser, un traitre dans l’équipe ruinant les données depuis un moment. Yegor travailla alors pour les Nord-coréens mais son aide ne servit pas. Recherché pour trahison internationalement, il se constitua comme une sorte de mercenaire de la science et répara son frère, tué après la guerre par une prostituée blonde nommée Svetlana."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}],"legacyTargetId":"pnj-105-yegor-karamov","navigation":{"group":"Corruption & menaces","groupOrder":80,"subgroup":"Abominations","subgroupOrder":20,"pageOrder":500}},{"id":"pnj-fleaux-focus-arkady-karamov-4-arkady-karamov","dataset":"verite-fleaux-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Arkady KARAMOV","source":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Fléaux","Focus Fléaux 2026-09","Abomination","« Créatures »"],"pnj":{"completeness":"detailed","real_name":"Arkady KARAMOV","nom_verite":"Yegor KARAMOV","race":"Abomination","age":"«57 ans » / -","origine":"Russe","statut":"« Créatures »","affiliations":"« Créatures »","relations":[],"identity_keys":["Arkady KARAMOV","Yegor Karamovich","Yegor KARAMOV"]},"loreBook":{"focusBatch":"fleaux-focus-2026-09-v1","focusSource":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx"},"sections":[{"id":"fleaux-focus-dossier","title":"Dossier — Focus Fléaux","level":2,"blocks":[{"type":"p","style":"Normal","text":"Apôtre du grand Savoir"},{"type":"p","style":"Normal","text":"Nom de la Réalité : Arkady KARAMOV Nom de la Vérité :Yegor KARAMOV Age : «57 ans » - Affiliations : « Créatures » Nationalité d’origine : Russe Ethnie réelle : Abomination"}]},{"id":"fleaux-focus-realite","title":"Informations Réalité — Focus Fléaux","level":2,"blocks":[{"type":"p","style":"Normal","text":"Yegor et Arkady KARAMOVICH sont nés en Russie. Leur père se nommait Sergey, c’était un prêtre du culte du « Grand Savoir » qui eut des soucis avec la justice de l’URSS et se retrouva protégé par la Vladivostokskaia, la mafia locale en nouant de forts liens avec. Forcément, Yegor et Arkady grandirent avec la dette de leur père et nouèrent des amitiés profondes avec les mafieux, Arkady finissant par devenir un des plus loyaux hommes de main de Kireyev Semyon VALENTINOVICH, Arkady, moins intelligent que son frère, s’enfonça dans la violence et la prostitution. Fou d’une blonde sculpturale nommée Lera Ivanovna, Arkady, une serveuse et strip-teaseuse, Arkady était un chien fou qui ne recula devant aucune mission pour monter dans la mafia, même si son mentor, Semyon, ne croyait pas vraiment en lui, préférant Dragomir Mikhaïlovich, plus vieux et plus solide. Arkady se lança donc dans l’armée pour avoir la « dureté » et la rigueur qu’on lui reprochait de ne pas avoir. Quand il revint à Vladivostock, après 5 ans de service, Spetsnaz musclé et sûr de lui, il se rendit compte que son absence ne lui avait pas tant profiter qu’il ne l’imaginait. Sa petite amie s’était mise avec un ancien marin reconverti dans la cuisine, elle avait une gamine de cinq ans et un de deux ans. Semyon était totalement installé mais plus grand monde ne se souvenait d’Arkady, il fut obligé de recommencer son ascension de la base. Malgré tout, Arkady s’acharna et 6 ans plus tard, il était un mafieux plutôt bien intégré quoi qu’il ne digérât pas la trahison de Lera et encore moins que sa sale gamine de 11 ans, Svetlana, ne soit aussi adorée par Semyon. Arkady prit sous son aile Luka NIKITOVICH, qui était le fils d’une cousine et un jeune plein de volonté comme il l’était. Un jour de 2009, Yegor ordonna à Arkady de se rendre en Espagne, sans discuter, les deux frères ayant toujours été très proches et lié, le mafieux accepta et fut torturé par Ana Diana, avant d’être formé comme prêtre du « grand Savoir ». Changé à jamais, il continua sa vie de mafieux et de résistant pendant la guerre. A la fin de celle-ci, il soutint néanmoins Luka quant à la succession de Semyon et s’empressa de séquestrer Lera, la mère de Svetlana afin de la faire cesser toute volonté de succession. Luka fut tué par Svetlana mais elle rata Arkady bien qu’elle ne libérât sa mère. En 2033, quelques heures avant qu’elle ne quitte définitivement Vladivostok, Svetlana trouva Arkady dans un trou paumé et l’assassina pour lui faire payer d’avoir touché sa mère. Arkady n’aurait pas pu survivre sans l’intervention de son frère qui lui créa un corps entièrement synthétique et clona son propre cerveau pour remplacer celui d’Arkady, le cyborg créé s’avéra à la fois être Arkady et à la fois être Yegor, si le scientifique passa à autre chose, le mafieux resta sur une profonde envie de vengeance, concevant un plan pour opposer la Bratva au cartel de Sinaloa qu’il exécuta en 2035."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}],"legacyTargetId":"pnj-084-arkady-karamov","navigation":{"group":"Corruption & menaces","groupOrder":80,"subgroup":"Abominations","subgroupOrder":20,"pageOrder":500}},{"id":"pnj-fleaux-focus-sven-scythe--102-sven-scythe","dataset":"verite-fleaux-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Sven SCYTHE","source":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Fléaux","Focus Fléaux 2026-09","Azménorienne-Abomination","Abominations"],"pnj":{"completeness":"detailed","real_name":"Sven SCYTHE","nom_verite":"Selm SCYTHERI’TAYN","race":"Azménorienne-Abomination","age":"«_ » - ???? ans","origine":"Azménorien","statut":"Abominations","affiliations":"Abominations","relations":[],"identity_keys":["Sven SCYTHE","Selm Scytheri","Selm SCYTHERI’TAYN"]},"loreBook":{"focusBatch":"fleaux-focus-2026-09-v1","focusSource":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx"},"sections":[{"id":"fleaux-focus-dossier","title":"Dossier — Focus Fléaux","level":2,"blocks":[{"type":"p","style":"Normal","text":"La noble chasse"},{"type":"p","style":"Normal","text":"Nom de la Réalité : Sven SCYTHE Nom de la Vérité : Selm SCYTHERI’TAYN Age : «_ » - ???? ans Affiliations : Abominations Nationalité d’origine : Azménorien Ethnie réelle : Azménorienne-Abomination"}]},{"id":"fleaux-focus-realite","title":"Informations Réalité — Focus Fléaux","level":2,"blocks":[{"type":"p","style":"Normal","text":"Sven est un émigré Estonien. Quand le pays a officiellement cessé d’exister en 2024, l’émigration a été forte, la Californie a récupéré son lot de ressortissants bien que les megacorporations détentrice du territoire Estonien n’aient tenté de faire passer l’émigration comme de la « concurrence déloyale ». Hélas, Sven n’a pas pu trouver de travail étant donné son mauvais logifate. On ignore trop de quoi il vit, c’est un homme mystérieux et difficile à croiser."}]},{"id":"fleaux-focus-verite","title":"Informations Vérité — Focus Fléaux","level":2,"audience":"mj","blocks":[{"type":"p","style":"Normal","text":"Bien qu’il porte le nom de la très glorieuse famille elfe gris qui donna la non moins célèbre reine et première des elfes noires sur Aèr, Sven est bien un azménorien, certes, il a donc des origines communes avec la reine elfe noire, mais n’est issu que d’une lointaine branche des Scytheri qui ne devraient même plus avoir le nom. Malgré tout, c’est un noble d’une maison déchue, par leur lien de sang avec la famille royale elfe noire, les Scytheri Azménoriens n’ont jamais été influents, ils ont souvent subi les revers des relations entre les deux peuples, méprisés, une certaine disgrâce pour ces lointains descendants de la plus grande famille royale des elfes gris. La majorité des Scytheri’Tayn a totalement fuit Aèr en raison de ce manque de cette position délicate, sur Terre, ils cherchèrent à se refaire une image et quand Kaless Proleyh accéda au trône d’Azménor-than, la mère de Selm, Deivnara Scytheri se montra une de ses plus loyales partisanes sur Terre, pas seulement en soutenant l’effort de guerre dans la conquête du roi sur l’ensemble d’Aèr mais en déportant le conflit sur Terre, les azménoriens terriens s’attaquant aux autres exilés. Hélas, un choix tragique, Kaless, le « roi fou », fut trahi par les huit grandes maisons nobles, et ceux qui avaient osé le suivre jusqu’au bout ne furent pas pardonnés. La mère de Selm en réchappa, mais elle fut traquée. Elle s’offrit à de sombres cultes pour échapper à la colère des autres immigrés d’Aèr. Selm fut le prix à payer pour la survie et la protection de sa mère. C’est une engeance même si on ne sait trop de quoi, il reste globalement azménorien pour ses compétences. Il sert le culte de Vhodhal’nact'ru, « la bouche infinie ». Il n’a que deux buts dans la vie : anéantir le conseil des anciens et trouver Ux’sharith pour la servir, comme son maitre lui a ordonné. Sa maison étant autrefois noble, il a du sang de dragon, mais ses ailes sont absolument difformes."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}],"legacyTargetId":"pnj-102-sven-scythe","navigation":{"group":"Corruption & menaces","groupOrder":80,"subgroup":"Abominations","subgroupOrder":20,"pageOrder":500}},{"id":"pnj-fleaux-focus-mila-shilove-094-mila-shilove","dataset":"verite-fleaux-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Mila SHILOVE","source":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Fléaux","Focus Fléaux 2026-09","Mage","Enders"],"pnj":{"completeness":"detailed","real_name":"Mila SHILOVE","nom_verite":"Miluska VOROSHILOV","race":"Mage","age":"«46 ans » - ????? ans","origine":"Américano-russe","statut":"Enders","affiliations":"Enders","relations":[],"identity_keys":["Mila SHILOVE","Miluska Voroshilov","Miluska VOROSHILOV"]},"loreBook":{"focusBatch":"fleaux-focus-2026-09-v1","focusSource":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx"},"sections":[{"id":"fleaux-focus-dossier","title":"Dossier — Focus Fléaux","level":2,"blocks":[{"type":"p","style":"Normal","text":"La beauté du village perdu"},{"type":"p","style":"Normal","text":"Nom de la Réalité : Mila SHILOVE Nom de la Vérité : Miluska VOROSHILOV Age : «46 ans » - ????? ans Affiliations : Enders Nationalité d’origine : Américano-russe Ethnie réelle : Mage"}]},{"id":"fleaux-focus-verite","title":"Informations Vérité — Focus Fléaux","level":2,"audience":"mj","blocks":[{"type":"p","style":"Normal","text":"Perdu en Alaska, vous trouvez une petite communauté, isolée et totalement méconnue des autres locaux. Des petites maisons de bois, un cadre glacial quoi qu’idyllique, une sublime et radieuse femme en chef de communauté, « la prêtresse Mila » … fuyez. D’une part, pas un de ces habitant n’est innocent, tous sont cannibales, d’autre part, certains ne sont même pas humains, certains sont des Wendigos voire pire quoi que pire n’est pas le mot. Cette femme est un monstre ayant tué père, mère, frères, sœurs, cousins et ses propres enfants pour devenir la plus puissante Mage d’Alaska, et elle les a tous mangé pour cela, sur ordre d’une voix qu’elle est la seule désormais à entendre et à qui elle parle à voix haute. Des villages perdus en Alaska, de « Enders », des survivalistes un peu à l’ancienne, elle en a peut-être une centaine, de vrais pièges pour attirer des créatures, des chasseurs ou bien des gens normaux, toujours pour s’en nourrir, parfois pour avoir leurs pouvoirs. Miluska est absolument sans pitié, elle voit absolument toutes les créatures comme un repas, peu importe la taille, la forme ou l’amitié nouée avec elle, elle est complétement obsédée par le gout des choses, par le besoin de manger les gens et de savoir quel don ou quelle émotion ils donneront. C’est une drogue pour elle qu’elle cherche à partager à travers le culte de Vhodhal. Elle vénère le Fléau et le considère comme le plus puissant de tous, celui qui peut absolument tout dévorer, la mort, le temps, l’espace, il dévore tout. Si sa main gauche est plus pâle que le reste de son corps, c’est qu’elle l’a déjà dévoré, cru, la rongeant à l’os un jour où elle était seule. Elle sait pertinemment qu’elle envoie au Néant tout ce qu’elle dévore et qu’elle ne conserve pas, elle n’en a plus rien à faire, ayant même étudié les pouvoirs du néant eux-mêmes avant d’abandonner. Son pire ennemi est Edwin KELLY, de la loge de Portland, s’il ne peut rien contre elle, loin de l’égaler magiquement, il peut contrôler les hordes de Wendigo ou de bêtes faramines qui grouillent autour d’elle, plus ils ont faim, moins ils ont de conscience et plus ses dons magiques de maitrise sur les bêtes fonctionnent."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}],"legacyTargetId":"pnj-094-mila-shilove","navigation":{"group":"Corruption & menaces","groupOrder":80,"subgroup":"Abominations","subgroupOrder":20,"pageOrder":500}},{"id":"pnj-fleaux-focus-maximilian-valentin-von-stroheim-tin-von-stroheim","dataset":"verite-fleaux-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Maximilian Valentin von STROHEIM","source":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Fléaux","Focus Fléaux 2026-09","Vampire","crawler (hooker et fixer)"],"pnj":{"completeness":"detailed","real_name":"Maximilian Valentin von STROHEIM","nom_verite":"Maximilian Valentin von STROHEIM","race":"Vampire","age":"« 26 ans » - ?? ans","origine":"Autrichienne","statut":"crawler (hooker et fixer)","affiliations":"crawler (hooker et fixer)","relations":[],"identity_keys":["Maximilian Valentin von STROHEIM","Maximilian Valentin Von Stroheim"]},"loreBook":{"focusBatch":"fleaux-focus-2026-09-v1","focusSource":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx"},"sections":[{"id":"fleaux-focus-dossier","title":"Dossier — Focus Fléaux","level":2,"blocks":[{"type":"p","style":"Normal","text":"Le roi solaire"},{"type":"p","style":"Normal","text":"Nom de la Réalité : Maximilian Valentin von STROHEIM Nom de la Vérité : Maximilian Valentin von STROHEIM Age : « 26 ans » - ?? ans Affiliations : crawler (hooker et fixer) Nationalité d’origine : Autrichienne Ethnie réelle : Vampire"}]},{"id":"fleaux-focus-verite","title":"Informations Vérité — Focus Fléaux","level":2,"audience":"mj","blocks":[{"type":"p","style":"Normal","text":"Maximilian est un vampire né au XVIIème siècle, c’est un vampire de pure lignée qui avait une famille aussi influente au sein de la Krovni que dans le Saint-Empire romain germanique. Il s’est d’ailleurs illustré lors de la bataille de Nördlingen, face aux Suèdois protestants et surtout leurs loups garous des pelages blancs où il blessa gravement Thorunn de l’époque (la Meneuse) malgré son jeune âge. Extrêmement Talentueux et puissant, par le jeu politique, il fut marié à la princesse Hécate qui venait de perdre son 92ème mari. Durant le siècle suivant, il voyagea beaucoup, notamment aux Amériques, et explora les terres sauvages de l’Alaska. Il y rencontra le Fléau Siadara, qu’il pensa être un vampire, après une brève relation il s’en retourna sur le vieux continent, mais réalisa être extrêmement malade. Atteint de la famine Blanche, que la Krovni connaissait déjà, les vampires étant très sensibles aux afflictions des fléaux, il fut répudié, mis au ban de la société, puis assez vite on lui lança des hordes de Lavandières. Les assassins ne tuèrent pas seulement que le traqué mais toute la lignée Von Stroheim fut purgée, comme pour effacer la souillure qu’était l’existence de ce nom. Cela comprenait la jeune Annalena Von STROHEIM, la fille de Maximilian et Hécate, que la princesse tua elle-même malgré l’immense rareté des sangs purs de sa lignée. Maximilian n’accepta pas son destin, il supplia le Mage Faust de l’aider, le Mage s’y essaya mais préféra fuir la compagnie du vampire qui travailla l’Alchimie seul, le vampire ne trouvant aucun moyen de combattre la « famine blanche » mais trouva comment l’utiliser pour dévorer la « malédiction du sang noir », son sang devint blanc. Maximilian n’a pas besoin de boire du sang, ne craint rien comme un vampire, c’est un être assez différent, aucun chasseur de vampires ne saurait l’abattre puisque cette abomination n’est qu’un wendigo dans un corps vampire, maitre de lui. Il s’est lui-même déclaré « Roi des sangs d’ivoires », c’est-à-dire tous les vampires qu’il créa depuis qu’il joua avec l’Alchimie. Cependant, sa faim est réelle et immense, il doit dévorer des quantités énormes de matière vivante et de magie pour rester maitre de lui-même c’est pourquoi il vénère Vhodhal, espérant, à tort, que le Fléau n’atténue un jour sa faim."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}],"legacyTargetId":"pnj-093-maximilian-valentin-von-stroheim","navigation":{"group":"Figures de Vérité","groupOrder":70,"subgroup":"Vampires","subgroupOrder":10,"pageOrder":500}},{"id":"pnj-fleaux-focus-arthur-savas-085-arthur-savas","dataset":"verite-fleaux-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Arthur SAVAS","source":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Fléaux","Focus Fléaux 2026-09","Abominations","Religieux"],"pnj":{"completeness":"detailed","real_name":"Arthur SAVAS","nom_verite":"Aristaeus","race":"Abominations","age":"«66 ans » - ????? ans","origine":"grecque","statut":"Religieux","affiliations":"Religieux","relations":[],"identity_keys":["Arthur SAVAS","Aristaeus"]},"loreBook":{"focusBatch":"fleaux-focus-2026-09-v1","focusSource":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx"},"sections":[{"id":"fleaux-focus-dossier","title":"Dossier — Focus Fléaux","level":2,"blocks":[{"type":"p","style":"Normal","text":"Le grand prêtre de l’Evolution"},{"type":"p","style":"Normal","text":"Nom de la Réalité : Arthur SAVAS Nom de la Vérité : Aristaeus Age : «66 ans » - ????? ans Affiliations : Religieux Nationalité d’origine : grecque Ethnie réelle : Abominations"}]},{"id":"fleaux-focus-verite","title":"Informations Vérité — Focus Fléaux","level":2,"audience":"mj","blocks":[{"type":"p","style":"Normal","text":"Arthur SAVAS est un prêtre de l’Eglise Chrétienne réformée. Initialement c’était un religieux orthodoxe en Grèce, mais il a émigré aux Etats-Unis puis en Californie durant les années 2030. Ami du père GRAFF, il reste assez discret sur la scène religieuse, préférant s’occuper d’une petite communauté isolée. C’est le Grand Maître du culte de Vhadhi en vérité et sa secte a beau se cacher au sein-même de l’Eglise Chrétienne, plus d’une fois les chasseurs de l’Eglise ont abattu de ses enfants. Ce n’est pas un humain, c’est une abomination, un ancien Khinae déformé par les pouvoirs de Vhadhi, il n’a jamais cessé de dévorer des humains mais a une préférence nette pour les nourrissons. C’est pour cette raison qu’absolument toute la fonction sacerdotale revient à des femmes, des prêtresses, puisqu’il exige dans leur acte de foi un tribut en enfant, au moins un bébé chacune doit être conçu et sacrifié, mais cela n’a pas vraiment de lien avec le culte et les croyances, c’est uniquement pour son appétit égoïste et déformé. Il possède sept formes par les pouvoirs de Vhadhi, la première semble celle d’une forme d’humain, la seconde, proche est sa forme hybride, des myriades d’excroissances de chair sur sa tête et son dos s’agitent anarchiquement. Sa troisième forme est proche d’un Dive, un colosse gras et livide à la peau d’ivoire, débordant de gras et de lambeaux de chair flasque encaissant les frappes physiques. Sa quatrième forme est celle d’une sorte de khinae géant de huit mètres, blanc, maigre, à la tête déformée et large, couvert de tentacules à la place d’un pelage sur le dos. Sa cinquième forme devient difficile à décrire, elle est similaire à celle d’un cachalot qu’on aurait doté de pattes de chenilles faites en têtes de lamproies, toute sa peau étant parcourue de trous n’étant que des bouches bardées de dents. Sa sixième forme est celle d’un œuf de chair et de gras, couvert de plis et de rides, des milliers de petites mains de bébé semblent essayer de passer à travers la peau, dans cette forme aussi abjecte que simple, il semble capable d’évoluer à une vitesse hallucinante et sa résistance aux pouvoirs est monstrueuse, sa régénération aussi. Sa dernière forme est variable, elle est fonction de ce qu’il a enduré dans sa forme précédente, elle est le résultat de son évolution pour être insensible à son ennemi. C’est un être abject qui sait pertinemment que le paradis promis est un lieu de souffrances et d’altérations mais il est récompensé pour chaque âme qu’il y envoie."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}],"legacyTargetId":"pnj-085-arthur-savas","navigation":{"group":"Corruption & menaces","groupOrder":80,"subgroup":"Abominations","subgroupOrder":20,"pageOrder":500}},{"id":"pnj-fleaux-focus-margareta-diaconescu-areta-diaconescu","dataset":"verite-fleaux-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Margareta DIACONESCU","source":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Fléaux","Focus Fléaux 2026-09","Daemons (abomination)","Religieux"],"pnj":{"completeness":"detailed","real_name":"Margareta DIACONESCU","nom_verite":"Héméra","race":"Daemons (abomination)","age":"« 42 ans » - ?? ans","origine":"Roumaine","statut":"Religieux","affiliations":"Religieux","relations":[],"identity_keys":["Margareta DIACONESCU","Margareta Diaconescu","Héméra"]},"loreBook":{"focusBatch":"fleaux-focus-2026-09-v1","focusSource":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx"},"sections":[{"id":"fleaux-focus-dossier","title":"Dossier — Focus Fléaux","level":2,"blocks":[{"type":"p","style":"Normal","text":"La prêtresse de la génétique"},{"type":"p","style":"Normal","text":"Nom de la Réalité : Margareta DIACONESCU Nom de la Vérité : Héméra Age : « 42 ans » - ?? ans Affiliations : Religieux Nationalité d’origine : Roumaine Ethnie réelle : Daemons (abomination)"}]},{"id":"fleaux-focus-verite","title":"Informations Vérité — Focus Fléaux","level":2,"audience":"mj","blocks":[{"type":"p","style":"Normal","text":"Margareta est une nonne d’une petite église isolée en Californie, cette ressortissante roumaine ayant émigré lors des grandes insurrections européennes. Elle a un accent roumain assez prononcé encore en 2035. Assez belle rousse au regard embrasé et à la peu très pâle, elle semble avoir un charme surnaturel qui lui vaut souvent la méfiance des créatures ayant un savoir sur la Vérité. Contrairement à tous les signes qu’elle donne, elle n’a rien d’un vampire néanmoins, n’en a jamais été un et n’en possède aucun don. Elle est presque l’opposé d’un vampire en vérité, puisque cette Démone servait initialement le dieu de Lumière, Lucifer. Surnommée Héméra dans la mythologie grecque, c’’était l’intendante de la dimension infernale de Lucifer, pour ne pas dire son bras-droit et la plus puissante de ses servantes. Assez attachée à son maitre, elle a longuement insisté pour calmer sa jalousie contre Elynea, elle a souvent été douce avec l’émigrée, essayant de faire pardonner son maitre les humiliations infligées à l’amante de la reine des dieux. Hélas, Héméra n’arriva pas à raisonner son maitre et sa relative douceur, intéressée mais réelle, n’arriva pas à toucher Elynea. Après la chute de Lucifer, Héméra s’occupa d’évacuer la bulle dimensionnelle, préférant vider les âmes en les cédant à Belial que de risquer un effondrement dimensionnel si Lucifer tardait à regagner assez de puissance, ainsi, Dieux et Archanges pensèrent la dimension vide. Elynea enferma Vhadhi dans cette dimension, elle n’ignorait pas que si aucune âme n’y restait, Héméra et une douzaine de divinités mineures y étaient encore, à essayer de restaurer le pouvoir de Lucifer, se prenant le Fléau et ses pouvoirs directement, dans une bulle dimensionnelle confinée. Héméra subit des millions de supplices par l’altération de sa nature, de ses pouvoirs avant de maitriser, petit à petit l’évolution qu’elle prenait. Elle reforgea son âme pendant des siècles, des millénaires et s’échappa de la dimension. Dépourvue d’envie de vengeance, elle réalisa avoir tellement changé qu’elle était une part de Vhadhi et Vhadhi était une part d’elle-même, tout comme les autres divinités mineures sacrifiées. Elle approcha le culte de Vhadhi, considérant que le Fléau, était l’absolu source de pouvoir pour peu qu’on ait la volonté assez forte pour la surpasser, comme elle le fit ou le fit Elynea. Elle laisse les commandes du culte à Aristaeus mais s’occupe des menaces supérieures, en l’état, elle a assez d’expérience pour repousser même un dieu ou un Archange supérieur si elle le désirait."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}],"legacyTargetId":"pnj-092-margareta-diaconescu","navigation":{"group":"Corruption & menaces","groupOrder":80,"subgroup":"Abominations","subgroupOrder":20,"pageOrder":500}},{"id":"pnj-fleaux-focus-ulfric-tamer-104-ulfric-tamer","dataset":"verite-fleaux-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Ulfric TAMER","source":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Fléaux","Focus Fléaux 2026-09","Fléau supérieur","« Créatures »"],"pnj":{"completeness":"detailed","real_name":"Ulfric TAMER","nom_verite":"Rulfam","race":"Fléau supérieur","age":"« 55 ans » - ???? ans","origine":"suédois","statut":"« Créatures »","affiliations":"« Créatures »","relations":[],"identity_keys":["Ulfric TAMER","Ulfric Tamer","Rulfam"]},"loreBook":{"focusBatch":"fleaux-focus-2026-09-v1","focusSource":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx"},"sections":[{"id":"fleaux-focus-dossier","title":"Dossier — Focus Fléaux","level":2,"blocks":[{"type":"p","style":"Normal","text":"Dragon fléau"},{"type":"p","style":"Normal","text":"Nom de la Réalité : Ulfric TAMER Nom de la Vérité : Rulfam Age : « 55 ans » - ???? ans Affiliations : « Créatures » Nationalité d’origine : suédois Ethnie réelle : Fléau supérieur"}]},{"id":"fleaux-focus-verite","title":"Informations Vérité — Focus Fléaux","level":2,"audience":"mj","blocks":[{"type":"p","style":"Normal","text":"Ulfric TAMER est un ender, un crawler des souterrains de « Losttown », une communauté de parias vivant sous terre. Il en est le leader en vérité, et Losttown a beau être l’Eldorado pour certain, un lieu sans corporation, sans loi gouvernementale, sans haute technologie malsaine, mais doté d’un marché noir sans limite, c’est en vérité un trou à rats, aussi putride que rempli de déchets de la société qui n’en peuvent plus du Logifate mais se refusent à se salir de trop les mains en faisant les vrais crawlers. Rulfam est un fléau supérieur et un dragon. C’est le dernier « enfant de Tiamat » en vie. L’ordre des chevaliers sauroctones le cherche activement pour lui faire la peau, littéralement. Losttown n’est pas que son antre c’est aussi le repaire du plus grand culte de Shaoggith au monde. Là-bas, tout est mis en en œuvre pour glorifier la « Mère ». Les chasseurs sont rapidement tués en vérité, car les rues sont remplies d’abominations mineures et de monstres reptiliens. Les Mo’sens sont assez nombreux, immunisés aux émanations magiques cédant des écailles. C’est aussi à Losttown que se trouve la plus grande communauté de Xewens sur Terre. Ulfric est le « maitre » de la cité souterraine, s’il vénère sa mère, il sait qu’un jour prochain, les dieux ou des agents de ces derniers trouveront Losttown et tenteront quelque chose. Pour se prémunir de ce jour, Ulfric s’est assuré plusieurs portails sur la dimension des Dives ainsi qu’une Loge renégate de Mages, la famille Apophis, des mages liés aux serpents fanatiques de Shaoggith. Le plus grand ennemi de TAMER est Siegfried qui a été formé par son père, Shorolth, c’est un chevalier de l’ordre des Sauroctone, le père biologique de Tiamandra VECELLIO et un démon de Belial désormais."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}],"legacyTargetId":"pnj-104-ulfric-tamer","navigation":{"group":"Corruption & menaces","groupOrder":80,"subgroup":"Fléaux & figures de Rupture","subgroupOrder":10,"pageOrder":500}},{"id":"pnj-fleaux-focus-leona-elliott-90-leona-elliott","dataset":"verite-fleaux-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Leona ELLIOTT","source":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Fléaux","Focus Fléaux 2026-09","Mo’senne","corporation- REPTILE – culte de Gajh’ shaoggith"],"pnj":{"completeness":"detailed","real_name":"Leona ELLIOTT","nom_verite":"Li’loth","race":"Mo’senne","age":"«26 ans » - ????? ans","origine":"Américaine","statut":"corporation- REPTILE – culte de Gajh’ shaoggith","affiliations":"corporation- REPTILE – culte de Gajh’ shaoggith","relations":[],"identity_keys":["Leona ELLIOTT","Leona Elliott","Li’loth"]},"loreBook":{"focusBatch":"fleaux-focus-2026-09-v1","focusSource":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx"},"sections":[{"id":"fleaux-focus-dossier","title":"Dossier — Focus Fléaux","level":2,"blocks":[{"type":"p","style":"Normal","text":"Présidente de Monarch system corporation"},{"type":"p","style":"Normal","text":"Nom de la Réalité : Leona ELLIOTT Nom de la Vérité : Li’loth Age : «26 ans » - ????? ans Affiliations : corporation- REPTILE – culte de Gajh’ shaoggith Nationalité d’origine : Américaine Ethnie réelle : Mo’senne"}]},{"id":"fleaux-focus-realite","title":"Informations Réalité — Focus Fléaux","level":2,"blocks":[{"type":"p","style":"Normal","text":"Leona ELLIOTTT est un mannequin de la Tuatha corporation. Sa chevelure teinte d’un rouge sanglant et naturellement rousse ardente est un de ses plus bel arguments physiques, ses yeux d’un noisette presque jaune lui donnent un regard d’aigle, ses courbes parfaites répondent aux canons de beauté de la Tuatha et plus d’une fois elle a posé avec la grande présidente, Siobhain, faisant d’elle une des stars montantes de la mode dans la corporation. Elle est excessivement belle et semble plus que douée dans tous les arts."}]},{"id":"fleaux-focus-verite","title":"Informations Vérité — Focus Fléaux","level":2,"audience":"mj","blocks":[{"type":"p","style":"Normal","text":"Derrière les traits de Leona se dissimule une des créatures les plus maléfiques de Terra Umbra. Officiellement, dans la Vérité, c’est une servante de la « T-ra’queen », la grande maitresse du REPTILE, une mutante au sang génétiquement brassé d’humain et de Mo’sen. Ti’Rakyn lui fait confiance pour reléguer ses ordres et lui obéir loyalement, comme de nombreuses autres femelles mo’sen qu’elle a comme esclaves-servantes. Cependant, les véritables intentions de Li’loth sont légèrement différentes, elle est la plus ancienne servante de Shaoggith, la mère des abominations reptiliennes, le Fléau majeur surnommé « Tiamat » qui engendra certaines abominations, certains deimons mais également des chasseurs tels que l’ordre de Saint-George. Shaoggith ne sait pas se diviser contrairement à V’Aagor ou Sharith, alors elle confia ses pouvoirs à une créature au hasard, dans la galaxie, quand elle fut vaincue. C’est Li’loth qui en hérita et avec son culte, chercha désespérément le « monde-tombeau ». Il se pourrait que Shaoggith soit la « Mère primordiale » des cultes Mo’sens, Chezzons et Xewens et Li’loth sa première prêtresse, on ignore toutefois si le culte naquit bien avant sa défaite ou exactement quand elle fut enfermée. Actuellement, Li’loth est donc l’intégrale détentrice de la nature de Shaoggith, si les dieux parvenaient à déchirer « l’âme » du Fléau, qui résiste depuis sa défaite, Li’loth serait alors complétement le Fléau et prendrait le nom de Li’loth Shaoggith. Elle est actuellement capable de rivaliser avec n’importe quel archange ou dieu ancien, mais sa survie dépend bien plus de sa discrérion que de sa puissance. Un de ses buts est d’anéantir le culte de V’Aagor qu’est celui mené par l’Ombre-Pape, les membres de son culte secret ayant donc à cœur de tuer son Messie : Stephania Volkov et de récupérer le leur : Tiamandra Vecellio, l’ultime créature possédant la peau de Shaoggith, seule rivale à Li’loth pour devenir Shaoggith."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}],"legacyTargetId":"pnj-090-leona-elliott","navigation":{"group":"Corruption & menaces","groupOrder":80,"subgroup":"Abominations","subgroupOrder":20,"pageOrder":500}},{"id":"pnj-fleaux-focus-aberration-z-87--aberration-z-87","dataset":"verite-fleaux-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Aberration Z-87","source":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Fléaux","Focus Fléaux 2026-09","Mo’senne (abomination)","Abominations"],"pnj":{"completeness":"detailed","real_name":"Aberration Z-87","nom_verite":"Shy’Krerath","race":"Mo’senne (abomination)","age":"« ?? ans » - ?? ans","origine":"","statut":"Abominations","affiliations":"Abominations","relations":[],"identity_keys":["Aberration Z-87","Shy Krerath","Shy’Krerath"]},"loreBook":{"focusBatch":"fleaux-focus-2026-09-v1","focusSource":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx"},"sections":[{"id":"fleaux-focus-dossier","title":"Dossier — Focus Fléaux","level":2,"blocks":[{"type":"p","style":"Normal","text":"Les crocs de Shaoggith"},{"type":"p","style":"Normal","text":"Nom de la Réalité : Aberration Z-87 Nom de la Vérité : Shy’Krerath Age : « ?? ans » - ?? ans Affiliations : Abominations Nationalité d’origine : _ Ethnie réelle : Mo’senne (abomination)"}]},{"id":"fleaux-focus-realite","title":"Informations Réalité — Focus Fléaux","level":2,"blocks":[{"type":"p","style":"Normal","text":"Octobre 1974, sur une île du nord du Japon, a été aperçue l’Aberration z-87, haute de 57 mètres disparaissant dans un tunnel qui s’effondra juste après son passage. La presse Japonaise parla d’un canular de Godzilla, les gouvernements nièrent toute réalité des faits."}]},{"id":"fleaux-focus-verite","title":"Informations Vérité — Focus Fléaux","level":2,"audience":"mj","blocks":[{"type":"p","style":"Normal","text":"Shy’Krerath est une fille de Li’Loth et d’un xewen du culte de Shaoggith. Elle est capable de grandir jusqu’à une centaine de mètres de haut, de se déformer, plus elle grandit, plus sa forme devient sombre alors qu’elle est une Mo’senne relativement normale dans sa forme basique. Par sa nature, elle a hérité de pouvoirs des fléaux, l’hologramme ne peut la dissimuler dès la seconde où elle use du moindre pouvoir, comme pour la révéler aux Dieux et sonner l’alerte, elle est donc obligée de vivre sous terre avec le reste du culte. Bien qu’elle évoque vaguement Godzilla, elle n’est pas vraiment à la recherche de combats dans les rues contre d’autres géants, la douleur immense qu’elle ressent en grossissant est difficile à supporter, en elle, certains atomes fusionnent, son noyau devenant un véritable réacteur à fusion nucléaire, non sans la bruler. Bien que lancer sur des rues une créature incapable de se cacher et possiblement géante ne soit en rien discret, le culte de Shaoggith l’utilise comme assassine quand un traitre au culte est identifié, elle rase alors une partie de la ville ou le village entier où la personne se réfugie. Il n’y a jamais de survivants à ses assauts et les témoins arrivant après constatent toujours les dégâts d’un impact météoritique. Nourrie aux autres abominations, elle chasse parfois dans les profondeurs pour se nourrir d’hommes-poissons et de leurs alliés rocréens des abysses car sa véritable mission est de dévorer les autres prêtres et serviteurs abominables des grands Fléaux, jusqu’à ce que seule Shaoggith ne demeure. En 2035, le Mage Faust l’a néanmoins invoquée dans le désert du Nevada et lui créa une amulette pour qu’elle nait une forme humaine malgré ses pouvoirs, le sournois magicien essaie depuis d’en faire une alliée, en lui faisant découvrir Los Angeles, Krerath n’est pas dupe mais être une abomination recluse dans les souterrains est pesant depuis des millénaires, son hésitation se renforçant petit à petit, ne voyant pas forcément l’intérêt de son existence dans les tunnels."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}],"legacyTargetId":"pnj-081-aberration-z-87","navigation":{"group":"Corruption & menaces","groupOrder":80,"subgroup":"Abominations","subgroupOrder":20,"pageOrder":500}},{"id":"pnj-fleaux-focus-olla-berwick-099-olla-berwick","dataset":"verite-fleaux-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Olla BERWICK","source":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Fléaux","Focus Fléaux 2026-09","Humaine","Corporatistes (Eversor) -Abominations"],"pnj":{"completeness":"detailed","real_name":"Olla BERWICK","nom_verite":"Olla BERWICK","race":"Humaine","age":"« 30 ans » - ?? ans","origine":"Americaine","statut":"Corporatistes (Eversor) -Abominations","affiliations":"Corporatistes (Eversor) -Abominations","relations":[],"identity_keys":["Olla BERWICK","Olla Berwick"]},"loreBook":{"focusBatch":"fleaux-focus-2026-09-v1","focusSource":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx"},"sections":[{"id":"fleaux-focus-dossier","title":"Dossier — Focus Fléaux","level":2,"blocks":[{"type":"p","style":"Normal","text":"L’abomination divine"},{"type":"p","style":"Normal","text":"Nom de la Réalité : Olla BERWICK Nom de la Vérité : Olla BERWICK Age : « 30 ans » - ?? ans Affiliations : Corporatistes (Eversor) -Abominations Nationalité d’origine : Americaine Ethnie réelle : Humaine"}]},{"id":"fleaux-focus-realite","title":"Informations Réalité — Focus Fléaux","level":2,"blocks":[{"type":"p","style":"Normal","text":"Olla est la présidente de la branche restauration au sein de l’Eversor Corporation fondée par Saskia. Elle était une aubergiste sur une île arriérée perdue dans le temps et fut sauvée de sa secte par Veronica SILVER, avec qui elle a une relation depuis."}]},{"id":"fleaux-focus-verite","title":"Informations Vérité — Focus Fléaux","level":2,"audience":"mj","blocks":[{"type":"p","style":"Normal","text":"Quand Veronica trucida le Fléau mineur Telipinu par ses balles électrifiées de foudre, elle ignorait certainement qu’elle condamnait la brune pour qui elle avait une attirance. A la mort de Telipinu, son essence est allée dans Andrew, un enfant qu’il possédait et ses pouvoirs ont été dévorés par le corps de l’aubergiste Olla. Il comptait la dévorer plus tard mais Olla a progressivement pris conscience de ses dons quand elle s’est passionnée pour l’occulte, en Californie. Comme ni Veronica ni Saskia n’ont vraiment fait attention à elle, Olla s’est enfoncée dans de longues marches devenant de véritables chasses aux créatures, accompagnée d’un Caith Sidhe. En détruisant de plus en plus de créatures, elle comprit avoir les pouvoirs de « Dieu », du moins celui qu’elle priait autrefois, Telipinu. Après avoir échappé à plusieurs assauts des Rocréens abyssaux, elle se fit approcher volontairement par une secte de Thul, la secte avait piégé un Eon, Heinrich MARSHALL, et faisait croire à ce dieu stellaire qu’il était leur élu. Aux début, Olla voulait surtout en apprendre plus sur les Thuliens dont elle avait le sang mais elle se retrouva prise dans un rituel, les cultistes ayant été avertis par Andrew (telipinu) quant à qui elle était. Ils sacrifièrent Heinrich et Olla à Thul, leurs pouvoirs et leurs âmes se faisant dévorer, cependant, Heinrich ayant été sacrifié avant Olla, elle le dévora afin de se libérer, et échappa au sacrifice après avoir aspiré l’âme de chaque cultiste présent. Profondément traumatisée et touchée par Thul, frôlant la folie, elle cacha cela à Veronica et Saskia, usant de son caractère presque niais malgré ses effroyables cauchemars, détenant la puissance d’un Eon et d’un grand Thulien, Olla retourna au culte pour apprendre à mieux se contrôler, elle fut surprise par des cultistes qui n’étaient pas présents lors du sacrifice et en devint la maitresse. Elle est traquée par Maximilien MARSHAlL, le maitre d’Heimrich mais aussi Ysabel THORNE, une inquisitrice galactique. Officiellement, elle est devenue la cible que devait tuer Saskia initialement, l’ayant dévoré. Elle peut voir parfaitement dans la vérité, Thul lui ayant donné ce don à travers ses cauchemars et sait aussi comment le libérer : en sacrifiant Veronica dans le palais royal de Mu."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}],"legacyTargetId":"pnj-099-olla-berwick","navigation":{"group":"Corruption & menaces","groupOrder":80,"subgroup":"Abominations","subgroupOrder":20,"pageOrder":500}},{"id":"pnj-fleaux-focus-grim-grigoria-ravinsky-rigoria-ravinsky","dataset":"verite-fleaux-pnj","category":"Personnages","sourceCategory":"Vérité","title":"« Grim », Grigoria RAVINSKY","source":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Fléaux","Focus Fléaux 2026-09","Orques","pègre (bratva)"],"pnj":{"completeness":"detailed","real_name":"« Grim », Grigoria RAVINSKY","nom_verite":"Greem’Sha","race":"Orques","age":"« 48 ans » - ???","origine":"Ukrainienne","statut":"pègre (bratva)","affiliations":"pègre (bratva)","relations":[],"identity_keys":["« Grim », Grigoria RAVINSKY","Grim","Greem’Sha"]},"loreBook":{"focusBatch":"fleaux-focus-2026-09-v1","focusSource":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx"},"sections":[{"id":"fleaux-focus-dossier","title":"Dossier — Focus Fléaux","level":2,"blocks":[{"type":"p","style":"Normal","text":"L’abomination verte"},{"type":"p","style":"Normal","text":"Nom de la Réalité : « Grim », Grigoria RAVINSKY Nom de la Vérité : Greem’Sha Age : « 48 ans » - ??? Affiliations : pègre (bratva) Nationalité d’origine : Ukrainienne Ethnie réelle : Orques"}]},{"id":"fleaux-focus-realite","title":"Informations Réalité — Focus Fléaux","level":2,"blocks":[{"type":"p","style":"Normal","text":"Grigoria RAVINSKY était une subordonnée de Drasko VLADIC dans l’escadron fantôme qu’il menait, des pro-russes qui se rallièrent aux troupes de l’Arkhangel durant la guerre de 22-28. Tout comme Drasko, c’était une dure à cuir et une psychopathe en puissance étant donné ce qu’elle avait vécu jusque-là. Contenue seulement par les poings de Drasko jusque-là, suivre un chef tel que l’Arkhangel changea sa vie et si elle n’en devint absolument pas moins violente, elle obtint un but à sa vie, quelque chose qu’elle n’avait jamais eu auparavant. Au sein de la Bratva, on ne parle pas de « Grim », jamais, elle n’existe pas, pas même dans les rangs de Milda et de ses assassins, on n’évoque absolument jamais la mafieuse hormis sous le nom de « l’ukrainienne », en effet, Grim n’est absolument soumise qu’à Drasko et l’Arkhangel, elle n’en fait qu’à sa tête pour le reste et joue les crawlers ou bien les chasseurs la majorité du temps. Si on répugne à l’évoquer dans la Bratva, c’est parce qu’elle n’agit, généralement, que sur ordre de Drasko, et quand une psychopathe reçoit puis interprète des ordres d’un autre psychopathe, souvent, ça tourne mal, très mal comme ce fut le cas avec le village dans les rocheuses où une famille d’oligarque russe refusant de payer un tribut a été simplement massacré."}]},{"id":"fleaux-focus-verite","title":"Informations Vérité — Focus Fléaux","level":2,"audience":"mj","blocks":[{"type":"p","style":"Normal","text":"Greem’Sha est une abomination, elle est née du viol d’une grande guerrière thulkare à une époque reculée par des serviteurs du grand fléau Thul, certains disent qu’elle serait l’engeance-même du « Dieux des profondeurs ». Le sang de fléau ne se porte pas aisément, même chez les orcs, moins regardant sur les origines, greem’sha faisait peur, d’autant plus quand Ashorn la prit dans son harem et n‘en fit un monstre au combat. Elle s’émancipa de son bienfaiteur, cherchant sa propre voie, errant sur Terre. Plus d’une fois, elle fut pourchassée par les sombres cultes, finalement, elle devint une chasseuse de cultistes, elle se fichait des créatures, mais dès qu’elle trouvait des humains ou autre qui glorifiaient des fléaux, elle les purgeait. Elle tomba amoureuse d’un simple humain, Drasko, un taré au demeurant, sentant un inexplicable de le suivre bien que lui ne la considérait que comme une arme, elle tomba aussi amoureuse de l’Arkangel, ne comprenant pas pourquoi ces deux humains la captivaient mais les adorant au point de s’engager corps et âmes pour eux, délaissant pour eux la destruction des cultes de son « père »."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}],"legacyTargetId":"pnj-133-grim-grigoria-ravinsky","navigation":{"group":"Corruption & menaces","groupOrder":80,"subgroup":"Abominations","subgroupOrder":20,"pageOrder":500}}] as Array<Record<string, any>>;
export const COMPENDIUM_VERITE_FLEAUX_NEW_PNJ_ARTICLES = [{"id":"pnj-fleaux-neeba-ngubenani","dataset":"verite-fleaux-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Neeba NGUBENANI","source":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Fléaux","Focus Fléaux 2026-09","Vampire","Corporatiste"],"pnj":{"completeness":"detailed","real_name":"Neeba NGUBENANI","nom_verite":"Neeba NGUBENANI","race":"Vampire","age":"«35 ans » - ???? ans","origine":"Zambienne","statut":"Corporatiste","affiliations":"Corporatiste","relations":[],"identity_keys":["Neeba NGUBENANI","Neeba Ngubenani"]},"loreBook":{"focusBatch":"fleaux-focus-2026-09-v1","focusSource":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx"},"sections":[{"id":"fleaux-focus-dossier","title":"Dossier — Focus Fléaux","level":2,"blocks":[{"type":"p","style":"Normal","text":"Le plus traditionnel des vampires"},{"type":"p","style":"Normal","text":"Nom de la Réalité : Neeba NGUBENANI Nom de la Vérité : Neeba NGUBENANI Age : «35 ans » - ???? ans Affiliations : Corporatiste Nationalité d’origine : Zambienne Ethnie réelle : Vampire"}]},{"id":"fleaux-focus-verite","title":"Informations Vérité — Focus Fléaux","level":2,"audience":"mj","blocks":[{"type":"p","style":"Normal","text":"On ignore quand il est né, à une époque reculée bien avant l’antiquité. C’est un vampire né d’une longue lignée de descendants des Khinae, et bien qu’il ignore ce que sont les Khinae, pour Neeba, son lignage est sa plus grande fierté. Il est à l’origine des vampires de « Oru ayeraye » il en est le roi et le fondateur. Il est aussi le grand conquérant et le grand chasseur, c’est lui qui extermina presque entièrement les « boudas », les hommes-hyènes, équivalent des loups-garous en Afrique, durant des millénaires, durant le commerce triangulaire, il faisait expédier les lignées de bouda pour les faire vendre aux blancs. Il déteste corps et âme les vampires de « l’alghul » et de la « Krovni ». Neeba voue un culte ancien aux « Forces », les Fléaux anciens ayant créé ses ancêtres c’est en cela qu’il déteste les deux factions vampiriques citées plus haut, « l’Alghul » moyen-oriental prônant pour origine « Arawn » un vampire originel maudit par la reine des dieux alors que la Krovni évoque Caïn, maudit par Dieu, Neeba ne pouvant accepter qu’on ne reconnaisse l’œuvre « d’Osh’bawa », le dieu de l’Ombre que seuls les vampires de « L’oru » ne vénèrent. Un point décisif concernant Neeba est sa totale stérilité, évoqué plus tôt, il ne respecte que le lignage chez les vampires et méprise les transformés, pourtant la quasi-totalité de l’espèce en étant. Or, il est parfaitement incapable de se reproduire, il est le dernier de sa lignée et cela le frustre atrocement. Pour cette raison, il semble tout faire pour avoir les faveurs de la déesse Lilith, son seul espoir, espérant qu’au moins elle ne pardonne aux vampires leur crime originel."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}],"navigation":{"group":"Figures de Vérité","groupOrder":70,"subgroup":"Vampires","subgroupOrder":10,"pageOrder":500}},{"id":"pnj-fleaux-fredegonda","dataset":"verite-fleaux-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Fredegonda VONRIM","source":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Fléaux","Focus Fléaux 2026-09","Nains","Abominations (Duergars)"],"pnj":{"completeness":"detailed","real_name":"Fredegonda VONRIM","nom_verite":"fredegonda VONRIM","race":"Nains","age":"« ??? » - ???? ans","origine":"aucune","statut":"Abominations (Duergars)","affiliations":"Abominations (Duergars)","relations":[],"identity_keys":["Fredegonda VONRIM","Fredegonda","fredegonda VONRIM"]},"loreBook":{"focusBatch":"fleaux-focus-2026-09-v1","focusSource":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx"},"sections":[{"id":"fleaux-focus-dossier","title":"Dossier — Focus Fléaux","level":2,"blocks":[{"type":"p","style":"Normal","text":"La sorcière putride"},{"type":"p","style":"Normal","text":"Nom de la Réalité : Aucun Nom de la Vérité : fredegonda VONRIM Age : « ??? » - ???? ans Affiliations : Abominations (Duergars) Nationalité d’origine : aucune Ethnie réelle : Nains"}]},{"id":"fleaux-focus-verite","title":"Informations Vérité — Focus Fléaux","level":2,"audience":"mj","blocks":[{"type":"p","style":"Normal","text":"Fille de Motsognir, elle est connue comme « la Putride » au sens où son âme s’émiette et son corps semble s’altérer comme peu de Duergars. Elle est une Ombre, pas un peu ou de moitié, elle est totalement une ombre désormais et n’a plus grand-chose d’une whurtenne. Afin de survivre, elle a bu l’essence de V’Aagor, le Fléau, dont elle est un fragment de fait, comme l’Ombre-Pape et d’autres entités servant le fléau, étant le fléau sans qu’il ne soit eux. Motsognir la déteste néanmoins, il ne cherchait pas à servir les Fléaux mais à se servir de l’Ombre, être au-dessus de ce pouvoir, l’asservir sans y être soumis. Sa fille a fait ses choix, elle est désormais une créature abominable quoi que puissante. Elle est appelée « vierge des ombres » parmi les siens, car elle crée des Deimons, ses enfants, sans jamais coucher, se refusant aux mâles qui la dégoutent. Pleine de haine et de souffrance, elle est une alliée de l’Ombre-pape à la surface, mais également des prêtres de Thul, un autre fléau majeur, la sorcière naine désirant simplement anéantir les humains et ceux de la surface en déchainant l’Ombre-monde et l’y déversant. Elle ne peut être tuée aisément, elle a déjà été chassée par Azrael, alors qu’elle tentait de s’emparer d’un village en Chine, hélas, l’Archange de la Mort fut face à un choix, l’essence d’Ombre de la naine s’emparait d’elle, la tuer revenait à s’offrir en réceptacle a Fléau qu’elle portait, malgré une victoire, elle la laissa fuir. Les nains qui la suivent sont des opposants à Motsognir au sein des Duergars, tout comme les Nibelungen, les nains de la surface, ne sont pas parfaitement unis entre eux. Ces renégats des souterrains ne sont pas des alliés des nains de la surface, ce sont des extrémistes plus furieux encore que les autres. A l’instar d’Azrael, tous ceux qui tentent de tuer Fredegonda sont corrompus par elle et la servent avant qu’elle ne décède. Sa principale faiblesse est la beauté féminine, elle semble si jalouse et obsédée des belles femmes de la surface qu’elle se perds parfois en ville pour regarder des publicités de Siobhain notamment."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}],"navigation":{"group":"Corruption & menaces","groupOrder":80,"subgroup":"Abominations","subgroupOrder":20,"pageOrder":500}},{"id":"pnj-fleaux-baldwin-de-vandrick","dataset":"verite-fleaux-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Baldwin de Vandrick","source":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Fléaux","Focus Fléaux 2026-09","président de corporation"],"pnj":{"completeness":"detailed","real_name":"Baldwin VANDRICK","nom_verite":"","race":"","age":"70 ans","origine":"Suisse","statut":"président de corporation","affiliations":"président de corporation","relations":[],"identity_keys":["Baldwin de Vandrick","Baldwin VANDRICK"]},"loreBook":{"focusBatch":"fleaux-focus-2026-09-v1","focusSource":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx"},"sections":[{"id":"fleaux-focus-dossier","title":"Dossier — Focus Fléaux","level":2,"blocks":[{"type":"p","style":"Normal","text":"le descendant du fondateur"},{"type":"p","style":"Normal","text":"Nom : Baldwin VANDRICK Age : 70 ans Statut : président de corporation Nationalité d’origine : Suisse"}]},{"id":"fleaux-focus-informations","title":"Informations — Focus Fléaux","level":2,"blocks":[{"type":"p","style":"Normal","text":"Baldwin VANDRICK est un grand riche d’origine suisse, il a fait fortune par ses banques, qui étaient rattachées à un système d’école privées et de dons religieux. Officiellement soutenu par la Vatican. Maitre de l’ordre, il est né en 1965, dans les années 90, il était dans de nombreux conflit africains et asiatiques de même qu’en moyen-Orient. Le chevalier fit mercenaire pour se faire la main sur l’art de la guerre par l’expérience. A côté, il traqua de nombreuses sorcières mais en tua le moins possible, son but était de pousser leur utilisation au maximum et de réduire leur élimination au minimum. Il voulait aussi renouer avec les ordres de chasseurs de l’Eglise dont il savait l’existence, mais jamais le Vatican n’acceptant de les reconnaitre, le suisse ne parvint pas à faire rentrer son vieil ordre dans le moule. Poussé par un profond amour et une admiration pour les pouvoirs des sorcières psycolor, il entreprit d’organiser régulièrement la traque et la comparaison des meilleures, grâce aux découvertes archéologiques, il commença à redouter que la « déesse-mère » des anciennes croyances n’existe vraiment. Hélas, en 2020, il en eut la preuve avec l’éveil de Sharith. Dès lors, l’ordre se démantela tout seul, les sorcières les moins loyales profitant pour dépecer en toute légalité l’empire de Baldwin. Cependant, le réseau demeura, chevaliers et sorcières, pour près de 80% d’entre eux, eurent du mal à se faire une place dans la société, petit à petit, revenant aux anciens de l’ordre pour reconstruire quelque chose de rassurant quand quelques personnalités plus fortes, comme Catalina ou Levanah, s’en éloignèrent à tout jamais. Pendant ses années entre 2020 et 2035, Baldwin fit de grandes recherches sur Sharith, sa foi avait été ébranlée par la puissance du Fléau, le fait d’avoir été rejeté par l’Eglise toute sa vie joua aussi, nourrissant un fanatisme étrange, un fantasme comme quoi, la « déesse-mère » des sorcières n’était pas forcément si maléfique. Récemment, il eut un entretien avec Sharith en personne, la discussion achevant ses doutes quant à la nature divine et bénéfique de celle qu’il redouta tant autrefois."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}],"navigation":{"group":"Corruption & menaces","groupOrder":80,"subgroup":"Abominations","subgroupOrder":20,"pageOrder":500}},{"id":"pnj-fleaux-rolf-de-vandrick","dataset":"verite-fleaux-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Rolf de VANDRICK","source":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Fléaux","Focus Fléaux 2026-09","humaine","crawler (mercs)"],"pnj":{"completeness":"detailed","real_name":"Rolf de VANDRICK","nom_verite":"","race":"humaine","age":"«35 ans » / -","origine":"suisse","statut":"crawler (mercs)","affiliations":"crawler (mercs)","relations":["Amily de VANDRICK","Baldwin de VANDRICK"],"identity_keys":["Rolf de VANDRICK","Rolf de Vandrick"]},"loreBook":{"focusBatch":"fleaux-focus-2026-09-v1","focusSource":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx"},"sections":[{"id":"fleaux-focus-dossier","title":"Dossier — Focus Fléaux","level":2,"blocks":[{"type":"p","style":"Normal","text":"L’ordre des saintes Lagunes"},{"type":"p","style":"Normal","text":"Nom de la Réalité : Rolf de VANDRICK Nom de la Vérité : _ Age : «35 ans » - Affiliations : crawler (mercs) Nationalité d’origine : suisse Ethnie réelle : humaine"}]},{"id":"fleaux-focus-realite","title":"Informations Réalité — Focus Fléaux","level":2,"blocks":[{"type":"p","style":"Normal","text":"Rolf est le fils de l’ancien maitre de l’ordre et le frère de la plus prodigieuse femme chevalier de l’ordre. Il avait 20 ans quand Sharith s’est éveillée, il s’est retrouvé très affecté par la mort de nombreuses amies et personne qu’il connaissait avec l’éveil du Fléau. Contrairement à son père, il n’a jamais parfaitement compris qu’Alisa était- Sharith, la créatrice des sorcières et comme beaucoup d’anciens chevaliers de l’ordre, Sharith n’est pas un fléau mais l’Archange que Lucifer brisa une sorte de déesse de lumière qu’il faut rassembler et se nommait Shariel. C’est pourquoi, en Suisse, après son retour de la guerre du Pacifique, il rassembla des survivants de l’ordre, sorcière comme chevaliers, afin de recréer un « ordre de Shariel ». Héritier direct de l’ordre des Saintes lagunes, c’est un nouvel ordre de cultistes d’Ux’ Sharith, le « jeune » maitre de l’ordre ayant à cœur de retrouver les traitresses, Alisa, Catalina, Amily et d’autres n’étant pas revenue à l’ordre. Bien que le nouveau culte n’ait qu’assez peu de fond, les chevaliers-chasseurs se démènent à des missions de crawlers, tous s’équipant d’augmentations et d’armures de combat évoquant des armures de paladin. Rolf voue une vénération sans faille à « l’Archange Shariel », qui n’est qu’une très mauvaise interprétation que lui et les rares jeunes qui étaient en Suisse ont fait après le massacre d’Alisa. L’Archange Gabrielle ne manqua pas d’en profiter et envoya des serviteurs mais Rolf semble posséder un talent surnaturel pour savoir si quelqu’un ou quelque chose est lié aux fléaux – qu’il pense être des anges- il a donc tué de sang-froid les deux anges qui lui furent envoyés ne sentant pas de psycolor en eux. Il défend les sorcières plus que n’importe quel maitre de l’ordre des saintes Lagunes ne l’a jamais fait."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}],"navigation":{"group":"Chasseurs","groupOrder":60,"subgroup":"Chasseurs & réseaux de Chasse","subgroupOrder":10,"pageOrder":500}},{"id":"pnj-fleaux-raghnaid-maccalmain","dataset":"verite-fleaux-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Raghnaid MACCALMAIN","source":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Fléaux","Focus Fléaux 2026-09","Abomination -","« Créatures »"],"pnj":{"completeness":"detailed","real_name":"Raghnaid MACCALMAIN.","nom_verite":"« pustule cancéreuse »","race":"Abomination -","age":"« 42 ans » - ???? ans","origine":"écossaise","statut":"« Créatures »","affiliations":"« Créatures »","relations":[],"identity_keys":["Raghnaid MACCALMAIN","Raghnaid Maccalmain.","Raghnaid MACCALMAIN.","« pustule cancéreuse »"]},"loreBook":{"focusBatch":"fleaux-focus-2026-09-v1","focusSource":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx"},"sections":[{"id":"fleaux-focus-dossier","title":"Dossier — Focus Fléaux","level":2,"blocks":[{"type":"p","style":"Normal","text":"Secte de Bellatheis"},{"type":"p","style":"Normal","text":"Nom de la Réalité : Raghnaid MACCALMAIN. Nom de la Vérité : « pustule cancéreuse » Age : « 42 ans » - ???? ans Affiliations : « Créatures » Nationalité d’origine : écossaise Ethnie réelle : Abomination -"}]},{"id":"fleaux-focus-verite","title":"Informations Vérité — Focus Fléaux","level":2,"audience":"mj","blocks":[{"type":"p","style":"Normal","text":"Elle n’avait absolument pas de corps humain ni de nom à l’origine, elle ne sait pas vraiment de quoi elle est née ni même si elle est une engeance directe ou indirecte de Sharith, dans tous les cas, elle en est forcément une création. Surnommée « pustule » puisqu’elle était accrochée au corps immense de Sharith, elle a rapidement décidé de fuir en voyant ses frères et sœurs se faire emmener au fur et à mesure qu’ils naissaient, se faisant éliminer pour beaucoup. Elle resta longuement cachée, « Pustule » ayant peur des dieux surtout à la disparition de sa mère. Elle s’empara toutefois de corps humains pour passer inaperçue et entretint les cultes de sa mère avec ses sœurs qu’elle trouva. Elle voulait ramener Sharith à la vie et s’est donc beaucoup donnée. Malgré sa relative insignifiance, elle a toujours été un fléau supérieur dont le talent était de se greffer et fusionner à ce qu’elle touchait peau à peau et la raison est assez simple, elle s’est emparée d’un morceau du corps de sa mère avant de s’enfuir autrefois. Elle est de fait un fragment physique de Sharith. C’est avec ce fragment de corps qu’elle a créé la « grande orbe » et qui lui permet d’altérer les mortels à la condition d’avoir une des deux origines nécessaires. Bien qu’elle soit d’une grande beauté et d’une redoutable intelligence, et bien que ce soit une séductrice comme très peu de créatures le sont, le plus grand talent de « Pustule » est de se cacher quand elle sent le danger. S’insérant dans un corps vivant, elle se réduit à l’état d’une grosseur, un simple cancer inerte et se dégage de là une fois le danger passé. C’est toutefois ainsi qu’elle peut tuer les ennemis physiques, ceux qu’elle tue le plus aisément sont ceux doté d’une grande régénération, s’en délectant comme jamais, elle a, par exemple, déjà repoussé Caïn, très aisément malgré l’immense différence de compétences physiques."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}],"navigation":{"group":"Corruption & menaces","groupOrder":80,"subgroup":"Abominations","subgroupOrder":20,"pageOrder":500}},{"id":"pnj-fleaux-siadara","dataset":"verite-fleaux-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Sianna DANEIN / Siadara","source":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Fléaux","Focus Fléaux 2026-09","Fléau supérieur","« Créatures »"],"pnj":{"completeness":"detailed","real_name":"Sianna DANEIN","nom_verite":"Siadara","race":"Fléau supérieur","age":"« 25 ans » - ???? ans","origine":"allemande","statut":"« Créatures »","affiliations":"« Créatures »","relations":[],"identity_keys":["Sianna DANEIN / Siadara","Siadara","Sianna DANEIN"]},"loreBook":{"focusBatch":"fleaux-focus-2026-09-v1","focusSource":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx"},"sections":[{"id":"fleaux-focus-dossier","title":"Dossier — Focus Fléaux","level":2,"blocks":[{"type":"p","style":"Normal","text":"La famine incarnée"},{"type":"p","style":"Normal","text":"Nom de la Réalité : Sianna DANEIN Nom de la Vérité : Siadara Age : « 25 ans » - ???? ans Affiliations : « Créatures » Nationalité d’origine : allemande Ethnie réelle : Fléau supérieur"}]},{"id":"fleaux-focus-verite","title":"Informations Vérité — Focus Fléaux","level":2,"audience":"mj","blocks":[{"type":"p","style":"Normal","text":"Dans la réalité, Sianna DANEIN est une ex- actrice de Redwheels, elle travaille désormais à yellowfood. Dans la Vérité, elle est une fille de Vhodhal et d’Ux’sharith. C’est un des fléaux supérieurs les plus dangereux. Comme son géniteur, elle peut tout dévorer, comme sa génitrice, elle peut diviser. Contrairement à son père, elle est toutefois parfaitement calme, puisqu’elle divise sa famine enragée afin de ne pas la sentir, elle divise donc son pouvoir paternel constamment pour ne pas en souffrir, limitant donc énormément ses pouvoirs pour se contrôler. Les dieux n’avaient pas conscience de son existence avant de vaincre Vhodhal puis Sharith pour cette raison, comme ils en ignoraient presque tout, ils envoyèrent des dieux mineurs. Elle les a tous dévoré sans rien laissé autre chose que de de son épaisse salive blanche acide. Elle a été en grande partie détruite par R’Gahanath, un autre fléau supérieur, une semi-Vala’Erai, mais comme Vhodhal face à la mère de Gahanath, Siadara apprit à dévorer le temps. Elle n’a pas vraiment de but autre qu’exister, en paix. Toutefois elle est porteuse d’‘une forme d’infection, de rage qui se répand autour d’elle, la « famine blanche ». Toutes les espèces peuvent être touchées, par exemple, les « bêtes Faramines » qui sont des garous morts-vivants squelettiques et albinos sont parfois créé par la « famine blanche », les « sang d’ivoire » sont des vampires corrompus par la famine blanche, la « Loge d’écume » désigne une secte de Mages corrompus qui utilisent la famine blanche pour dévorer la magie, même s’ils en deviennent fous rapidement, les « Noctiels» sont des anges corrompus, la famine blanche fait totalement dégénérer le transcendance, ils dévorent la lumière elle-même. Les « cyclopes » sont les Dives corrompus, tandis que le reste des espèces deviendra plutôt des Wendigos. « Reine des Wendigos » est son autre surnom de fait. Elle cherche à utiliser les rares cultes en l’honneur de son père pour le trouver et le dévorer, car elle est convaincue que ses pouvoirs se calmeront une fois qu’il sera totalement détruit."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}],"navigation":{"group":"Corruption & menaces","groupOrder":80,"subgroup":"Fléaux & figures de Rupture","subgroupOrder":10,"pageOrder":500}},{"id":"pnj-fleaux-roi-du-givre","dataset":"verite-fleaux-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Le Roi du Givre","source":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Fléaux","Focus Fléaux 2026-09","Revenants","Abominations"],"pnj":{"completeness":"detailed","real_name":"Le Roi du Givre","nom_verite":"Le « roi du givre »","race":"Revenants","age":"« ?? ans » - ?? ans","origine":"","statut":"Abominations","affiliations":"Abominations","relations":[],"identity_keys":["Le Roi du Givre","le roi du givre","Le « roi du givre »"]},"loreBook":{"focusBatch":"fleaux-focus-2026-09-v1","focusSource":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx"},"sections":[{"id":"fleaux-focus-dossier","title":"Dossier — Focus Fléaux","level":2,"blocks":[{"type":"p","style":"Normal","text":"Le wendigo"},{"type":"p","style":"Normal","text":"Nom de la Réalité : --- Nom de la Vérité : Le « roi du givre » Age : « ?? ans » - ?? ans Affiliations : Abominations Nationalité d’origine : _ Ethnie réelle : Revenants"}]},{"id":"fleaux-focus-verite","title":"Informations Vérité — Focus Fléaux","level":2,"audience":"mj","blocks":[{"type":"p","style":"Normal","text":"On ignore qui il ou elle était, quelle espèce, quand, c’est simplement le plus ancien wendigo de la Terre actuellement. De toute évidence, c’est probablement un cadavre de Khinae corrompu. Avec ses cinq mètres et plusieurs tonnes, tout en glace, en os et en bois, c’est une des abominations les plus dangereuse à croiser car sa masse énorme n’est pas une entrave à sa rapidité. Ce monstre colossal est une pure brute d’instinct et de violence, de faim et de rage. Son cri est si puissant qu’il peut arracher une maison de bois et la disloquer sur plusieurs dizaines de mètres. Ce n’est pas une abomination surpuissante seulement c’est un « roi » au sens où il dirige véritablement les autres wendigos qu’il vient à créer quand il tue quelque chose sans le dévorer entièrement. Il obéit visiblement à Miluska, l’Hologramme ne peut pas le dissimuler donc il est caché dans les villages où elle se trouve, dormant jusqu’à ce qu’elle ne l’invoque, pour ne pas tout ravager. Il est tout simplement si affamé qu’il dévore la magie, aucun pouvoir qui n’est pas d’un rang divin ne peut l’affecter, de même, physiquement, s’il est affecté par à peu près tout ce qui existe, il est si résistant qu’un tir de tank ne lui enfonce le torse que de quelques micromètres, il craint donc bien le domaine physique sans aucune résistance surnaturelle mais son corps est si compact que presque personne n’a la force suffisante chez les humains. « Le roi du givre » peut dévorer la chaleur de toute une région, il pourrait être vu comme un atout majeur dans la lutte contre le réchauffement climatique s’il ne devait pas massacrer des centaines de vies pour avoir cette capacité. S’il n’a rien à dévorer, il dévorera les autres wendigo, puis son propre corps. Il est, en vérité, la Voix qu’entent Miluska, loin d’être la grosse bête contrôlée par la Mage il est celui qui contrôle la Mage, l’abomination a une intelligence malsaine et malfaisante quand son corps dort, il a forgé Miluska pour avoir du repos, pour avoir un mage capable de lui octroyer du répit, contrairement aux apparences elle et son culte sont les outils de la Bête, et non l’inverse et « le roi du givre » ne sert ni Siadara ni Vhodhal mais ses propres intérêts, sa propre survie."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}],"navigation":{"group":"Corruption & menaces","groupOrder":80,"subgroup":"Abominations","subgroupOrder":20,"pageOrder":500}},{"id":"pnj-fleaux-ryong-myung-sook","dataset":"verite-fleaux-pnj","category":"Personnages","sourceCategory":"Vérité","title":"RYONG Myung-Sook","source":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Fléaux","Focus Fléaux 2026-09","Vampire","Crawlers (hooker et neurodiver)"],"pnj":{"completeness":"detailed","real_name":"RYONG Myung-Sook","nom_verite":"RYONG Myung-Sook","race":"Vampire","age":"« 26 ans » - ?? ans","origine":"Coréenne","statut":"Crawlers (hooker et neurodiver)","affiliations":"Crawlers (hooker et neurodiver)","relations":[],"identity_keys":["RYONG Myung-Sook","Ryong Myung-Sook"]},"loreBook":{"focusBatch":"fleaux-focus-2026-09-v1","focusSource":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx"},"sections":[{"id":"fleaux-focus-dossier","title":"Dossier — Focus Fléaux","level":2,"blocks":[{"type":"p","style":"Normal","text":"Le roi solaire"},{"type":"p","style":"Normal","text":"Nom de la Réalité : RYONG Myung-Sook Nom de la Vérité : RYONG Myung-Sook Age : « 26 ans » - ?? ans Affiliations : Crawlers (hooker et neurodiver) Nationalité d’origine : Coréenne Ethnie réelle : Vampire"}]},{"id":"fleaux-focus-verite","title":"Informations Vérité — Focus Fléaux","level":2,"audience":"mj","blocks":[{"type":"p","style":"Normal","text":"La famille RYONG est une famille coréenne qui était riche, influente et de noble lignée, elle a émergé durant la période Chosŏn (du XV au XIXième siècle). Ce que la famille ignore, c’est que la fondatrice de sa renommée, Myung-Sook, l’a payé au prix fort. Vampire, elle était une simple courtisane à la base qui a choisi les bons amants, peu fertile étant vampire, elle a arraché des nourrissons au hasard pour faire mine d’avoir une descendance avec ses amants ou maris successifs. La baronne vampirique a su imposer sa famille humaine au fil des siècles mais un jour, pendant les crises de la fin de la période Chosŏn, des chasseurs commencèrent à épurer le territoire de la baronne RYONG, laquelle mena une petite guerre contre eux. Se défendre des chasseurs n’est pas difficile pour les barons vampiriques en général, mais la défaite de Myung-Sook vint d’une trahison, des rivaux vampiriques profitèrent des chasseurs pour la supplanter. Alors qu’elle était pratiquement morte, la créature vampirique, pourchassée, se jeta dans un cimetière et déterra le corps d’un vampire qu’elle avait fait bruler parce qu’il était atteint de la famine blanche, elle avala de ses ossements et se voua à Vhodhal pour survivre. Elle devint momentanément une forme de strygoï-Wendigo, elle massacra les chasseurs avant de trouver sa forme humaine en vomissant les ossements. Bien que contaminée par la famine blanche, elle est maitresse d’elle-même le plus souvent, c’est une baronne mais elle se déclare duchesse des « Elfenbeinblut » même si le roi Stroheim ne la reconnait pas comme telle. Ses objectifs sont assez différents de ceux du roi, qu’elle ne sert pas totalement, en effet, bien qu’elle ait subit les modifications alchimiques et juré une loyauté sans faille, l’unique but de Myung-Sook est d’anéantir Vhodhal’nact et de se libérer de la famine blanche, c’est pourquoi elle a des affinités avec le culte de Thul, espérant pouvoir contrer les pouvoirs du premier Fléau par ceux du second."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}],"navigation":{"group":"Figures de Vérité","groupOrder":70,"subgroup":"Vampires","subgroupOrder":10,"pageOrder":500}},{"id":"pnj-fleaux-am-mleeac","dataset":"verite-fleaux-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Am’Mleeac","source":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Fléaux","Focus Fléaux 2026-09","Fléau supérieur","« Créatures »"],"pnj":{"completeness":"detailed","real_name":"Am’Mleeac","nom_verite":"Am’Mleeac","race":"Fléau supérieur","age":"- ???? ans","origine":"???","statut":"« Créatures »","affiliations":"« Créatures »","relations":[],"identity_keys":["Am’Mleeac"]},"loreBook":{"focusBatch":"fleaux-focus-2026-09-v1","focusSource":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx"},"sections":[{"id":"fleaux-focus-dossier","title":"Dossier — Focus Fléaux","level":2,"blocks":[{"type":"p","style":"Normal","text":"La distorsion du Tout"},{"type":"p","style":"Normal","text":"Nom de la Réalité : _ Nom de la Vérité : Am’Mleeac Age : - ???? ans Affiliations : « Créatures » Nationalité d’origine : ??? Ethnie réelle : Fléau supérieur"}]},{"id":"fleaux-focus-verite","title":"Informations Vérité — Focus Fléaux","level":2,"audience":"mj","blocks":[{"type":"p","style":"Normal","text":"V’Aagor n’a pas engendré des fléaux qu’avec Ux’sharith, Vhadi aussi lui donna d’innombrables engeances malfaisantes et grouillantes. La créature la plus proche de ses créateurs étaient Mleeac, un immense nœud de fibres tentaculaires et obscures ne pouvant pas se déplacer, distordant l’espace pour le faire. Le fléau supérieur semblait inerte pendant des millénaires, placé entre deux dimensions lors d’une distorsion, il est resté endormi, tel un scarabée coincé sous un caillou et décidant de ne plus bouger. Il fut réveillé par un fléau lointain, maitresse des ombres wolféennes, qui, à l’autre bout de la galaxie chercha à dévorer le petit fléau, il s’arracha de l’entre-deux dimension, par instinct de survie. Son retour sur Terre fut d’une rare violence, il provoqua de forts Tsunamis et des lames de fonds dans les abysses, tant et si bien que les cités sous-marines furent ravagées, provoquant un éveil de Thul, un autre fléau qui le dévora aussi en partie. S’il ne reste pas beaucoup du corps initial de Mleeac, sa puissance reste colossale. Il est la seule entité à qui Vhadi peut insuffler son essence, ses pensées, elle se nourrit également de lui, mais en échange, le fléau se sert des mortels pour se régénérer et libérer sa créatrice. Il peut créer de la « sombre vérité » tout comme les autres serviteurs de V’Aagor, il s’en sert néanmoins assez peu. Les prêtres cultistes le servant ne reçoivent pas de pouvoirs, ils ont la promesse d’un paradis pour eux, éternel, sans jugement de leur vie sur Terre, il leur confère aussi une relative immortalité, quand un d’entre eux meurt, s’il prie le Fléau afin de ne pas quitter la Terre, son âme passe dans le corps humain le plus proche, s’il est en vie et fonctionnel, le prêtre change d’identité, hélas si rien n’est en vie sur une distance proportionnelle à la dévotion du prêtre, il décède. Mleeac n’est pas un fléau malfaisant ou destructeur volontairement, comme Vhadhi, sa nature est de déformer et changer les choses, le seul fait de contempler ses statuettes peut provoquer des mutations génétiques, le fait de recevoir sa parole peut carrément faire évoluer le physique comme si des millions d’années d’évolutions d’une espèce se passaient au travers du corps d’un seul individu. Il a une attirance malsaine pour les khinaes et leurs descendants."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}],"navigation":{"group":"Corruption & menaces","groupOrder":80,"subgroup":"Fléaux & figures de Rupture","subgroupOrder":10,"pageOrder":500}},{"id":"pnj-fleaux-dagon","dataset":"verite-fleaux-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Dagon / Aberration Z-19","source":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Fléaux","Focus Fléaux 2026-09","Abomination (abyssaux)"],"pnj":{"completeness":"detailed","real_name":"Aberration Z-19","nom_verite":"« Dagon »","race":"Abomination (abyssaux)","age":"- ????? ans","origine":"abysses","statut":"Fléaux","affiliations":"Fléaux","relations":[],"identity_keys":["Dagon / Aberration Z-19","« Dagon »","Aberration Z-19"]},"loreBook":{"focusBatch":"fleaux-focus-2026-09-v1","focusSource":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx"},"sections":[{"id":"fleaux-focus-dossier","title":"Dossier — Focus Fléaux","level":2,"blocks":[{"type":"p","style":"Normal","text":"Père des abyssaux"},{"type":"p","style":"Normal","text":"Nom de la Réalité : Aberration Z-19 Nom de la Vérité : « Dagon » Age : - ????? ans Affiliations : Fléaux Nationalité d’origine : abysses Ethnie réelle : Abomination (abyssaux)"}]},{"id":"fleaux-focus-verite","title":"Informations Vérité — Focus Fléaux","level":2,"audience":"mj","blocks":[{"type":"p","style":"Normal","text":"L’entité qui est décrite n’a pas vraiment de nom, on l’appelle « Dagon » selon les ouvrages de Lovecraft, car il correspond vaguement à l’idée de la créature. C’est un titanesque homme-poisson à l’apparence terrifiante, ses dents sont longues et transparentes, la lumière dégagée par son corps émane une énergie malsaine qui gèle le temps. Il est l’ancêtre biologique de presque tous les « abyssaux », les hommes-poissons de la Terre et n’a pas d’égal au sein de cette espèce singulière et déformée par Thul. Ces créatures sont surnommées « Thuliens », parce que leur survie et leurs existences ne sont dédiées qu’à leur Fléau de maître. De tous, « Dagon » est un surpuissant fléau mineur, c’est l’âge qui lui confère sa puissance, une certaine ironie puisqu’il n’est pas sensible au temps en théorie. Malgré sa férocité et son gout pour la reproduction, il est d’une intelligence qu’il ne faut pas sous￾estimer, c’est un magicien malgré les apparences et ce sont les lueurs sur son corps qui dégagent la magie suivant sa volonté. Pour ceux qui sont prêts à satisfaire ses désirs, il peut offrir des dons, il peut même sembler généreux, offrant l’immortalité à ceux qui le suivent dans les profondeurs. Mais il ne faut pas s’y tromper, il n’y aura aucun retour après cela, une fois la nature humaine abandonné, la corruption de l’âme entamée, les volontaires finissent comme de simples pions éternels, dont l’existence peut être sacrifiée à loisir selon les besoins de leurs maitres. De tous les « Grands thuliens », Dagon est possiblement le plus loyal à Thul, il n’a jamais établi de plan ou d’ambitions qui ne lui avait pas été insufflé par son maitre. Il est le plus grand ennemi de la reine des Nymphes aquatiques, Amphitrite."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}],"navigation":{"group":"Corruption & menaces","groupOrder":80,"subgroup":"Abominations","subgroupOrder":20,"pageOrder":500}},{"id":"pnj-fleaux-telipinu","dataset":"verite-fleaux-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Telipinu / Aberration Z-75","source":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Fléaux","Focus Fléaux 2026-09","Abomination (myxiniens)"],"pnj":{"completeness":"detailed","real_name":"Aberration Z-75","nom_verite":"« Telepinu »","race":"Abomination (myxiniens)","age":"- ????? ans","origine":"abysses","statut":"Fléaux","affiliations":"Fléaux","relations":[],"identity_keys":["Telipinu / Aberration Z-75","Telipinu","Aberration Z-75","« Telepinu »"]},"loreBook":{"focusBatch":"fleaux-focus-2026-09-v1","focusSource":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx"},"sections":[{"id":"fleaux-focus-dossier","title":"Dossier — Focus Fléaux","level":2,"blocks":[{"type":"p","style":"Normal","text":"Le père des Myxiniens"},{"type":"p","style":"Normal","text":"Nom de la Réalité : Aberration Z-75 Nom de la Vérité : « Telepinu » Age : - ????? ans Affiliations : Fléaux Nationalité d’origine : abysses Ethnie réelle : Abomination (myxiniens)"}]},{"id":"fleaux-focus-verite","title":"Informations Vérité — Focus Fléaux","level":2,"audience":"mj","blocks":[{"type":"p","style":"Normal","text":"« Telipinu » est un autre grand Thulien. Commandant aux « myxiniens », des sortes d’hommes-myxines ou d’hommes-lamproies, il est l’équivalent de « Dagon ». Les Mages qui l’ont rencontré l’ont nommé comme un ancien dieu de l’agriculture, comme Dagon a été nommé. Comme son homologue, c’est une créature énorme et puissante, sa magie immense passe par le mucus qu’il produit, ses adeptes en produisent également, créant un réseau visqueux et gélatineux, parfois, dans les cités sous-marines, le réseau est si vaste que Telipinu semble omniscient et omniprésent. Comme Dagon, il possède de nombreux villages à travers le monde où les cultistes métissés avec son peuple semblent lui vouer un culte. Contrairement à Dagon, le culte de Telipinu se fait passer pour une secte d’une Religion majeure, il en emprunte tous les symboles et les noms, les humains pensent honorer Dieu, Yahvé ou Allah, mais leurs prières n’atteignent jamais les cieux ou les enfers, ils sont prisonniers de l’affreux monstre visqueux. Tout comme Dagon, Telipinu a pour mission de libérer Thul et pour ça il traque activement les Atlantes afin d’obtenir le sang royal nécessaire pour atteindre la prison de leur maitre. Généralement, les cultes de Telipinu s’associent aux agences de voyage ou aux navires et arrangent des naufrages pour trier les visiteurs ainsi piégés avant de chercher si certains sont d’un intérêt quelconque. Telipinu est probablement le seul Thulien à avoir accédé à la clé de la victoire, en effet, en 2035, janvier, il a piégé une certaine Veronica SILVER, venue pour une enquête, après avoir même réussi à s’infiltter dans son corps et son esprit, il pensait avoir réussi à l’inséminer et la contrôler, à la place, il fut tué par la blonde et étant stérile, elle n’eut aucune séquelle de leur rencontre. Déchiré en deux, il continue de la traquer sous la forme d’un enfant nommé Andrew, tandis que ses pouvoirs ont été à sa descendante directe la plus proche de sa mort."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}],"navigation":{"group":"Corruption & menaces","groupOrder":80,"subgroup":"Abominations","subgroupOrder":20,"pageOrder":500}},{"id":"pnj-fleaux-r-sheraag","dataset":"verite-fleaux-pnj","category":"Personnages","sourceCategory":"Vérité","title":"R’Sheraag / Aberration Z-45","source":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Fléaux","Focus Fléaux 2026-09","Rocréenne","« Créatures »"],"pnj":{"completeness":"detailed","real_name":"Aberration Z-45","nom_verite":"R’Sheraag","race":"Rocréenne","age":"« ?? ans » - ?? ans","origine":"???","statut":"« Créatures »","affiliations":"« Créatures »","relations":[],"identity_keys":["R’Sheraag / Aberration Z-45","R’Sheraag","Aberration Z-45"]},"loreBook":{"focusBatch":"fleaux-focus-2026-09-v1","focusSource":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx"},"sections":[{"id":"fleaux-focus-dossier","title":"Dossier — Focus Fléaux","level":2,"blocks":[{"type":"p","style":"Normal","text":"Calamité abyssale"},{"type":"p","style":"Normal","text":"Nom de la Réalité : Aberration Z-45 Nom de la Vérité : R’Sheraag Age : « ?? ans » - ?? ans Affiliations : « Créatures » Nationalité d’origine : ??? Ethnie réelle : Rocréenne"}]},{"id":"fleaux-focus-realite","title":"Informations Réalité — Focus Fléaux","level":2,"blocks":[{"type":"p","style":"Normal","text":"L’ « organisme de surveillance des Aberrations biologiques » (« Biologic aberrations watchdog” BAW) est une sorte d’association d’illuminés de cryptozoologues et autres geeks fans de séries surnaturelles. En 2019, l’organisme a alerté les gouvernement qu’une créature avait été filmée s’attaquer à un bateau avant qu’une douzaine de chalutiers ne disparaissent dans l’Océan Pacifique. La presse n’a jamais relégué l’alerte et tout cela fut pris pour une tentative de promotion foireuse pour le film Godzilla 2 qui venait de sortir."}]},{"id":"fleaux-focus-verite","title":"Informations Vérité — Focus Fléaux","level":2,"audience":"mj","blocks":[{"type":"p","style":"Normal","text":"R’Sheraag est le plus grand leader des « rocréens obscurs ». On ignore son âge, les rocréens terrestres et galactiques ignorent son existence, en revanche, il est connu des plus anciennes créatures tels que les dieux ou les exilés. Avec ses deux mètres, il n’a rien d’un rocréen conventionnel, il dispose de bioarmure de combat de taille titanesque ayant la forme d’un calamar géant ou d’un vampyroteuthis, qu’il utilise pour couler des navires ou attaquer les bases sousmarines humaines. Il est le gardien de Ringeveled, une cité sous-marine d’abyssaux et de rocréens obscurs où une porte sur l’Ombre-Monde se trouvait avant qu’un vampire ancien ne la ferme. Son unique but est de faire libérer et réveiller son Créateur. Sa puissance psychique est colossale mais étant donné son âge avancé, très avancé même, il n’aurait pas une régénération aussi grande que les rocréens normaux, ce serait pourquoi il s’en nourrit, offrant les humains aux abyssaux et dévorant les rocréens quand il ramène des navires dans sa sombre cité. Ses sombres maitres lui auraient octroyé un Mageius, greffé à son corps douloureusement, par des pouvoirs si chaotiques et interdits qu’aucun Mage ni aucun Dieu n’aurait osé le tenter ainsi. C’est le plus jeune des grands Thuliens néanmoins, il s’entend assez mal avec Telipinu ou Dagon, car il a une volonté d’hégémonie totale des rocréens sombres sur les profondeurs, il s’estime le seul héritier digne du nom pour servir Thul qui a créé les rocréens à son image, en vérité, une coïncidence de l’évolution."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}],"navigation":{"group":"Corruption & menaces","groupOrder":80,"subgroup":"Abominations","subgroupOrder":20,"pageOrder":500}},{"id":"pnj-fleaux-dsherra-neth","dataset":"verite-fleaux-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Dsherra'neth / Aberration Z-47","source":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Fléaux","Focus Fléaux 2026-09","Rocréenne","Abominations"],"pnj":{"completeness":"detailed","real_name":"Aberration Z-47","nom_verite":"Dsherra'neth","race":"Rocréenne","age":"« ??? ans » -","origine":"abyssale","statut":"Abominations","affiliations":"Abominations","relations":[],"identity_keys":["Dsherra'neth / Aberration Z-47","Dsherra'neth","Aberration Z-47"]},"loreBook":{"focusBatch":"fleaux-focus-2026-09-v1","focusSource":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx"},"sections":[{"id":"fleaux-focus-dossier","title":"Dossier — Focus Fléaux","level":2,"blocks":[{"type":"p","style":"Normal","text":"Mère poulpe"},{"type":"p","style":"Normal","text":"Nom de la Réalité : Aberration Z-47 Nom de la Vérité : Dsherra'neth Age : « ??? ans » - Affiliations : Abominations Nationalité d’origine : abyssale Ethnie réelle : Rocréenne"}]},{"id":"fleaux-focus-realite","title":"Informations Réalité — Focus Fléaux","level":2,"blocks":[{"type":"p","style":"Normal","text":"L’aberration Z-47 a été observée trois fois, elle est décrite comme une sorte de sirène extrêmement séduisante aux longs cheveux d’un bleu tirant sur le violet. Elle a été aperçue en 1795 et aurait dévoré un équipage entier. Plus récemment en 2031, elle a été aperçue sur une plage, dépeçant un cadavre de baleine en Scandinavie."}]},{"id":"fleaux-focus-verite","title":"Informations Vérité — Focus Fléaux","level":2,"audience":"mj","blocks":[{"type":"p","style":"Normal","text":"Bien qu’elle parvienne abuser les mortels en revêtant une apparence sensuelle et attirante, Dsherra est une chasseuse des abysses et elle traque les mortels sur la mer et la plage. Son unique but est d’attirer le plus de mortels, homme ou femme à la suivre dans l’eau, telle une sirène, afin de les ramener comme esclave à la grande cité sous-marine, les échangeant avec les homme-poissons abyssaux, permettant la reproduction et la création de loyaux partisans en surface une fois qu’ils auront été ramenés avec leurs engeances. Elle est farouchement opposée aux méthodes de Mrallgirn'cllg, le plus grand chasseur des abysses, qui dévore des créatures surnaturelles et traque els atlantes. Si elle déteste les Muliens, elle essaye souvent de discuter avec les Atlantes quand elle a la chance d’en trouver un même si on unique but est de s’accoupler avec eux afin de corrompre l’espèce et de la dévoyer pour le culte de Thul. Elle est la mère de Telipinu, une engeance de fléau, que le grand Fléau Thul eu avec elle. La mort du fléau mineur a provoqué sa colère infinie. Elle traque elle aussi les coupables dont elle connait les visages mais pas vraiment plus, une blonde et un prêtre essentiellement. Elle a déjà décidé de la punition de chacun, ayant encore de l’essence de Thul pour procréer, elle a décidé que la blonde porterait le prochain enfant de fléau, tandis que le prêtre serait le père d’innombrables rocréens hybrides des abysses, dont il portera les œufs assurément. Plus elle chasse la blonde et le prêtre, plus elle s’enfonce dans les terres, elle a ainsi essayé d’entrer dans la tour Austin de nextar corporation avant de préférer en sortir."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}],"navigation":{"group":"Corruption & menaces","groupOrder":80,"subgroup":"Abominations","subgroupOrder":20,"pageOrder":500}},{"id":"pnj-fleaux-pestiria","dataset":"verite-fleaux-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Pestiria — Peste des vases","source":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Fléaux","Focus Fléaux 2026-09","Thalsiosse","Abominations"],"pnj":{"completeness":"detailed","real_name":"Pestiria — Peste des vases","nom_verite":"Pestiria","race":"Thalsiosse","age":"« ??? »","origine":"","statut":"Abominations","affiliations":"Abominations","relations":[],"identity_keys":["Pestiria — Peste des vases","Peste des vases","Pestiria"]},"loreBook":{"focusBatch":"fleaux-focus-2026-09-v1","focusSource":"TUC_Vérité_ les créatures_focus  sur les Fléaux(2).docx"},"sections":[{"id":"fleaux-focus-dossier","title":"Dossier — Focus Fléaux","level":2,"blocks":[{"type":"p","style":"Normal","text":"La mère des maladies"},{"type":"p","style":"Normal","text":"Nom de la Réalité : _ Nom de la Vérité : Pestiria Age : « ??? » Affiliations : Abominations Nationalité d’origine : _ Ethnie réelle : Thalsiosse"}]},{"id":"fleaux-focus-verite","title":"Informations Vérité — Focus Fléaux","level":2,"audience":"mj","blocks":[{"type":"p","style":"Normal","text":"Les Thalsios ne sont pas une espèce s’étant lancée dans le voyage stellaire depuis aussi longtemps qu’elle n’existe, cependant « Pestiria » est indubitablement une thalsiosse à l’origine. Peut-être issue d’une époque reculée, elle a été arrachée de son monde natal par le fléau Thul, comme une poussière emmenée dans le sillon d’un être colossal. Jetée sur Terre elle a enduré des milliers de douleurs en survivant, déformée par l’énergie malsaine du Fléau. Elle est devenue la vase et la boue dans laquelle son corps fondait, elle n’a plus de forme que celle d’un immense amas de vase, de boue, d’excroissances et de pustules où sa minuscule tête aux yeux luisant peut apparaitre parfois. Elle est dotée de puissants pouvoirs mentaux et le muscus vaseux nauséabond qu’elle laisse dans son sillage est aussi putride qu’il n’est densément magique mais la personne qui viendrait le toucher finirait rapidement par le regretter. En effet, acide et puant, ce mucus est porteur de toutes les maladies du monde, toutes les afflictions dévorent Pestiria en permanence et la font gémir de douleur et toutes les maladies, virus, bactéries, champignons et autres parasites se vautrent dans le mucus acide et tiède. Ses pustules recouvrent ceux qui respirent son haleine, dans le pue et la vase qui se logent dans la peau de ses victimes, les spores de son haleine portent ses œufs, sphériques et microscopiques, des œufs de batraciens allant ronger par leur acidité la peau où ils sont, le « têtard de peste » allant par la suite dévorer la chair en dessous, grêlant la peau et la laissant à jamais parcourue de trous comme le dos d’un crapaud pipa pipa. Elle ne sert pas à proprement parler le Fléau Thul, elle essaye simplement de survivre, mais les cultistes du Fléau la vénèrent comme la « mère des maladies » et elle cherche à joindre les villes en espérant un jour être sauvée de son état pitoyable qu’aucun dieu ni Mage ne saurait restaurer, hélas pour elle. Elle n’a aucune considération pour ses « têtards de peste », ignorant ce qui la fertilise en permanence, ces créatures maléfiques n’ayant pour seul objectif que de dévorer de la chair. A la fois chassée par les chasseurs surnaturels et ceux d’aliens, elle est vraisemblablement immortelle et pratiquement invulnérable étant donné à quel point elle est virulente."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}],"navigation":{"group":"Corruption & menaces","groupOrder":80,"subgroup":"Abominations","subgroupOrder":20,"pageOrder":500}}] as Array<Record<string, any>>;
